{"command":"mkdir -p /workspace/tmp && cd /workspace && cat > node.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

// Kind mirrors the YAML node kinds.
type Kind uint32

const (
	DocumentNode Kind = 1 << iota
	SequenceNode
	MappingNode
	ScalarNode
	AliasNode
)

// Style mirrors the YAML node styles.
type Style uint32

const (
	TaggedStyle Style = 1 << iota
	DoubleQuotedStyle
	SingleQuotedStyle
	LiteralStyle
	FoldedStyle
	FlowStyle
)

// Node is the in-memory representation of a data node (yaml like),
// with extra bookkeeping needed by the expression evaluator.
type Node struct {
	Kind  Kind
	Style Style

	Tag    string
	Value  string
	Anchor string
	Alias  *Node

	Content []*Node

	HeadComment string
	LineComment string
	FootComment string

	Line   int
	Column int

	Parent *Node
	Key    *Node

	LeadingContent  string
	TrailingContent string

	Document  uint
	Filename  string
	FileIndex int

	IsMapKey         bool
	EvaluateTogether bool
}

func (n *Node) String() string {
	return fmt.Sprintf("D%d, P%v, %s (%s)::%s", n.GetDocument(), n.GetNicePath(), kindString(n.Kind), n.Tag, n.Value)
}

func kindString(k Kind) string {
	switch k {
	case SequenceNode:
		return "SequenceNode"
	case MappingNode:
		return "MappingNode"
	case ScalarNode:
		return "ScalarNode"
	case AliasNode:
		return "AliasNode"
	case DocumentNode:
		return "DocumentNode"
	}
	return "unknown"
}

func (n *Node) GetDocument() uint {
	if n.Parent != nil {
		return n.Parent.GetDocument()
	}
	return n.Document
}

func (n *Node) GetFileIndex() int {
	if n.Parent != nil {
		return n.Parent.GetFileIndex()
	}
	return n.FileIndex
}

func (n *Node) GetFilename() string {
	if n.Parent != nil {
		return n.Parent.GetFilename()
	}
	return n.Filename
}

func (n *Node) GetKey() string {
	keyPrefix := ""
	if n.IsMapKey {
		keyPrefix = "key-"
	}
	key := ""
	if n.Key != nil {
		key = n.Key.Value
	}
	return fmt.Sprintf("%v%v - %v", keyPrefix, n.GetDocument(), key)
}

// GetPath returns the path of the node from the root.
func (n *Node) GetPath() []interface{} {
	if n.Parent == nil {
		return []interface{}{}
	}
	path := n.Parent.GetPath()
	if n.Key != nil {
		if n.Key.Tag == "!!int" {
			idx, err := strconv.Atoi(n.Key.Value)
			if err == nil {
				return append(path, idx)
			}
		}
		return append(path, n.Key.Value)
	}
	return path
}

func (n *Node) GetNicePath() string {
	path := n.GetPath()
	parts := make([]string, len(path))
	for i, p := range path {
		parts[i] = fmt.Sprintf("%v", p)
	}
	return strings.Join(parts, ".")
}

func (n *Node) IsSelfOrParentOfTypes(kinds ...Kind) bool {
	cur := n
	for cur != nil {
		for _, k := range kinds {
			if cur.Kind == k {
				return true
			}
		}
		cur = cur.Parent
	}
	return false
}

// CreateChild creates a node which is a child of this node (inherits doc info).
func (n *Node) CreateChild() *Node {
	return &Node{Parent: n}
}

func (n *Node) CreateReplacement(kind Kind, tag string, value string) *Node {
	return &Node{
		Kind:           kind,
		Tag:            tag,
		Value:          value,
		Parent:         n.Parent,
		Key:            n.Key,
		LeadingContent: n.LeadingContent,
		IsMapKey:       n.IsMapKey,
	}
}

func (n *Node) CreateReplacementWithComments(kind Kind, tag string, style Style) *Node {
	r := n.CreateReplacement(kind, tag, "")
	r.Style = style
	r.HeadComment = n.HeadComment
	r.LineComment = n.LineComment
	r.FootComment = n.FootComment
	return r
}

func (n *Node) AddKeyValueChild(rawKey *Node, rawValue *Node) (*Node, *Node) {
	key := rawKey.Copy()
	key.Parent = n
	key.IsMapKey = true
	value := rawValue.Copy()
	value.Parent = n
	value.Key = key
	n.Content = append(n.Content, key, value)
	return key, value
}

func (n *Node) AddChild(rawValue *Node) *Node {
	value := rawValue.Copy()
	value.Parent = n
	idx := len(n.Content)
	value.Key = createStringScalar(strconv.Itoa(idx))
	value.Key.Tag = "!!int"
	n.Content = append(n.Content, value)
	return value
}

func (n *Node) AddChildren(children []*Node) {
	if n.Kind == MappingNode {
		for i := 0; i+1 < len(children); i += 2 {
			n.AddKeyValueChild(children[i], children[i+1])
		}
		if len(children)%2 == 1 {
			n.AddChild(children[len(children)-1])
		}
	} else {
		for _, c := range children {
			n.AddChild(c)
		}
	}
}

func (n *Node) SetParent(parent *Node) {
	n.Parent = parent
}

// Copy returns a deep copy of the node (children copied too).
func (n *Node) Copy() *Node {
	return n.doCopy(true)
}

// CopyWithoutContent returns a shallow copy without children.
func (n *Node) CopyWithoutContent() *Node {
	return n.doCopy(false)
}

func (n *Node) doCopy(cloneContent bool) *Node {
	if n == nil {
		return nil
	}
	c := &Node{
		Kind:             n.Kind,
		Style:            n.Style,
		Tag:              n.Tag,
		Value:            n.Value,
		Anchor:           n.Anchor,
		Alias:            n.Alias,
		HeadComment:      n.HeadComment,
		LineComment:      n.LineComment,
		FootComment:      n.FootComment,
		Line:             n.Line,
		Column:           n.Column,
		Parent:           n.Parent,
		Key:              n.Key,
		LeadingContent:   n.LeadingContent,
		TrailingContent:  n.TrailingContent,
		Document:         n.Document,
		Filename:         n.Filename,
		FileIndex:        n.FileIndex,
		IsMapKey:         n.IsMapKey,
		EvaluateTogether: n.EvaluateTogether,
	}
	if cloneContent && len(n.Content) > 0 {
		c.Content = make([]*Node, len(n.Content))
		for i, child := range n.Content {
			cc := child.doCopy(true)
			cc.Parent = c
			if n.Kind == MappingNode && i%2 == 1 {
				cc.Key = c.Content[i-1]
			}
			c.Content[i] = cc
		}
	}
	return c
}

// UpdateFrom copies the value/content of other into this node, preserving identity.
func (n *Node) UpdateFrom(other *Node, prefs assignPreferences) {
	n.UpdateAttributesFrom(other, prefs)
	n.Content = make([]*Node, 0, len(other.Content))
	n.Alias = other.Alias
	for i, child := range other.Content {
		cc := child.Copy()
		cc.Parent = n
		if other.Kind == MappingNode && i%2 == 1 {
			cc.Key = n.Content[i-1]
		}
		n.Content = append(n.Content, cc)
	}
}

func (n *Node) UpdateAttributesFrom(other *Node, prefs assignPreferences) {
	if n.Kind != other.Kind {
		// clear out the contents when kind changes
		n.Content = nil
	}
	n.Kind = other.Kind
	n.Tag = other.Tag
	n.Value = other.Value
	if other.Kind != AliasNode {
		n.Alias = nil
	}
	if !prefs.OnlyWriteNull {
		if !prefs.DontOverWriteAnchor {
			n.Anchor = other.Anchor
		}
	}
	// merge comments
	if !prefs.ClobberCustomTags {
		// keep custom tags
	}
	if prefs.OnlyWriteNull {
		return
	}
	if other.HeadComment != "" {
		n.HeadComment = other.HeadComment
	}
	if other.LineComment != "" {
		n.LineComment = other.LineComment
	}
	if other.FootComment != "" {
		n.FootComment = other.FootComment
	}
	if !prefs.KeepStyle || other.Style != 0 {
		n.Style = other.Style
	}
}

func (n *Node) guessTagFromCustomType() string {
	if strings.HasPrefix(n.Tag, "!!") {
		return n.Tag
	}
	if n.Value == "" {
		return ""
	}
	return guessTag(n.Value)
}

func createStringScalar(value string) *Node {
	return &Node{Kind: ScalarNode, Tag: "!!str", Value: value}
}

func createScalar(tag string, value string) *Node {
	return &Node{Kind: ScalarNode, Tag: tag, Value: value}
}

func createBool(b bool) *Node {
	if b {
		return &Node{Kind: ScalarNode, Tag: "!!bool", Value: "true"}
	}
	return &Node{Kind: ScalarNode, Tag: "!!bool", Value: "false"}
}

func createNull() *Node {
	return &Node{Kind: ScalarNode, Tag: "!!null", Value: "null"}
}

func createMap() *Node {
	return &Node{Kind: MappingNode, Tag: "!!map"}
}

func createSeq() *Node {
	return &Node{Kind: SequenceNode, Tag: "!!seq"}
}

func (n *Node) IsTruthy() bool {
	if n == nil {
		return false
	}
	if n.Kind == AliasNode && n.Alias != nil {
		return n.Alias.IsTruthy()
	}
	if n.Tag == "!!null" {
		return false
	}
	if n.Kind == ScalarNode && n.Tag == "!!bool" {
		return n.Value == "true" || n.Value == "True" || n.Value == "TRUE"
	}
	return true
}

// unwrapAlias follows alias nodes.
func unwrapAlias(n *Node) *Node {
	for n != nil && n.Kind == AliasNode && n.Alias != nil {
		n = n.Alias
	}
	return n
}

// mapKeyIndex finds the index of a key node in a mapping.
func (n *Node) findKeyIndex(key string) int {
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key {
			return i
		}
	}
	return -1
}
EOF
echo done"}

