func literalToken(val interface{}, str string) *token {
	node := &Node{Kind: ScalarNode, Value: str}
	switch v := val.(type) {
	case bool:
		node.Tag = "!!bool"
	case int64:
		node.Tag = "!!int"
	case float64:
		node.Tag = "!!float"
	case string:
		node.Tag = "!!str"
		_ = v
	case nil:
		node.Tag = "!!null"
	}
	op := &Operation{OperationType: valueOpType, Value: val, StringValue: str, CandidateNode: node}
