func traverseHandler(match string, groups []string) ([]*token, error) {
	value := match[1:]
	prefs := traversePreferences{}
	if strings.HasSuffix(value, "?") {
		prefs.OptionalTraverse = true
		value = value[:len(value)-1]
	}
	if len(value) >= 2 && strings.HasPrefix(value, `"`) && strings.HasSuffix(value, `"`) {
		value = value[1 : len(value)-1]
	}
	if value == "" {
		// self
		return []*token{{TokenType: operationToken, Operation: &Operation{OperationType: selfReferenceOpType}, CheckForPostTraverse: false}}, nil
	}
	node := &Node{Kind: ScalarNode, Tag: "!!str", Value: value}
	op := &Operation{OperationType: traversePathOpType, Value: value, StringValue: value, CandidateNode: node, Preferences: prefs}
