func numberHandler(match string, groups []string) ([]*token, error) {
	var tok *token
	if strings.HasPrefix(match, "0x") || strings.HasPrefix(match, "0X") {
		v, err := strconv.ParseInt(match[2:], 16, 64)
		if err != nil {
			return nil, err
		}
		tok = literalToken(v, match)
		return []*token{tok}, nil
	}
	if strings.ContainsAny(match, ".eE") {
		f, err := strconv.ParseFloat(match, 64)
		if err != nil {
			return nil, err
		}
