		{"splitdoc", simpleOp(splitDocumentOpType)},
		{"to_number", simpleOp(toNumberOpType)},
		{"tonumber", simpleOp(toNumberOpType)},
		{"to_string", simpleOp(toStringOpType)},
		{"tostring", simpleOp(toStringOpType)},
		{"upcase", opWithPrefs(changeCaseOpType, changeCasePrefs{ToUpperCase: true})},
		{"downcase", opWithPrefs(changeCaseOpType, changeCasePrefs{ToUpperCase: false})},
		{"trim", simpleOp(trimOpType)},
		{"split", simpleOp(splitStringOpType)},
		{"join", simpleOp(joinStringOpType)},
		{"sub", simpleOp(subStringOpType)},
		{"test", simpleOp(testOpType)},
		{"match", simpleOp(matchOpType)},
		{"capture", simpleOp(captureOpType)},
		{"format_datetime", simpleOp(formatDateTimeOpType)},
		{"now", simpleOp(nowOpType)},
		{"tz", simpleOp(tzOpType)},
		{"from_unix", simpleOp(fromUnixOpType)},
		{"to_unix", simpleOp(toUnixOpType)},
		{"shuffle", simpleOp(shuffleOpType)},
		{"kind", simpleOp(getKindOpType)},
		{"ireduce", simpleOp(reduceOpType)},
		{"pivot", simpleOp(pivotOpType)},
		{"system", simpleOp(systemOpType)},
		{"not", simpleOp(notOpType)},
		{"and", simpleOp(andOpType)},
		{"or", simpleOp(orOpType)},
		{"as", simpleOp(assignVariableOpType)},
		{"true", func(m string, g []string) ([]*token, error) { return []*token{literalToken(true, "true")}, nil }},
		{"false", func(m string, g []string) ([]*token, error) { return []*token{literalToken(false, "false")}, nil }},
		{"null", func(m string, g []string) ([]*token, error) { return []*token{literalToken(nil, "null")}, nil }},
		{"~", func(m string, g []string) ([]*token, error) { return []*token{literalToken(nil, "~")}, nil }},
	}
	// longest match first to emulate keyword precedence
	for i := 0; i < len(keywords); i++ {
		for j := i + 1; j < len(keywords); j++ {
			if len(keywords[j].name) > len(keywords[i].name) {
				keywords[i], keywords[j] = keywords[j], keywords[i]
			}
		}
	}
	for _, k := range keywords {
		rule(regexp.QuoteMeta(k.name), k.handler)
	}
}

// lexError mirrors the participle lexer error format.
func lexError(line, col int, remaining string) error {
	text := remaining
	runes := []rune(text)
	if len(runes) > 16 {
		text = string(runes[:16]) + "..."
	}
	return fmt.Errorf("%d:%d: lexer: invalid input text %s", line, col, strconv.Quote(text))
}

func tokenise(expression string) ([]*token, error) {
	if len(lexRules) == 0 {
		initLexer()
	}
	var tokens []*token
	pos := 0
	line, col := 1, 1
	for pos < len(expression) {
		remaining := expression[pos:]
		matched := false
		for _, r := range lexRules {
			loc := r.re.FindStringSubmatchIndex(remaining)
			if loc == nil || loc[1] == 0 {
				continue
			}
			match := remaining[:loc[1]]
			matched = true
			if r.handler != nil {
				groups := make([]string, 0)
				toks, err := r.handler(match, groups)
				if err != nil {
					return nil, err
				}
				tokens = append(tokens, toks...)
			}
			// advance position
			for _, ch := range match {
				if ch == '\n' {
					line++
					col = 1
				} else {
					col++
				}
			}
			pos += len(match)
			break
		}
		if !matched {
			return nil, lexError(line, col, remaining)
		}
	}
	return tokens, nil
}
EOF
echo ok"}

