package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

type tokenType uint32

const (
	operationToken tokenType = 1 << iota
	openBracket
	closeBracket
	openCollect
	closeCollect
	openCollectObject
	closeCollectObject
	traverseArrayCollect
)

type token struct {
	TokenType            tokenType
	Operation            *Operation
	AssignOperation      *Operation // e.g. tag=, style=
	CheckForPostTraverse bool
	Match                string
}

func (t *token) toString(detail bool) string {
	switch t.TokenType {
	case operationToken:
		if detail {
			return t.Operation.toString()
		}
		return t.Operation.toString()
	case openBracket:
		return "("
	case closeBracket:
		return ")"
	case openCollect:
		return "["
	case closeCollect:
		return "]"
	case openCollectObject:
		return "{"
	case closeCollectObject:
		return "}"
	case traverseArrayCollect:
		return ".["
	}
	return "NFI"
}

type lexRule struct {
	re      *regexp.Regexp
	handler func(match string, groups []string) ([]*token, error)
}

var lexRules []lexRule

func rule(pattern string, handler func(match string, groups []string) ([]*token, error)) {
	lexRules = append(lexRules, lexRule{re: regexp.MustCompile(`\A(?:` + pattern + `)`), handler: handler})
}

func simpleOp(opType *operationType) func(string, []string) ([]*token, error) {
	return func(match string, groups []string) ([]*token, error) {
		return []*token{{TokenType: operationToken, Operation: &Operation{OperationType: opType}, CheckForPostTraverse: opType.CheckForPostTraverse}}, nil
	}
}

func opWithPrefs(opType *operationType, prefs interface{}) func(string, []string) ([]*token, error) {
	return func(match string, groups []string) ([]*token, error) {
		return []*token{{TokenType: operationToken, Operation: &Operation{OperationType: opType, Preferences: prefs}, CheckForPostTraverse: opType.CheckForPostTraverse}}, nil
	}
}

func opTokenOnly(opType *operationType, prefs interface{}, value interface{}, strValue string) *token {
	return &token{TokenType: operationToken, Operation: &Operation{OperationType: opType, Preferences: prefs, Value: value, StringValue: strValue}, CheckForPostTraverse: opType.CheckForPostTraverse}
}

func literalToken(val interface{}, str string) *token {
	node := &Node{Kind: ScalarNode, Value: str}
	switch v := val.(type) {
	case bool:
		node.Tag = "!!bool"
	case int64:
		node.Tag = "!!int"
	case float64:
		node.Tag = "!!float"
	case string:
		node.Tag = "!!str"
		_ = v
	case nil:
		node.Tag = "!!null"
	}
	op := &Operation{OperationType: valueOpType, Value: val, StringValue: str, CandidateNode: node}
	return &token{TokenType: operationToken, Operation: op}
}

func simpleToken(tt tokenType, check bool) func(string, []string) ([]*token, error) {
	return func(match string, groups []string) ([]*token, error) {
		return []*token{{TokenType: tt, CheckForPostTraverse: check, Match: match}}, nil
	}
}

func assignableOp(getOp *operationType, assignOp *operationType) func(string, []string) ([]*token, error) {
	return func(match string, groups []string) ([]*token, error) {
		return []*token{{TokenType: operationToken, Operation: &Operation{OperationType: getOp}, AssignOperation: &Operation{OperationType: assignOp}, CheckForPostTraverse: getOp.CheckForPostTraverse}}, nil
	}
}

func assignableOpWithPrefs(getOp *operationType, assignOp *operationType, prefs interface{}) func(string, []string) ([]*token, error) {
	return func(match string, groups []string) ([]*token, error) {
		return []*token{{TokenType: operationToken, Operation: &Operation{OperationType: getOp, Preferences: prefs}, AssignOperation: &Operation{OperationType: assignOp, Preferences: prefs}, CheckForPostTraverse: getOp.CheckForPostTraverse}}, nil
	}
}

func traverseHandler(match string, groups []string) ([]*token, error) {
	value := match[1:]
	prefs := traversePreferences{}
	if strings.HasSuffix(value, "?") {
		prefs.OptionalTraverse = true
		value = value[:len(value)-1]
	}
	if len(value) >= 2 && strings.HasPrefix(value, `"`) && strings.HasSuffix(value, `"`) {
		value = value[1 : len(value)-1]
	}
	if value == "" {
		// self
		return []*token{{TokenType: operationToken, Operation: &Operation{OperationType: selfReferenceOpType}, CheckForPostTraverse: false}}, nil
	}
	node := &Node{Kind: ScalarNode, Tag: "!!str", Value: value}
	op := &Operation{OperationType: traversePathOpType, Value: value, StringValue: value, CandidateNode: node, Preferences: prefs}
	return []*token{{TokenType: operationToken, Operation: op, CheckForPostTraverse: true}}, nil
}

func numberHandler(match string, groups []string) ([]*token, error) {
	var tok *token
	if strings.HasPrefix(match, "0x") || strings.HasPrefix(match, "0X") {
		v, err := strconv.ParseInt(match[2:], 16, 64)
		if err != nil {
			return nil, err
		}
		tok = literalToken(v, match)
		return []*token{tok}, nil
	}
	if strings.ContainsAny(match, ".eE") {
		f, err := strconv.ParseFloat(match, 64)
		if err != nil {
			return nil, err
		}
		tok = literalToken(f, match)
		return []*token{tok}, nil
	}
	v, err := strconv.ParseInt(match, 10, 64)
	if err != nil {
		return nil, err
	}
	tok = literalToken(v, match)
	return []*token{tok}, nil
}

func unescapeString(s string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			n := s[i+1]
			switch n {
			case 'n':
				sb.WriteByte('\n')
				i++
				continue
			case 't':
				sb.WriteByte('\t')
				i++
				continue
			case 'r':
				sb.WriteByte('\r')
				i++
				continue
			case 'b':
				sb.WriteByte('\b')
				i++
				continue
			case 'f':
				sb.WriteByte('\f')
				i++
				continue
			case '"':
				sb.WriteByte('"')
				i++
				continue
			case '\\':
				sb.WriteByte('\\')
				i++
				continue
			}
		}
		sb.WriteByte(c)
	}
	return sb.String()
}

func stringHandler(match string, groups []string) ([]*token, error) {
	inner := match[1 : len(match)-1]
	value := unescapeString(inner)
	node := &Node{Kind: ScalarNode, Tag: "!!str", Value: value}
	op := &Operation{OperationType: valueOpType, Value: value, StringValue: value, CandidateNode: node}
	if strings.Contains(value, `\(`) && stringInterpolationEnabled {
		op = &Operation{OperationType: stringInterpolationOpType, Value: value, StringValue: value, CandidateNode: node}
	}
	return []*token{{TokenType: operationToken, Operation: op}}, nil
}

func variableHandler(match string, groups []string) ([]*token, error) {
	name := match[1:]
	op := &Operation{OperationType: getVariableOpType, StringValue: name}
	return []*token{{TokenType: operationToken, Operation: op, CheckForPostTraverse: true}}, nil
}

func envHandler(match string, groups []string) ([]*token, error) {
	// env(X) or strenv(X)
	open := strings.Index(match, "(")
	name := match[open+1 : len(match)-1]
	prefs := envOpPreferences{StringValue: strings.HasPrefix(match, "strenv")}
	op := &Operation{OperationType: envOpType, Value: name, StringValue: name, Preferences: prefs}
	return []*token{{TokenType: operationToken, Operation: op, CheckForPostTraverse: true}}, nil
}

func envsubstHandler(match string, groups []string) ([]*token, error) {
	prefs := envSubstPreferences{}
	if strings.Contains(match, "(") {
		inner := match[strings.Index(match, "(")+1 : len(match)-1]
		for _, part := range regexp.MustCompile(`[\s,]+`).Split(inner, -1) {
			switch strings.TrimSpace(part) {
			case "ne":
				prefs.NoEmpty = true
			case "nu":
				prefs.NoUnset = true
			case "ff":
				prefs.FailFast = true
			}
		}
	}
	op := &Operation{OperationType: envSubstOpType, Preferences: prefs}
	return []*token{{TokenType: operationToken, Operation: op}}, nil
}

func encodeWithIndentHandler(format string) func(string, []string) ([]*token, error) {
	return func(match string, groups []string) ([]*token, error) {
		indent := 2
		if strings.Contains(match, "(") {
			inner := match[strings.Index(match, "(")+1 : len(match)-1]
			i, err := strconv.Atoi(inner)
			if err != nil {
				return nil, err
			}
			indent = i
		}
		prefs := encoderPreferences{format: format, indent: indent}
		op := &Operation{OperationType: encodeOpType, Preferences: prefs}
		return []*token{{TokenType: operationToken, Operation: op}}, nil
	}
}

func encodeHandler(format string) func(string, []string) ([]*token, error) {
	return func(match string, groups []string) ([]*token, error) {
		prefs := encoderPreferences{format: format, indent: 2}
		op := &Operation{OperationType: encodeOpType, Preferences: prefs}
		return []*token{{TokenType: operationToken, Operation: op}}, nil
	}
}

func decodeHandler(format string) func(string, []string) ([]*token, error) {
	return func(match string, groups []string) ([]*token, error) {
		prefs := decoderPreferences{format: format}
		op := &Operation{OperationType: decodeOpType, Preferences: prefs}
		return []*token{{TokenType: operationToken, Operation: op}}, nil
	}
}

func flattenHandler(match string, groups []string) ([]*token, error) {
	depth := -1
	if strings.Contains(match, "(") {
		inner := match[strings.Index(match, "(")+1 : len(match)-1]
		if inner != "" {
			i, err := strconv.Atoi(inner)
			if err != nil {
				return nil, err
			}
			depth = i
		}
	}
	op := &Operation{OperationType: flattenOpType, Preferences: flattenPreferences{depth: depth}}
	return []*token{{TokenType: operationToken, Operation: op, CheckForPostTraverse: true}}, nil
}

func parentHandler(match string, groups []string) ([]*token, error) {
	level := 1
	if strings.Contains(match, "(") {
		inner := match[strings.Index(match, "(")+1 : len(match)-1]
		if inner != "" {
			i, err := strconv.Atoi(inner)
			if err != nil {
				return nil, err
			}
			level = i
		}
	}
	op := &Operation{OperationType: getParentOpType, Preferences: parentOpPreferences{Level: level}}
	return []*token{{TokenType: operationToken, Operation: op, CheckForPostTraverse: true}}, nil
}

func multiplyHandler(match string, groups []string) ([]*token, error) {
	prefs := multiplyPreferences{}
	flags := match[1:]
	prefs.AppendArrays = strings.Contains(flags, "+")
	prefs.TraversePrefs = traversePreferences{DontFollowAlias: true}
	prefs.AssignPrefs = assignPreferences{}
	if strings.Contains(flags, "?") {
		prefs.AssignPrefs.OnlyWriteNull = true
	}
	if strings.Contains(flags, "n") {
		prefs.AssignPrefs.OnlyWriteNull = true
	}
	if strings.Contains(flags, "d") {
		prefs.DeepMergeArrays = true
	}
	if strings.Contains(flags, "c") {
		prefs.AssignPrefs.ClobberCustomTags = true
	}
	op := &Operation{OperationType: multiplyOpType, Preferences: prefs, StringValue: match}
	return []*token{{TokenType: operationToken, Operation: op}}, nil
}

func loadHandler(match string, groups []string) ([]*token, error) {
	var prefs loadPrefs
	switch match {
	case "load":
		prefs = loadPrefs{loadAsString: false, decoder: "yaml"}
	case "strload", "load_str":
		prefs = loadPrefs{loadAsString: true}
	case "load_base64":
		prefs = loadPrefs{decoder: "base64"}
	case "load_props":
		prefs = loadPrefs{decoder: "props"}
	case "load_xml":
		prefs = loadPrefs{decoder: "xml"}
	}
	op := &Operation{OperationType: loadOpType, Preferences: prefs}
	return []*token{{TokenType: operationToken, Operation: op, CheckForPostTraverse: true}}, nil
}

func initLexer() {
	rule(`[ \t\n\r]+`, nil)
	rule(`#[^\n]*`, nil)

	rule(`\.\.\.`, opWithPrefs(recursiveDescentOpType, recursiveDescentPreferences{RecurseArray: true, TraversePreferences: traversePreferences{DontFollowAlias: true, IncludeMapKeys: true}}))
	rule(`\.\.`, opWithPrefs(recursiveDescentOpType, recursiveDescentPreferences{RecurseArray: true, TraversePreferences: traversePreferences{DontFollowAlias: true, IncludeMapKeys: false}}))
	rule(`\.\[`, func(match string, groups []string) ([]*token, error) {
		return []*token{
			{TokenType: operationToken, Operation: &Operation{OperationType: selfReferenceOpType}},
			{TokenType: operationToken, Operation: &Operation{OperationType: traverseArrayOpType}},
			{TokenType: openCollect},
		}, nil
	})
	rule(`\."[^" ]*"\??`, traverseHandler)
	rule(`\.[^ \t\n\r\[\]{}()=!,;:|.]*`, traverseHandler)

	rule(`\(`, simpleToken(openBracket, false))
	rule(`\)`, simpleToken(closeBracket, true))
	rule(`\[`, simpleToken(openCollect, false))
	rule(`\]\??`, simpleToken(closeCollect, true))
	rule(`\{`, simpleToken(openCollectObject, false))
	rule(`\}`, simpleToken(closeCollectObject, true))

	rule(`;`, simpleOp(blockOpType))
	rule(`,`, simpleOp(unionOpType))
	rule(`:`, simpleOp(createMapOpType))

	rule(`\|=`, opWithPrefs(assignOpType, assignPreferences{}))
	rule(`\|`, simpleOp(pipeOpType))

	// numbers (before - operator)
	rule(`-?0[xX][0-9a-fA-F]+`, numberHandler)
	rule(`-?[0-9]+(\.[0-9]+)?([eE][-+]?[0-9]+)?`, numberHandler)

	rule(`"(\\.|[^"\\])*"`, stringHandler)
	rule(`\$[a-zA-Z0-9_\-]+`, variableHandler)

	// multi-char operators
	rule(`==`, simpleOp(equalsOpType))
	rule(`!=`, simpleOp(notEqualsOpType))
	rule(`>=`, opWithPrefs(compareOpType, compareTypePref{OrEqual: true, Greater: true}))
	rule(`<=`, opWithPrefs(compareOpType, compareTypePref{OrEqual: true, Greater: false}))
	rule(`>`, opWithPrefs(compareOpType, compareTypePref{OrEqual: false, Greater: true}))
	rule(`<`, opWithPrefs(compareOpType, compareTypePref{OrEqual: false, Greater: false}))
	rule(`\+=`, simpleOp(addAssignOpType))
	rule(`-=`, simpleOp(subtractAssignOpType))
