	rule(`flatten(\([0-9]*\))?`, flattenHandler)
	rule(`parent(\([0-9-]*\))?`, parentHandler)

	rule(`load_base64|load_props|load_xml|load_str|strload|load`, loadHandler)

	type kw struct {
		name    string
