		{"fromEntries", simpleOp(fromEntriesOpType)},
		{"fromentries", simpleOp(fromEntriesOpType)},
		{"with_entries", simpleOp(withEntriesOpType)},
		{"withEntries", simpleOp(withEntriesOpType)},
		{"withentries", simpleOp(withEntriesOpType)},
		{"delpaths", simpleOp(delPathsOpType)},
		{"del_paths", simpleOp(delPathsOpType)},
		{"del", simpleOp(deleteChildOpType)},
		{"pick", simpleOp(pickOpType)},
		{"omit", simpleOp(omitOpType)},
		{"path", simpleOp(getPathOpType)},
		{"setpath", simpleOp(setPathOpType)},
		{"set_path", simpleOp(setPathOpType)},
		{"eval", simpleOp(evalOpType)},
		{"with_dtf", simpleOp(withDtfOpType)},
		{"with", simpleOp(withOpType)},
		{"error", simpleOp(errorOpType)},
		{"sort_by", simpleOp(sortByOpType)},
