		{"sortKeys", simpleOp(sortKeysOpType)},
		{"sortkeys", simpleOp(sortKeysOpType)},
		{"sort", simpleOp(sortOpType)},
		{"reverse", simpleOp(reverseOpType)},
		{"unique_by", simpleOp(uniqueByOpType)},
		{"unique", simpleOp(uniqueOpType)},
		{"group_by", simpleOp(groupByOpType)},
		{"groupby", simpleOp(groupByOpType)},
		{"min", simpleOp(minOpType)},
		{"max", simpleOp(maxOpType)},
		{"any_c", simpleOp(anyConditionOpType)},
		{"any", simpleOp(anyOpType)},
		{"all_c", simpleOp(allConditionOpType)},
		{"all", simpleOp(allOpType)},
