		{"line_comment", assignableOpWithPrefs(getCommentOpType, assignCommentOpType, commentOpPreferences{LineComment: true})},
		{"lineComment", assignableOpWithPrefs(getCommentOpType, assignCommentOpType, commentOpPreferences{LineComment: true})},
