// lexError mirrors the participle lexer error format.
func lexError(line, col int, remaining string) error {
	text := remaining
	runes := []rune(text)
	if len(runes) > 16 {
		text = string(runes[:16]) + "..."
	}
	return fmt.Errorf("%d:%d: lexer: invalid input text %s", line, col, strconv.Quote(text))
}

func tokenise(expression string) ([]*token, error) {
	if len(lexRules) == 0 {
		initLexer()
	}
	var tokens []*token
	pos := 0
	line, col := 1, 1
	for pos < len(expression) {
		remaining := expression[pos:]
		matched := false
		for _, r := range lexRules {
			loc := r.re.FindStringSubmatchIndex(remaining)
			if loc == nil || loc[1] == 0 {
				continue
			}
			match := remaining[:loc[1]]
			matched = true
			if r.handler != nil {
				groups := make([]string, 0)
				toks, err := r.handler(match, groups)
				if err != nil {
					return nil, err
				}
				tokens = append(tokens, toks...)
			}
			// advance position
			for _, ch := range match {
				if ch == '\n' {
					line++
					col = 1
				} else {
					col++
				}
			}
			pos += len(match)
			break
		}
		if !matched {
			return nil, lexError(line, col, remaining)
		}
	}
	return tokens, nil
}
