func createExpressionTree(postFixPath []*Operation) (*ExpressionNode, error) {
	var stack []*ExpressionNode
	if len(postFixPath) == 0 {
		return nil, nil
	}
	for _, op := range postFixPath {
		var newNode = ExpressionNode{Operation: op}
		numArgs := op.OperationType.NumArgs
		if numArgs > 0 {
			if numArgs == 1 {
				if len(stack) < 1 {
					return nil, fmt.Errorf("'%v' expects 1 arg but received none", strings.TrimSpace(op.toString()))
				}
				remaining, rhs := stack[:len(stack)-1], stack[len(stack)-1]
				newNode.RHS = rhs
				stack = remaining
			} else if numArgs == 2 {
				if len(stack) < 2 {
					return nil, fmt.Errorf("'%v' expects 2 args but there is %v", strings.TrimSpace(op.toString()), len(stack))
				}
				remaining, lhs, rhs := stack[:len(stack)-2], stack[len(stack)-2], stack[len(stack)-1]
				newNode.LHS = lhs
				newNode.RHS = rhs
				stack = remaining
			}
		}
		stack = append(stack, &newNode)
	}
	if len(stack) != 1 {
		return nil, fmt.Errorf("bad expression, please check expression syntax")
	}
	return stack[0], nil
}

var expressionCache = map[string]*ExpressionNode{}

func parseExpression(expression string) (*ExpressionNode, error) {
	if cached, ok := expressionCache[expression]; ok {
		return cached, nil
	}
	tokens, err := tokenise(expression)
	if err != nil {
		return nil, err
	}
	fixed := fixTokens(tokens)
	postfix, err := convertToPostfix(fixed)
	if err != nil {
		return nil, err
	}
	tree, err := createExpressionTree(postfix)
	if err != nil {
		return nil, err
	}
	expressionCache[expression] = tree
	return tree, nil
}
