package main

import (
	"container/list"
	"fmt"
	"strings"
)

// NodeList is a list of nodes; its pointer identity matters for the union operator.
type NodeList struct {
	*list.List
}

func newNodeList() *NodeList {
	return &NodeList{list.New()}
}

func nodeListOf(nodes ...*Node) *NodeList {
	l := newNodeList()
	for _, n := range nodes {
		l.PushBack(n)
	}
	return l
}

func (nl *NodeList) Nodes() []*Node {
	if nl == nil || nl.List == nil {
		return nil
	}
	res := make([]*Node, 0, nl.Len())
	for el := nl.Front(); el != nil; el = el.Next() {
		res = append(res, el.Value.(*Node))
	}
	return res
}

func (nl *NodeList) First() *Node {
	if nl == nil || nl.List == nil || nl.Len() == 0 {
		return nil
	}
	return nl.Front().Value.(*Node)
}

func (nl *NodeList) Append(n *Node) {
	nl.PushBack(n)
}

type Context struct {
	MatchingNodes  *NodeList
	Variables      map[string]*NodeList
	DontAutoCreate bool
	datetimeLayout string
}

func (c Context) SingleReadonlyChildContext(candidate *Node) Context {
	clone := c.ChildContext(nodeListOf(candidate))
	clone.DontAutoCreate = true
	return clone
}

func (c Context) SingleChildContext(candidate *Node) Context {
	return c.ChildContext(nodeListOf(candidate))
}

func (c Context) GetDateTimeLayout() string {
	if c.datetimeLayout != "" {
		return c.datetimeLayout
	}
	return "2006-01-02T15:04:05Z07:00"
}

func (c Context) SetDateTimeLayout(newDateTimeLayout string) {
	c.datetimeLayout = newDateTimeLayout
}

func (c Context) GetVariable(name string) (*NodeList, bool) {
	if c.Variables == nil {
		return nil, false
	}
	v, ok := c.Variables[name]
	return v, ok
}

func (c Context) SetVariable(name string, value *NodeList) {
	if c.Variables == nil {
		c.Variables = make(map[string]*NodeList)
	}
	c.Variables[name] = value
}

func (c Context) ChildContext(results *NodeList) Context {
	clone := c.Clone()
	clone.MatchingNodes = results
	return clone
}

func (c Context) Clone() Context {
	clone := Context{}
	clone.MatchingNodes = c.MatchingNodes
	clone.DontAutoCreate = c.DontAutoCreate
	clone.datetimeLayout = c.datetimeLayout
	clone.Variables = make(map[string]*NodeList, len(c.Variables))
	for k, v := range c.Variables {
		clone.Variables[k] = v
	}
	return clone
}

func (c Context) ReadOnlyClone() Context {
	clone := c.Clone()
	clone.DontAutoCreate = true
	return clone
}

func (c Context) WritableClone() Context {
	clone := c.Clone()
	clone.DontAutoCreate = false
	return clone
}

func (c Context) DeepClone() Context {
	clone := c.Clone()
	clone.MatchingNodes = newNodeList()
	for el := c.MatchingNodes.Front(); el != nil; el = el.Next() {
		clone.MatchingNodes.PushBack(el.Value.(*Node).Copy())
	}
	return clone
}

func (c Context) ToString() string {
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("Context\nDontAutoCreate: %v\n", c.DontAutoCreate))
	for el := c.MatchingNodes.Front(); el != nil; el = el.Next() {
		sb.WriteString(el.Value.(*Node).String())
		sb.WriteString("\n")
	}
	return sb.String()
}
