package main

import (
	"fmt"
)

type evaluator struct {
	prefs *globalPrefs
}

func newEvaluator() *evaluator {
	return &evaluator{}
}

// GetMatchingNodes evaluates the expression tree against the context.
func (d *evaluator) GetMatchingNodes(context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode == nil {
		return context, nil
	}
	handler := expressionNode.Operation.OperationType.Handler
	if handler != nil {
		return handler(d, context, expressionNode)
	}
	return Context{}, fmt.Errorf("Unknown operator %v", expressionNode.Operation.OperationType.Type)
}

func selfOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return context, nil
}

func emptyOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return context.ChildContext(newNodeList()), nil
}

func valueOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	node := expressionNode.Operation.CandidateNode
	// each evaluation produces a fresh copy so that mutations don't leak
	n := &Node{Kind: node.Kind, Tag: node.Tag, Value: node.Value, Style: node.Style}
	return context.SingleChildContext(n), nil
}

func pipeOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode.LHS.Operation.OperationType == assignVariableOpType {
		return variableLoop(d, context, expressionNode)
	}
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	return d.GetMatchingNodes(lhs, expressionNode.RHS)
}

func unionOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	rhs, err := d.GetMatchingNodes(context, expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	results := lhs.ChildContext(newNodeList())
	for el := lhs.MatchingNodes.Front(); el != nil; el = el.Next() {
		results.MatchingNodes.PushBack(el.Value)
	}
	if rhs.MatchingNodes != lhs.MatchingNodes {
		for el := rhs.MatchingNodes.Front(); el != nil; el = el.Next() {
			results.MatchingNodes.PushBack(el.Value)
		}
	}
	// merge variables
	for k, v := range rhs.Variables {
		results.Variables[k] = v
	}
	return results, nil
}

func blockOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	_, err = d.GetMatchingNodes(lhs, expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	return context.ChildContext(newNodeList()), nil
}

// crossFunction evaluates lhs and rhs against the context and runs the
// calculation on the cartesian product.
type crossFunctionCalculation func(d *evaluator, context Context, lhs *Node, rhs *Node) (*Node, error)

func crossFunction(d *evaluator, context Context, expressionNode *ExpressionNode, calculation crossFunctionCalculation, calcWhenEmpty bool) (Context, error) {
	return doCrossFunc(d, context, expressionNode, calculation, calcWhenEmpty)
}

func doCrossFunc(d *evaluator, context Context, expressionNode *ExpressionNode, calculation crossFunctionCalculation, calcWhenEmpty bool) (Context, error) {
	results := newNodeList()
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	rhs, err := d.GetMatchingNodes(context, expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	if calcWhenEmpty && lhs.MatchingNodes.Len() == 0 {
		for rightEl := rhs.MatchingNodes.Front(); rightEl != nil; rightEl = rightEl.Next() {
			resultCandidate, err := calculation(d, context, nil, rightEl.Value.(*Node))
			if err != nil {
				return Context{}, err
			}
			if resultCandidate != nil {
				results.PushBack(resultCandidate)
			}
		}
		return context.ChildContext(results), nil
	}
	for el := lhs.MatchingNodes.Front(); el != nil; el = el.Next() {
		lhsCandidate := el.Value.(*Node)
		for rightEl := rhs.MatchingNodes.Front(); rightEl != nil; rightEl = rightEl.Next() {
			rhsCandidate := rightEl.Value.(*Node)
			resultCandidate, err := calculation(d, context, lhsCandidate, rhsCandidate)
			if err != nil {
				return Context{}, err
			}
			if resultCandidate != nil {
				results.PushBack(resultCandidate)
			}
		}
	}
	return context.ChildContext(results), nil
}

// crossFunctionWithPrefs is like crossFunction but where each lhs node is used
// as the context for evaluating the rhs (used by e.g. alternative operator).
func crossFunctionPerLhs(d *evaluator, context Context, expressionNode *ExpressionNode, calculation crossFunctionCalculation, calcWhenEmpty bool) (Context, error) {
	results := newNodeList()
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	if calcWhenEmpty && lhs.MatchingNodes.Len() == 0 {
		rhs, err := d.GetMatchingNodes(context, expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		for rightEl := rhs.MatchingNodes.Front(); rightEl != nil; rightEl = rightEl.Next() {
			resultCandidate, err := calculation(d, context, nil, rightEl.Value.(*Node))
			if err != nil {
				return Context{}, err
			}
			if resultCandidate != nil {
				results.PushBack(resultCandidate)
			}
		}
		return context.ChildContext(results), nil
	}
	for el := lhs.MatchingNodes.Front(); el != nil; el = el.Next() {
		lhsCandidate := el.Value.(*Node)
		rhs, err := d.GetMatchingNodes(context, expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		for rightEl := rhs.MatchingNodes.Front(); rightEl != nil; rightEl = rightEl.Next() {
			rhsCandidate := rightEl.Value.(*Node)
			resultCandidate, err := calculation(d, context, lhsCandidate, rhsCandidate)
			if err != nil {
				return Context{}, err
			}
			if resultCandidate != nil {
				results.PushBack(resultCandidate)
			}
		}
	}
	return context.ChildContext(results), nil
}

// ---- collect

func collectOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if context.MatchingNodes.Len() == 0 {
		node := &Node{Kind: SequenceNode, Tag: "!!seq", Value: "[]"}
		return context.SingleChildContext(node), nil
	}
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		collected := &Node{Kind: SequenceNode, Tag: "!!seq"}
		collectExpResults, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		for result := collectExpResults.MatchingNodes.Front(); result != nil; result = result.Next() {
			resultC := result.Value.(*Node)
			collected.AddChild(resultC)
		}
		results.PushBack(collected)
	}
	return context.ChildContext(results), nil
}

// ---- create map / collect object

func createMapOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	// each matchingNodes entry should turn into a sequence of keys to create.
	// then collect object should do a cross function of the same index sequence for all matches.
	sequences := newNodeList()
	if context.MatchingNodes.Len() > 0 {
		for matchingNodeEl := context.MatchingNodes.Front(); matchingNodeEl != nil; matchingNodeEl = matchingNodeEl.Next() {
			matchingNode := matchingNodeEl.Value.(*Node)
			sequenceNode, err := sequenceFor(d, context, matchingNode, expressionNode)
			if err != nil {
				return Context{}, err
			}
			sequences.PushBack(sequenceNode)
		}
	} else {
		sequenceNode, err := sequenceFor(d, context, nil, expressionNode)
		if err != nil {
			return Context{}, err
		}
		sequences.PushBack(sequenceNode)
	}
	outer := &Node{Kind: SequenceNode, Tag: "!!seq"}
	for el := sequences.Front(); el != nil; el = el.Next() {
		child := el.Value.(*Node)
		child.Parent = outer
		outer.Content = append(outer.Content, child)
	}
	return context.SingleChildContext(outer), nil
}

func sequenceFor(d *evaluator, context Context, matchingNode *Node, expressionNode *ExpressionNode) (*Node, error) {
	matches := newNodeList()
	if matchingNode != nil {
		matches.PushBack(matchingNode)
	}
	mapPairs, err := crossFunction(d, context.ChildContext(matches), expressionNode,
		func(d *evaluator, context Context, lhs *Node, rhs *Node) (*Node, error) {
			node := &Node{Kind: MappingNode, Tag: "!!map"}
			node.AddKeyValueChild(lhs, rhs)
			return node, nil
		}, false)
	if err != nil {
		return nil, err
	}
	innerList := &Node{Kind: SequenceNode, Tag: "!!seq", Style: FlowStyle}
	for el := mapPairs.MatchingNodes.Front(); el != nil; el = el.Next() {
		n := el.Value.(*Node)
		n.Parent = innerList
		innerList.Content = append(innerList.Content, n)
	}
	return innerList, nil
}

func collectObjectOperator(d *evaluator, originalContext Context, expressionNode *ExpressionNode) (Context, error) {
	context := originalContext.WritableClone()
	if context.MatchingNodes.Len() == 0 {
		candidate := &Node{Kind: MappingNode, Tag: "!!map", Value: "{}"}
		return context.SingleChildContext(candidate), nil
	}
	first := context.MatchingNodes.Front().Value.(*Node)
	var rotated = make([][]*Node, len(first.Content))

	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidateNode := el.Value.(*Node)
		if len(candidateNode.Content) < len(first.Content) {
			return Context{}, fmt.Errorf("CollectObject: mismatching node sizes; are you creating a map with mismatching key value pairs?")
		}
		for i := 0; i < len(first.Content); i++ {
			rotated[i] = append(rotated[i], candidateNode.Content[i])
		}
	}

	newObject := newNodeList()
	for i := 0; i < len(first.Content); i++ {
		additions, err := collect(d, context.ChildContext(newNodeList()), rotated[i])
