			return Context{}, err
		}
		for el := additions.MatchingNodes.Front(); el != nil; el = el.Next() {
			newObject.PushBack(el.Value)
		}
	}
	return context.ChildContext(newObject), nil
}

func collect(d *evaluator, context Context, remainingMatches []*Node) (Context, error) {
	if len(remainingMatches) == 0 {
		return context, nil
	}
	candidate := remainingMatches[0]
	remainingMatches = remainingMatches[1:]

	splatted, err := splat(context.SingleChildContext(candidate), traversePreferences{DontFollowAlias: true, IncludeMapKeys: false})
	if err != nil {
		return Context{}, err
	}
	for splatEl := splatted.MatchingNodes.Front(); splatEl != nil; splatEl = splatEl.Next() {
		splatEl.Value.(*Node).Style = 0
	}
	if context.MatchingNodes.Len() == 0 {
		return collect(d, splatted, remainingMatches)
	}
	newAgg := newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		aggCandidate := el.Value.(*Node)
		for splatEl := splatted.MatchingNodes.Front(); splatEl != nil; splatEl = splatEl.Next() {
			splatCandidate := splatEl.Value.(*Node)
			newCandidate := aggCandidate.Copy()
			newCandidate.Parent = nil
			newCandidate.Key = nil
			newCandidate, err := multiply(multiplyPreferences{AppendArrays: false, TraversePrefs: traversePreferences{DontFollowAlias: true}})(d, context, newCandidate, splatCandidate)
			if err != nil {
				return Context{}, err
			}
			newAgg.PushBack(newCandidate)
		}
	}
	return collect(d, context.ChildContext(newAgg), remainingMatches)
}
