func (d *evaluator) GetMatchingNodes(context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode == nil {
		return context, nil
	}
	handler := expressionNode.Operation.OperationType.Handler
	if handler != nil {
		return handler(d, context, expressionNode)
	}
	return Context{}, fmt.Errorf("Unknown operator %v", expressionNode.Operation.OperationType.Type)
}

func selfOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return context, nil
}

func emptyOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return context.ChildContext(newNodeList()), nil
}

func valueOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	node := expressionNode.Operation.CandidateNode
	// each evaluation produces a fresh copy so that mutations don't leak
	n := &Node{Kind: node.Kind, Tag: node.Tag, Value: node.Value, Style: node.Style}
	return context.SingleChildContext(n), nil
}

func pipeOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode.LHS.Operation.OperationType == assignVariableOpType {
		return variableLoop(d, context, expressionNode)
	}
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	return d.GetMatchingNodes(lhs, expressionNode.RHS)
}

func unionOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	rhs, err := d.GetMatchingNodes(context, expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	results := lhs.ChildContext(newNodeList())
	for el := lhs.MatchingNodes.Front(); el != nil; el = el.Next() {
		results.MatchingNodes.PushBack(el.Value)
	}
	if rhs.MatchingNodes != lhs.MatchingNodes {
		for el := rhs.MatchingNodes.Front(); el != nil; el = el.Next() {
			results.MatchingNodes.PushBack(el.Value)
		}
	}
	// merge variables
	for k, v := range rhs.Variables {
