package main

import (
	"fmt"
	"strconv"
)

func traversePathOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var matches = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		newNodes, err := traverse(context, el.Value.(*Node), expressionNode.Operation)
		if err != nil {
			return Context{}, err
		}
		for _, n := range newNodes {
			matches.PushBack(n)
		}
	}
	return context.ChildContext(matches), nil
}

func traverse(context Context, matchingNode *Node, operation *Operation) ([]*Node, error) {
	value := operation.Value
	prefs := traversePreferences{}
	if p, ok := operation.Preferences.(traversePreferences); ok {
		prefs = p
	}
	if matchingNode.Kind == AliasNode && !prefs.DontFollowAlias {
		matchingNode = matchingNode.Alias
	}
	switch matchingNode.Kind {
	case MappingNode:
		return traverseMap(context, matchingNode, createStringScalar(fmt.Sprintf("%v", value)), prefs, false)
	case SequenceNode:
		return traverseArray(matchingNode, operation.CandidateNode, prefs)
	case AliasNode:
		return traverse(context, matchingNode.Alias, operation)
	case ScalarNode:
		if matchingNode.Tag == "!!null" && !context.DontAutoCreate && !prefs.DontAutoCreate {
			// create a map
			matchingNode.Kind = MappingNode
			matchingNode.Tag = "!!map"
			matchingNode.Value = ""
			matchingNode.Style = 0
			matchingNode.Content = nil
			return traverseMap(context, matchingNode, createStringScalar(fmt.Sprintf("%v", value)), prefs, false)
		}
		return nil, nil
	}
	return nil, nil
}

func keyMatches(key *Node, wanted *Node) bool {
	return wanted.Value == key.Value
}

func traverseMap(context Context, matchingNode *Node, keyNode *Node, prefs traversePreferences, splat bool) ([]*Node, error) {
	var newMatches = newNodeList()
	err := doTraverseMap(newMatches, matchingNode, keyNode, prefs, splat)
	if err != nil {
		return nil, err
	}
	if !splat && !prefs.DontAutoCreate && !context.DontAutoCreate && newMatches.Len() == 0 {
		// no matches, create one
		keyNode := createStringScalar(keyNode.Value)
		valueNode := createNull()
		_, value := matchingNode.AddKeyValueChild(keyNode, valueNode)
		newMatches.PushBack(value)
	}
	return newMatches.Nodes(), nil
}

func doTraverseMap(newMatches *NodeList, node *Node, wantedKey *Node, prefs traversePreferences, splat bool) error {
	// value.Content is a concatenated array of key, value,
	// so keys are in the even indexes, values in odd.
	// merge aliases are defined first, but we only want to traverse them
	// if we don't find a match directly on this node first.
	var contents = node.Content
	for index := 0; index < len(contents); index = index + 2 {
		key := contents[index]
		value := contents[index+1]
		// skip the 'merge' tag, find a direct match first
		if key.Tag == "!!merge" && !prefs.DontFollowAlias {
			if err := traverseMergeAnchor(newMatches, value, wantedKey, prefs, splat); err != nil {
				return err
			}
		} else if splat || keyMatches(key, wantedKey) {
			if prefs.IncludeMapKeys {
				newMatches.PushBack(key)
			}
			if !prefs.DontIncludeMapValues {
				newMatches.PushBack(value)
			}
		}
	}
	return nil
}

func traverseMergeAnchor(newMatches *NodeList, value *Node, wantedKey *Node, prefs traversePreferences, splat bool) error {
	switch value.Kind {
	case AliasNode:
		if value.Alias == nil {
			return nil
		}
		if value.Alias.Kind != MappingNode {
			return fmt.Errorf("can only use merge anchors with maps (!!map), but got %v", value.Alias.Tag)
		}
		return doTraverseMap(newMatches, value.Alias, wantedKey, prefs, splat)
	case SequenceNode:
		for _, childValue := range value.Content {
			err := traverseMergeAnchor(newMatches, childValue, wantedKey, prefs, splat)
			if err != nil {
				return err
			}
		}
	}
	return nil
}

func traverseArray(node *Node, keyNode *Node, prefs traversePreferences) ([]*Node, error) {
	var indicesToTraverse []*Node
	if keyNode.Kind == SequenceNode {
		indicesToTraverse = keyNode.Content
	} else {
		indicesToTraverse = []*Node{keyNode}
	}
	return traverseArrayIndices(node, indicesToTraverse, prefs)
}

func traverseArrayIndices(node *Node, indicesToTraverse []*Node, prefs traversePreferences) ([]*Node, error) {
	if node.Tag == "!!null" {
		node.Kind = SequenceNode
		node.Tag = "!!seq"
		node.Value = ""
		node.Style = 0
		node.Content = nil
	}
	if node.Kind == AliasNode && node.Alias != nil {
		node = node.Alias
	}
	if node.Kind == MappingNode {
		var newMatches []*Node
		for _, indexNode := range indicesToTraverse {
			matches, err := traverseMapWithIndices(node, indexNode, prefs)
			if err != nil {
				return nil, err
			}
			newMatches = append(newMatches, matches...)
		}
		return newMatches, nil
	}
	if node.Kind == ScalarNode {
		// slicing strings
		var newMatches []*Node
		for _, indexNode := range indicesToTraverse {
			if indexNode.Kind == MappingNode {
				sliced, err := sliceString(node, indexNode)
				if err != nil {
					return nil, err
				}
				newMatches = append(newMatches, sliced)
			}
		}
		return newMatches, nil
	}
	if node.Kind != SequenceNode {
		return nil, nil
	}
	if len(indicesToTraverse) == 0 {
		// splat
		return node.Content, nil
	}
	var newMatches []*Node
	for _, indexNode := range indicesToTraverse {
		if indexNode.Kind == MappingNode {
			// slice
			sliced, err := sliceArray(node, indexNode)
			if err != nil {
				return nil, err
			}
			newMatches = append(newMatches, sliced)
			continue
		}
		index, err := parseInt(indexNode.Value)
		if err != nil {
			if prefs.OptionalTraverse {
				continue
			}
			return nil, fmt.Errorf("cannot index array with '%v' (%v)", indexNode.Value, err)
		}
		indexToUse := index
		contentLength := len(node.Content)
		for contentLength <= index {
			if contentLength == 0 {
				// default to nice yaml formatting
				node.Style = 0
			}
			node.AddChild(createNull())
			contentLength = len(node.Content)
		}
		if indexToUse < 0 {
			indexToUse = contentLength + indexToUse
		}
		if indexToUse < 0 {
			return nil, fmt.Errorf("index [%v] out of range, array size is %v", index, contentLength)
		}
		newMatches = append(newMatches, node.Content[indexToUse])
	}
	return newMatches, nil
}

func parseInt(s string) (int, error) {
	i, err := strconv.ParseInt(s, 10, 64)
	return int(i), err
}

func traverseMapWithIndices(node *Node, indexNode *Node, prefs traversePreferences) ([]*Node, error) {
	if indexNode.Kind == MappingNode {
		// slice on a map - yields an empty array
		return []*Node{{Kind: SequenceNode, Tag: "!!seq"}}, nil
	}
	ctx := Context{DontAutoCreate: prefs.DontAutoCreate}
	return traverseMap(ctx, node, indexNode, prefs, false)
}

func sliceBounds(length int, indexNode *Node) (int, int, error) {
	start := 0
	end := length
	if len(indexNode.Content) >= 2 {
		startNode := indexNode.Content[0]
