package main

import (
	"fmt"
)

func assignUpdateOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	prefs := assignPreferences{}
	if p, ok := expressionNode.Operation.Preferences.(assignPreferences); ok {
		prefs = p
	}
	if !expressionNode.Operation.UpdateAssign {
		// first evaluate the rhs with the original context
		rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		for rhsEl := rhs.MatchingNodes.Front(); rhsEl != nil; rhsEl = rhsEl.Next() {
			rhsCandidate := rhsEl.Value.(*Node)
			for el := lhs.MatchingNodes.Front(); el != nil; el = el.Next() {
				candidate := el.Value.(*Node)
				candidate.UpdateFrom(rhsCandidate, prefs)
			}
		}
		return context, nil
	}
	for el := lhs.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		first := rhs.MatchingNodes.Front()
		if first != nil {
			rhsCandidate := first.Value.(*Node)
			candidate.UpdateFrom(rhsCandidate, prefs)
		}
	}
	return context, nil
}

// generic update for e.g. +=, -= : lhs op= rhs  <=> lhs |= . op rhs
func compoundAssignFunction(d *evaluator, context Context, expressionNode *ExpressionNode, operation operationHandler) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	// tricky logic when we are running this against the context (e.g. .a += 1)
	// the rhs is evaluated against the *original* context, not the lhs
	for el := lhs.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		valueOp := &Operation{OperationType: valueOpType, CandidateNode: candidate}
		valueExpression := &ExpressionNode{Operation: valueOp}
		assignmentOp := &Operation{OperationType: assignOpType, Preferences: assignPreferences{}}
		assignmentOpNode := &ExpressionNode{Operation: assignmentOp, LHS: valueExpression, RHS: &ExpressionNode{Operation: &Operation{OperationType: &operationType{Type: "COMPOUND", Handler: operation, NumArgs: 2}}, LHS: valueExpression, RHS: expressionNode.RHS}}
		_ = assignmentOpNode
		// evaluate: candidate = operation(candidate, rhs)
		rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		rhsFirst := rhs.MatchingNodes.Front()
		if rhsFirst == nil {
			continue
		}
		result, err := operation(d, context, candidate, rhsFirst.Value.(*Node))
		_ = result
		if err != nil {
			return Context{}, err
		}
	}
	return context, nil
}

// helper for compound assignments
type binaryCalc func(d *evaluator, context Context, lhs *Node, rhs *Node) (*Node, error)

func compoundAssign(calc binaryCalc) operationHandler {
	return func(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
		lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
		if err != nil {
			return Context{}, err
		}
		prefs := assignPreferences{}
		for el := lhs.MatchingNodes.Front(); el != nil; el = el.Next() {
			candidate := el.Value.(*Node)
			rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			rhsFirst := rhs.MatchingNodes.Front()
			if rhsFirst == nil {
				continue
			}
			result, err := calc(d, context, candidate, rhsFirst.Value.(*Node))
			if err != nil {
				return Context{}, err
			}
			if result != nil {
				candidate.UpdateFrom(result, prefs)
			}
		}
		return context, nil
	}
}

var addAssignOperator = compoundAssign(add)
var subtractAssignOperator = compoundAssign(subtract)

func multiplyAssignOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	prefs := multiplyPreferences{}
	if p, ok := expressionNode.Operation.Preferences.(multiplyPreferences); ok {
