func compoundAssignFunction(d *evaluator, context Context, expressionNode *ExpressionNode, operation operationHandler) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	// tricky logic when we are running this against the context (e.g. .a += 1)
	// the rhs is evaluated against the *original* context, not the lhs
	for el := lhs.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		valueOp := &Operation{OperationType: valueOpType, CandidateNode: candidate}
		valueExpression := &ExpressionNode{Operation: valueOp}
		assignmentOp := &Operation{OperationType: assignOpType, Preferences: assignPreferences{}}
		assignmentOpNode := &ExpressionNode{Operation: assignmentOp, LHS: valueExpression, RHS: &ExpressionNode{Operation: &Operation{OperationType: &operationType{Type: "COMPOUND", Handler: operation, NumArgs: 2}}, LHS: valueExpression, RHS: expressionNode.RHS}}
		_ = assignmentOpNode
		// evaluate: candidate = operation(candidate, rhs)
		rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		rhsFirst := rhs.MatchingNodes.Front()
		if rhsFirst == nil {
			continue
		}
		result, err := operation(d, context, candidate, rhsFirst.Value.(*Node))
		_ = result
		if err != nil {
			return Context{}, err
		}
	}
	return context, nil
