				rhs, err := d.GetMatchingNodes(ctx, expressionNode.RHS)
				if err != nil {
					return Context{}, err
				}
				rhsNodes := rhs.MatchingNodes.Nodes()
				if len(rhsNodes) == 0 {
					rhsNodes = []*Node{nil}
				}
				for _, rhsCandidate := range rhsNodes {
					rhsTrue := isTruthyNode(rhsCandidate)
					owner := lhsCandidate
					if owner == nil {
						owner = rhsCandidate
					}
					results.PushBack(createBooleanCandidate(owner, op(lhsTrue, rhsTrue)))
				}
			}
		}
		return context.ChildContext(results), nil
	}
}

var andOperator = booleanOp(func(a, b bool) bool { return a && b }, false)
var orOperator = booleanOp(func(a, b bool) bool { return a || b }, true)

func notOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		truthy := isTruthyNode(candidate)
		results.PushBack(createBooleanCandidate(candidate, !truthy))
	}
	return context.ChildContext(results), nil
}

func selectOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		// grab the first value
		first := rhs.MatchingNodes.Front()
		if first != nil {
			result := first.Value.(*Node)
			if isTruthyNode(result) {
				results.PushBack(candidate)
			}
		}
	}
	return context.ChildContext(results), nil
}

func anyOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return anyAllCondition(d, context, nil, func(a, b bool) bool { return a || b }, false, "any")
}

func allOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return anyAllCondition(d, context, nil, func(a, b bool) bool { return a && b }, true, "all")
}

func anyConditionOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return anyAllCondition(d, context, expressionNode.RHS, func(a, b bool) bool { return a || b }, false, "any")
}

func allConditionOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return anyAllCondition(d, context, expressionNode.RHS, func(a, b bool) bool { return a && b }, true, "all")
}

func anyAllCondition(d *evaluator, context Context, condition *ExpressionNode, op func(bool, bool) bool, initial bool, name string) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := unwrapAlias(el.Value.(*Node))
		if candidate.Kind != SequenceNode {
			return Context{}, fmt.Errorf("%v only supports arrays, was %v", name, candidate.Tag)
		}
		result := initial
		for _, child := range candidate.Content {
			childValue := isTruthyNode(child)
			if condition != nil {
				rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(child), condition)
				if err != nil {
					return Context{}, err
				}
				childValue = false
				first := rhs.MatchingNodes.Front()
				if first != nil {
					childValue = isTruthyNode(first.Value.(*Node))
				}
			}
			result = op(result, childValue)
		}
		results.PushBack(createBooleanCandidate(candidate, result))
	}
	return context.ChildContext(results), nil
}

// ---- alternative //

func alternativeOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	contexts := []Context{}
	if context.MatchingNodes.Len() == 0 {
		contexts = append(contexts, context)
	} else {
		for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
			contexts = append(contexts, context.SingleChildContext(el.Value.(*Node)))
		}
	}
	for _, ctx := range contexts {
		lhs, err := d.GetMatchingNodes(ctx, expressionNode.LHS)
		if err != nil {
			return Context{}, err
		}
		anyTruthy := false
		for el := lhs.MatchingNodes.Front(); el != nil; el = el.Next() {
			candidate := el.Value.(*Node)
			if isTruthyNode(candidate) {
				anyTruthy = true
				results.PushBack(candidate)
			}
		}
		if !anyTruthy {
			rhs, err := d.GetMatchingNodes(ctx, expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			for el := rhs.MatchingNodes.Front(); el != nil; el = el.Next() {
				results.PushBack(el.Value)
			}
		}
	}
	return context.ChildContext(results), nil
}
