// parseInt64 parses an integer, returning the format to print it back with.
func parseInt64(numberString string) (string, int64, error) {
	if strings.HasPrefix(numberString, "0x") || strings.HasPrefix(numberString, "0X") {
		num, err := strconv.ParseInt(numberString[2:], 16, 64)
		return "0x%X", num, err
	}
	num, err := strconv.ParseInt(numberString, 10, 64)
	return "%v", num, err
}

func parseIntValue(numberString string) (int, error) {
	_, num, err := parseInt64(numberString)
	return int(num), err
}

func formatFloat(f float64) string {
	return fmt.Sprintf("%v", f)
}

func guessTag(value string) string {
	return resolveTag(value)
}

func nodeTag(n *Node) string {
	if strings.HasPrefix(n.Tag, "!!") {
		return n.Tag
	}
	if n.Kind == ScalarNode {
		return guessTag(n.Value)
	}
	return n.Tag
}

// ---- add

func addOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	rhs, err := d.GetMatchingNodes(context, expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	if lhs.MatchingNodes.Len() == 0 {
		return rhs, nil
	}
	if rhs.MatchingNodes.Len() == 0 {
		return lhs, nil
	}
	results := newNodeList()
	for el := lhs.MatchingNodes.Front(); el != nil; el = el.Next() {
		for rel := rhs.MatchingNodes.Front(); rel != nil; rel = rel.Next() {
			r, err := add(d, context, el.Value.(*Node), rel.Value.(*Node))
			if err != nil {
				return Context{}, err
			}
			if r != nil {
				results.PushBack(r)
			}
		}
	}
	return context.ChildContext(results), nil
}

func add(d *evaluator, context Context, lhs *Node, rhs *Node) (*Node, error) {
	if lhs == nil {
		return rhs.Copy(), nil
	}
	if lhs.Kind == AliasNode && lhs.Alias != nil {
		lhs = lhs.Alias
	}
	if rhs.Kind == AliasNode && rhs.Alias != nil {
		rhs = rhs.Alias
	}
	if lhs.Tag == "!!null" {
		r := rhs.Copy()
		r.Parent = lhs.Parent
		r.Key = lhs.Key
		return r, nil
	}
	target := lhs.CopyWithoutContent()
	switch lhs.Kind {
	case MappingNode:
		if rhs.Kind != MappingNode {
			return nil, fmt.Errorf("%v (%v) cannot be added to a %v (%v)", rhs.Tag, rhs.GetNicePath(), lhs.Tag, lhs.GetNicePath())
		}
		addMaps(target, lhs, rhs)
	case SequenceNode:
		if err := addSequences(target, lhs, rhs); err != nil {
			return nil, err
		}
	case ScalarNode:
		if rhs.Kind != ScalarNode {
			return nil, fmt.Errorf("%v (%v) cannot be added to a %v (%v)", rhs.Tag, rhs.GetNicePath(), lhs.Tag, lhs.GetNicePath())
		}
		if err := addScalars(context, target, lhs, rhs); err != nil {
			return nil, err
		}
	}
	return target, nil
}

func addMaps(target *Node, lhs *Node, rhs *Node) {
	target.Content = nil
	for i := 0; i+1 < len(lhs.Content); i += 2 {
		target.AddKeyValueChild(lhs.Content[i], lhs.Content[i+1])
	}
	for i := 0; i+1 < len(rhs.Content); i += 2 {
		key := rhs.Content[i]
		value := rhs.Content[i+1]
		idx := target.findKeyIndex(key.Value)
		if idx >= 0 {
			nv := value.Copy()
			nv.Parent = target
			nv.Key = target.Content[idx]
			target.Content[idx+1] = nv
		} else {
			target.AddKeyValueChild(key, value)
		}
	}
	target.Kind = MappingNode
	target.Tag = lhs.Tag
}

func addSequences(target *Node, lhs *Node, rhs *Node) error {
	target.Content = nil
	for _, c := range lhs.Content {
		target.AddChild(c)
	}
	if rhs.Kind == SequenceNode {
		for _, c := range rhs.Content {
			target.AddChild(c)
		}
	} else if rhs.Tag != "!!null" {
		target.AddChild(rhs)
	}
	target.Kind = SequenceNode
	target.Tag = lhs.Tag
	return nil
}

func addScalars(context Context, target *Node, lhs *Node, rhs *Node) error {
	lhsTag := lhs.Tag
	rhsTag := rhs.Tag
	lhsIsCustom := false
	if !strings.HasPrefix(lhsTag, "!!") {
		lhsTag = guessTag(lhs.Value)
		lhsIsCustom = true
	}
	if !strings.HasPrefix(rhsTag, "!!") {
		rhsTag = guessTag(rhs.Value)
	}
	isDateTime := lhs.Tag == "!!timestamp"
	if lhsTag == "!!str" && context.GetDateTimeLayout() != time.RFC3339 {
		_, err := parseDateTime(context.GetDateTimeLayout(), lhs.Value)
		isDateTime = err == nil
	}
	if isDateTime {
		return addDateTimes(context.GetDateTimeLayout(), target, lhs, rhs)
	} else if lhsTag == "!!str" {
		target.Kind = ScalarNode
		target.Style = lhs.Style
		target.Tag = lhs.Tag
		if rhs.Tag == "!!null" {
			target.Value = lhs.Value
		} else {
			target.Value = lhs.Value + rhs.Value
		}
	} else if rhsTag == "!!str" {
		target.Kind = ScalarNode
		target.Style = rhs.Style
		target.Tag = rhs.Tag
		target.Value = lhs.Value + rhs.Value
	} else if lhsTag == "!!int" && rhsTag == "!!int" {
		format, lhsNum, err := parseInt64(lhs.Value)
		if err != nil {
			return err
		}
		_, rhsNum, err := parseInt64(rhs.Value)
		if err != nil {
			return err
		}
		sum := lhsNum + rhsNum
		target.Kind = ScalarNode
		target.Style = lhs.Style
		target.Tag = lhs.Tag
		target.Value = fmt.Sprintf(format, sum)
	} else if (lhsTag == "!!int" || lhsTag == "!!float") && (rhsTag == "!!int" || rhsTag == "!!float") {
		lhsNum, err := strconv.ParseFloat(lhs.Value, 64)
		if err != nil {
			return err
		}
		rhsNum, err := strconv.ParseFloat(rhs.Value, 64)
		if err != nil {
			return err
		}
		sum := lhsNum + rhsNum
		target.Kind = ScalarNode
		target.Style = lhs.Style
		if lhsIsCustom {
			target.Tag = lhs.Tag
		} else {
			target.Tag = "!!float"
		}
		target.Value = formatFloat(sum)
	} else {
		return fmt.Errorf("%v cannot be added to %v", lhs.Tag, rhs.Tag)
	}
	return nil
}

func addDateTimes(layout string, target *Node, lhs *Node, rhs *Node) error {
	duration, err := time.ParseDuration(rhs.Value)
	if err != nil {
		return fmt.Errorf("unable to parse duration [%v]: %w", rhs.Value, err)
	}
	currentTime, err := parseDateTime(layout, lhs.Value)
	if err != nil {
		return err
	}
	newTime := currentTime.Add(duration)
	target.Kind = ScalarNode
	target.Style = lhs.Style
	target.Tag = lhs.Tag
	target.Value = newTime.Format(layout)
	return nil
}

// ---- subtract

func subtractOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return crossFunction(d, context.ReadOnlyClone(), expressionNode, subtract, false)
}

func subtract(d *evaluator, context Context, lhs *Node, rhs *Node) (*Node, error) {
	if lhs.Kind == AliasNode && lhs.Alias != nil {
		lhs = lhs.Alias
	}
	if rhs.Kind == AliasNode && rhs.Alias != nil {
		rhs = rhs.Alias
	}
	if lhs.Tag == "!!null" {
		r := rhs.Copy()
		r.Parent = lhs.Parent
		r.Key = lhs.Key
		return r, nil
	}
	target := lhs.CopyWithoutContent()
	switch lhs.Kind {
	case MappingNode:
		return nil, fmt.Errorf("maps not yet supported for subtraction")
	case SequenceNode:
		if rhs.Kind != SequenceNode {
			return nil, fmt.Errorf("%v (%v) cannot be subtracted from %v", rhs.Tag, rhs.GetNicePath(), lhs.Tag)
		}
		subtractArray(target, lhs, rhs)
	case ScalarNode:
		if rhs.Kind != ScalarNode {
			return nil, fmt.Errorf("%v (%v) cannot be subtracted from %v", rhs.Tag, rhs.GetNicePath(), lhs.Tag)
		}
		if err := subtractScalars(context, target, lhs, rhs); err != nil {
			return nil, err
		}
	}
	return target, nil
}

func subtractArray(target *Node, lhs *Node, rhs *Node) {
	target.Content = nil
	for _, item := range lhs.Content {
		found := false
		for _, r := range rhs.Content {
			if recursiveNodeEqual(item, r) {
				found = true
				break
			}
		}
		if !found {
			target.AddChild(item)
		}
	}
	target.Kind = SequenceNode
	target.Tag = lhs.Tag
}

func subtractScalars(context Context, target *Node, lhs *Node, rhs *Node) error {
	lhsTag := lhs.Tag
	rhsTag := rhs.Tag
	lhsIsCustom := false
	if !strings.HasPrefix(lhsTag, "!!") {
		lhsTag = guessTag(lhs.Value)
		lhsIsCustom = true
	}
	if !strings.HasPrefix(rhsTag, "!!") {
		rhsTag = guessTag(rhs.Value)
	}
	isDateTime := lhs.Tag == "!!timestamp"
	if lhsTag == "!!str" && context.GetDateTimeLayout() != time.RFC3339 {
		_, err := parseDateTime(context.GetDateTimeLayout(), lhs.Value)
		isDateTime = err == nil
	}
	if isDateTime {
		return subtractDateTime(context.GetDateTimeLayout(), target, lhs, rhs)
	} else if lhsTag == "!!str" {
		return fmt.Errorf("strings cannot be subtracted")
	} else if lhsTag == "!!int" && rhsTag == "!!int" {
		format, lhsNum, err := parseInt64(lhs.Value)
		if err != nil {
			return err
		}
		_, rhsNum, err := parseInt64(rhs.Value)
		if err != nil {
			return err
		}
		result := lhsNum - rhsNum
		target.Kind = ScalarNode
		target.Style = lhs.Style
		target.Tag = lhs.Tag
		target.Value = fmt.Sprintf(format, result)
	} else if (lhsTag == "!!int" || lhsTag == "!!float") && (rhsTag == "!!int" || rhsTag == "!!float") {
		lhsNum, err := strconv.ParseFloat(lhs.Value, 64)
		if err != nil {
			return err
		}
		rhsNum, err := strconv.ParseFloat(rhs.Value, 64)
		if err != nil {
			return err
		}
		result := lhsNum - rhsNum
		target.Kind = ScalarNode
		target.Style = lhs.Style
		if lhsIsCustom {
			target.Tag = lhs.Tag
		} else {
			target.Tag = "!!float"
		}
		target.Value = formatFloat(result)
	} else {
		return fmt.Errorf("%v cannot be added to %v", lhs.Tag, rhs.Tag)
	}
	return nil
}

func subtractDateTime(layout string, target *Node, lhs *Node, rhs *Node) error {
	duration, err := time.ParseDuration(rhs.Value)
	if err != nil {
		return fmt.Errorf("unable to parse duration [%v]: %w", rhs.Value, err)
	}
	currentTime, err := parseDateTime(layout, lhs.Value)
	if err != nil {
		return err
	}
	newTime := currentTime.Add(-duration)
	target.Kind = ScalarNode
	target.Style = lhs.Style
	target.Tag = lhs.Tag
	target.Value = newTime.Format(layout)
	return nil
}

// ---- multiply

func multiplyOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	prefs := multiplyPreferences{}
	if p, ok := expressionNode.Operation.Preferences.(multiplyPreferences); ok {
		prefs = p
	}
	return crossFunction(d, context.ReadOnlyClone(), expressionNode, multiply(prefs), false)
}

func multiply(prefs multiplyPreferences) crossFunctionCalculation {
	return func(d *evaluator, context Context, lhs *Node, rhs *Node) (*Node, error) {
		if lhs == nil {
			return rhs, nil
		}
		if lhs.Kind == AliasNode && lhs.Alias != nil {
			lhs = lhs.Alias
		}
		if rhs.Kind == AliasNode && rhs.Alias != nil {
			rhs = rhs.Alias
		}
		if rhs.Tag == "!!null" && rhs.Kind == ScalarNode {
			return lhs, nil
		}
		if lhs.Tag == "!!null" && lhs.Kind == ScalarNode {
			if rhs.Kind == MappingNode || rhs.Kind == SequenceNode {
				r := rhs.Copy()
				r.Parent = lhs.Parent
				r.Key = lhs.Key
				return r, nil
			}
			return nil, fmt.Errorf("cannot multiply %v with %v", lhs.Tag, rhs.Tag)
		}
		if lhs.Kind == MappingNode && rhs.Kind == MappingNode {
			return mergeObjects(d, context, lhs, rhs, prefs)
		}
		if lhs.Kind == SequenceNode && rhs.Kind == SequenceNode {
			return mergeArrays(d, context, lhs, rhs, prefs)
		}
		if lhs.Kind == ScalarNode && rhs.Kind == ScalarNode {
			return multiplyScalars(lhs, rhs)
		}
		return nil, fmt.Errorf("cannot multiply %v with %v", lhs.Tag, rhs.Tag)
	}
}

func multiplyScalars(lhs *Node, rhs *Node) (*Node, error) {
	lhsTag := nodeTag(lhs)
	rhsTag := nodeTag(rhs)
	lhsIsCustom := !strings.HasPrefix(lhs.Tag, "!!")
	if lhsTag == "!!str" && rhsTag == "!!int" {
		return repeatString(lhs, rhs)
	} else if lhsTag == "!!int" && rhsTag == "!!str" {
		return repeatString(rhs, lhs)
	} else if lhsTag == "!!int" && rhsTag == "!!int" {
		format, lhsNum, err := parseInt64(lhs.Value)
		if err != nil {
			return nil, err
		}
		_, rhsNum, err := parseInt64(rhs.Value)
		if err != nil {
			return nil, err
		}
		return lhs.CreateReplacement(ScalarNode, lhs.Tag, fmt.Sprintf(format, lhsNum*rhsNum)), nil
	} else if (lhsTag == "!!int" || lhsTag == "!!float") && (rhsTag == "!!int" || rhsTag == "!!float") {
		lhsNum, err := strconv.ParseFloat(lhs.Value, 64)
		if err != nil {
			return nil, err
		}
		rhsNum, err := strconv.ParseFloat(rhs.Value, 64)
		if err != nil {
			return nil, err
		}
		tag := "!!float"
		if lhsIsCustom {
			tag = lhs.Tag
		}
		return lhs.CreateReplacement(ScalarNode, tag, formatFloat(lhsNum*rhsNum)), nil
	}
	return nil, fmt.Errorf("cannot multiply %v with %v", lhs.Tag, rhs.Tag)
}

func repeatString(str *Node, count *Node) (*Node, error) {
	_, n, err := parseInt64(count.Value)
	if err != nil {
		return nil, err
	}
	if n < 0 {
		return nil, fmt.Errorf("cannot repeat string by a negative number (%v)", n)
	}
	return str.CreateReplacement(ScalarNode, "!!str", strings.Repeat(str.Value, int(n))), nil
}

func mergeArrays(d *evaluator, context Context, lhs *Node, rhs *Node, prefs multiplyPreferences) (*Node, error) {
	if prefs.AppendArrays {
		target := lhs.Copy()
		for _, c := range rhs.Content {
			target.AddChild(c)
		}
		return target, nil
	}
	if prefs.DeepMergeArrays {
		target := lhs.Copy()
		for i, c := range rhs.Content {
			if i < len(target.Content) {
				merged, err := multiply(prefs)(d, context, target.Content[i], c)
				if err != nil {
					return nil, err
				}
				m := merged.Copy()
				m.Parent = target
				m.Key = target.Content[i].Key
				target.Content[i] = m
			} else {
				target.AddChild(c)
			}
		}
		return target, nil
	}
	target := rhs.Copy()
	target.Parent = lhs.Parent
	target.Key = lhs.Key
	target.HeadComment = lhs.HeadComment
	target.LineComment = lhs.LineComment
	target.FootComment = lhs.FootComment
	target.Anchor = lhs.Anchor
	if rhs.LineComment != "" {
		target.LineComment = rhs.LineComment
	}
	return target, nil
}

func mergeObjects(d *evaluator, context Context, lhs *Node, rhs *Node, prefs multiplyPreferences) (*Node, error) {
	target := lhs.Copy()
	if err := mergeInto(d, context, target, rhs, prefs); err != nil {
		return nil, err
	}
	return target, nil
}

func mergeInto(d *evaluator, context Context, target *Node, rhs *Node, prefs multiplyPreferences) error {
	for i := 0; i+1 < len(rhs.Content); i += 2 {
		key := rhs.Content[i]
		value := rhs.Content[i+1]
		idx := target.findKeyIndex(key.Value)
		if idx < 0 {
			if prefs.AssignPrefs.OnlyWriteNull && value.Tag == "!!null" {
				// still add
			}
			target.AddKeyValueChild(key, value)
			continue
		}
		tv := target.Content[idx+1]
		rv := value
		if rv.Kind == AliasNode && rv.Alias != nil && tv.Kind != AliasNode {
			rv = rv.Alias
		}
		if prefs.AssignPrefs.OnlyWriteNull && tv.Tag != "!!null" {
			continue
		}
		if tv.Kind == MappingNode && rv.Kind == MappingNode {
			if err := mergeInto(d, context, tv, rv, prefs); err != nil {
				return err
			}
		} else if tv.Kind == SequenceNode && rv.Kind == SequenceNode {
			merged, err := mergeArrays(d, context, tv, rv, prefs)
			if err != nil {
				return err
			}
			tv.UpdateFrom(merged, prefs.AssignPrefs)
		} else if tv.Kind == MappingNode && rv.Tag == "!!null" {
			// null does not clobber maps
		} else {
			tv.UpdateFrom(rv, prefs.AssignPrefs)
		}
	}
	return nil
}

// ---- divide

func divideOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return crossFunction(d, context.ReadOnlyClone(), expressionNode, divide, false)
}

func divide(d *evaluator, context Context, lhs *Node, rhs *Node) (*Node, error) {
	if lhs.Kind == AliasNode && lhs.Alias != nil {
		lhs = lhs.Alias
	}
	if rhs.Kind == AliasNode && rhs.Alias != nil {
		rhs = rhs.Alias
	}
	if lhs.Tag == "!!null" {
		return nil, fmt.Errorf("%v (%v) cannot be divided by %v (%v)", lhs.Tag, lhs.GetNicePath(), rhs.Tag, rhs.GetNicePath())
	}
	target := lhs.CopyWithoutContent()
	if lhs.Kind == MappingNode || lhs.Kind == SequenceNode {
		return nil, fmt.Errorf("%v (%v) cannot be divided by %v (%v)", lhs.Tag, lhs.GetNicePath(), rhs.Tag, rhs.GetNicePath())
	}
	if rhs.Kind != ScalarNode {
		return nil, fmt.Errorf("%v (%v) cannot be divided by %v (%v)", lhs.Tag, lhs.GetNicePath(), rhs.Tag, rhs.GetNicePath())
	}
	lhsTag := nodeTag(lhs)
	rhsTag := nodeTag(rhs)
	lhsIsCustom := !strings.HasPrefix(lhs.Tag, "!!")
	if lhsTag == "!!str" && rhsTag == "!!str" {
		res := lhs.CreateReplacement(SequenceNode, "!!seq", "")
		res.Style = 0
		for _, part := range strings.Split(lhs.Value, rhs.Value) {
			res.AddChild(createStringScalar(part))
		}
		return res, nil
	} else if (lhsTag == "!!int" || lhsTag == "!!float") && (rhsTag == "!!int" || rhsTag == "!!float") {
		lhsNum, err := strconv.ParseFloat(lhs.Value, 64)
		if err != nil {
			return nil, err
		}
		rhsNum, err := strconv.ParseFloat(rhs.Value, 64)
		if err != nil {
			return nil, err
		}
		quotient := lhsNum / rhsNum
		target.Kind = ScalarNode
		target.Style = lhs.Style
		if lhsIsCustom {
			target.Tag = lhs.Tag
		} else {
			target.Tag = "!!float"
		}
		target.Value = formatFloat(quotient)
		return target, nil
	}
	return nil, fmt.Errorf("%v cannot be divided by %v", lhs.Tag, rhs.Tag)
}

// ---- modulo

func moduloOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return crossFunction(d, context.ReadOnlyClone(), expressionNode, modulo, false)
}

func modulo(d *evaluator, context Context, lhs *Node, rhs *Node) (*Node, error) {
	if lhs.Kind == AliasNode && lhs.Alias != nil {
		lhs = lhs.Alias
	}
	if rhs.Kind == AliasNode && rhs.Alias != nil {
		rhs = rhs.Alias
	}
	if lhs.Tag == "!!null" {
		return nil, fmt.Errorf("%v (%v) cannot modulo by %v (%v)", lhs.Tag, lhs.GetNicePath(), rhs.Tag, rhs.GetNicePath())
	}
	target := lhs.CopyWithoutContent()
	if lhs.Kind == MappingNode || lhs.Kind == SequenceNode || rhs.Kind != ScalarNode {
		return nil, fmt.Errorf("%v (%v) cannot modulo by %v (%v)", lhs.Tag, lhs.GetNicePath(), rhs.Tag, rhs.GetNicePath())
	}
	lhsTag := nodeTag(lhs)
	rhsTag := nodeTag(rhs)
	lhsIsCustom := !strings.HasPrefix(lhs.Tag, "!!")
	if lhsTag == "!!int" && rhsTag == "!!int" {
		format, lhsNum, err := parseInt64(lhs.Value)
		if err != nil {
			return nil, err
		}
		_, rhsNum, err := parseInt64(rhs.Value)
		if err != nil {
			return nil, err
		}
		if rhsNum == 0 {
			return nil, fmt.Errorf("cannot modulo by 0")
		}
		target.Kind = ScalarNode
		target.Style = lhs.Style
		target.Tag = lhs.Tag
		target.Value = fmt.Sprintf(format, lhsNum%rhsNum)
		return target, nil
	} else if (lhsTag == "!!int" || lhsTag == "!!float") && (rhsTag == "!!int" || rhsTag == "!!float") {
		lhsNum, err := strconv.ParseFloat(lhs.Value, 64)
		if err != nil {
			return nil, err
		}
		rhsNum, err := strconv.ParseFloat(rhs.Value, 64)
		if err != nil {
			return nil, err
		}
		if rhsNum == 0 {
			return nil, fmt.Errorf("cannot modulo by 0")
		}
		target.Kind = ScalarNode
		target.Style = lhs.Style
		if lhsIsCustom {
			target.Tag = lhs.Tag
		} else {
			target.Tag = "!!float"
		}
		target.Value = formatFloat(math.Mod(lhsNum, rhsNum))
		return target, nil
	}
	return nil, fmt.Errorf("%v cannot modulo by %v", lhs.Tag, rhs.Tag)
}
