// matchKey does a wildcard match where '*' matches any sequence of characters.
func matchKey(name string, pattern string) bool {
	if pattern == "" {
		return name == ""
	}
	return deepMatch([]rune(name), []rune(pattern))
}

func deepMatch(str, pattern []rune) bool {
	for len(pattern) > 0 {
		switch pattern[0] {
		default:
			if len(str) == 0 || str[0] != pattern[0] {
				return false
			}
		case '*':
			return deepMatch(str, pattern[1:]) ||
				(len(str) > 0 && deepMatch(str[1:], pattern))
		}
		str = str[1:]
		pattern = pattern[1:]
	}
	return len(str) == 0 && len(pattern) == 0
}

func isEquals(flip bool) crossFunctionCalculation {
	return func(d *evaluator, context Context, lhs *Node, rhs *Node) (*Node, error) {
		value := false
		if lhs == nil && rhs == nil {
			owner := &Node{}
			return createBooleanCandidate(owner, !flip), nil
		} else if lhs == nil {
			value = rhs.Tag == "!!null"
			if flip {
				value = !value
			}
			return createBooleanCandidate(rhs, value), nil
		} else if rhs == nil {
			value = lhs.Tag == "!!null"
			if flip {
				value = !value
