		lhs = unwrapAlias(lhs)
		rhs = unwrapAlias(rhs)
		if lhs.Tag == "!!null" {
			value = rhs.Tag == "!!null"
		} else if lhs.Kind == ScalarNode && rhs.Kind == ScalarNode {
			value = matchKey(lhs.Value, rhs.Value)
		}
		if flip {
			value = !value
		}
		return createBooleanCandidate(lhs, value), nil
	}
}

