	return func(d *evaluator, context Context, lhs *Node, rhs *Node) (*Node, error) {
		if lhs == nil && rhs == nil {
			owner := &Node{}
			return createBooleanCandidate(owner, prefs.OrEqual), nil
		} else if lhs == nil {
			return createBooleanCandidate(rhs, false), nil
		} else if rhs == nil {
