		}
		rhsNum, err := strconv.ParseFloat(rhs.Value, 64)
		if err != nil {
			return false, err
		}
		if prefs.OrEqual && lhsNum == rhsNum {
			return true, nil
		} else if prefs.Greater {
			return lhsNum > rhsNum, nil
		}
		return lhsNum < rhsNum, nil
	}
	return false, fmt.Errorf("%v not yet supported for comparison", lhs.Tag)
}

func compareStrings(prefs compareTypePref, lhs string, rhs string) bool {
	cmp := strings.Compare(lhs, rhs)
	if prefs.OrEqual && cmp == 0 {
		return true
	}
	if prefs.Greater {
		return cmp > 0
	}
	return cmp < 0
}

func parseDateTime(layout string, datestring string) (time.Time, error) {
	parsedTime, err := time.Parse(layout, datestring)
	if err != nil && layout == time.RFC3339 {
		// try parsing the date time with only the date
		parsedTime, err = time.Parse("2006-01-02", datestring)
	}
	return parsedTime, err
}
