// recursiveNodeEqual compares two nodes deeply (by kind, tag and value).
func recursiveNodeEqual(lhs *Node, rhs *Node) bool {
	lhs = unwrapAlias(lhs)
	rhs = unwrapAlias(rhs)
	if lhs.Kind != rhs.Kind {
		return false
	}
	if lhs.Kind == ScalarNode {
		return lhs.Tag == rhs.Tag && lhs.Value == rhs.Value
	}
	if len(lhs.Content) != len(rhs.Content) {
		return false
	}
	if lhs.Kind == MappingNode {
		for i := 0; i+1 < len(lhs.Content); i += 2 {
			key := lhs.Content[i]
			idx := rhs.findKeyIndex(key.Value)
			if idx < 0 {
				return false
			}
			if !recursiveNodeEqual(lhs.Content[i+1], rhs.Content[idx+1]) {
				return false
			}
		}
		return true
	}
	for i := range lhs.Content {
		if !recursiveNodeEqual(lhs.Content[i], rhs.Content[i]) {
			return false
		}
	}
	return true
}

// ---- length

func lengthOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		targetNode := unwrapAlias(candidate)
		var length int
		switch targetNode.Kind {
		case MappingNode:
			length = len(targetNode.Content) / 2
		case SequenceNode:
			length = len(targetNode.Content)
		case ScalarNode:
			if targetNode.Tag == "!!null" {
				length = 0
			} else {
				length = len([]rune(targetNode.Value))
			}
		default:
			length = 0
		}
		result := candidate.CreateReplacement(ScalarNode, "!!int", fmt.Sprintf("%v", length))
		results.PushBack(result)
	}
	return context.ChildContext(results), nil
}

// ---- keys

func keysOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		var targetNode *Node
		if node.Kind == MappingNode {
			targetNode = getMapKeys(candidate, node)
		} else if node.Kind == SequenceNode {
			targetNode = getIndices(candidate, node)
		} else {
			return Context{}, fmt.Errorf("cannot get keys of %v, keys only works for maps and arrays", node.Tag)
		}
		results.PushBack(targetNode)
	}
	return context.ChildContext(results), nil
}

func getMapKeys(original *Node, node *Node) *Node {
	keys := original.CreateReplacement(SequenceNode, "!!seq", "")
	for index := 0; index < len(node.Content); index = index + 2 {
		keys.AddChild(node.Content[index])
	}
	return keys
}

func getIndices(original *Node, node *Node) *Node {
	keys := original.CreateReplacement(SequenceNode, "!!seq", "")
	for index := range node.Content {
		keys.AddChild(createScalar("!!int", fmt.Sprintf("%v", index)))
	}
	return keys
}

