func hasOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	wanted := ""
	wantedTag := ""
	if rhs.MatchingNodes.Len() > 0 {
		first := rhs.MatchingNodes.Front().Value.(*Node)
		wanted = first.Value
		wantedTag = first.Tag
	}
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		result := false
		if node.Kind == MappingNode {
			result = node.findKeyIndex(wanted) >= 0
		} else if node.Kind == SequenceNode {
			if wantedTag == "!!int" {
				idx, err := strconv.Atoi(wanted)
				if err == nil && idx < len(node.Content) {
					result = true
				}
			}
		}
		results.PushBack(createBooleanCandidate(candidate, result))
	}
	return context.ChildContext(results), nil
}

// ---- delete

func deleteChildOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	contextToUse := context.ReadOnlyClone()
	nodesToDelete, err := d.GetMatchingNodes(contextToUse, expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	for el := nodesToDelete.MatchingNodes.Back(); el != nil; el = el.Prev() {
		candidate := el.Value.(*Node)
		if candidate.Parent == nil {
			// can't delete the root
			continue
		}
		parentNode := candidate.Parent
		deleteFromParent(parentNode, candidate)
	}
	return context, nil
}

func deleteFromParent(parentNode *Node, candidate *Node) {
	if parentNode.Kind == MappingNode {
		newContent := make([]*Node, 0, len(parentNode.Content))
		for i := 0; i+1 < len(parentNode.Content); i += 2 {
			if parentNode.Content[i+1] != candidate && parentNode.Content[i] != candidate {
				newContent = append(newContent, parentNode.Content[i], parentNode.Content[i+1])
			}
		}
		parentNode.Content = newContent
	} else if parentNode.Kind == SequenceNode {
		newContent := make([]*Node, 0, len(parentNode.Content))
		for _, c := range parentNode.Content {
			if c != candidate {
				newContent = append(newContent, c)
			}
		}
		parentNode.Content = newContent
		// reindex keys
		for i, c := range parentNode.Content {
			c.Key = createScalar("!!int", strconv.Itoa(i))
		}
	}
}

// ---- entries

func toEntriesOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		switch node.Kind {
		case MappingNode:
			results.PushBack(toEntriesFromMap(candidate, node))
		case SequenceNode:
			results.PushBack(toEntriesFromSeq(candidate, node))
		default:
			if node.Tag != "!!null" {
				return Context{}, fmt.Errorf("%v has no keys", node.Tag)
			}
		}
	}
	return context.ChildContext(results), nil
}

func entrySeqFor(key *Node, value *Node) *Node {
	node := &Node{Kind: MappingNode, Tag: "!!map"}
	node.AddKeyValueChild(createStringScalar("key"), key)
	node.AddKeyValueChild(createStringScalar("value"), value)
	return node
}

func toEntriesFromMap(original *Node, node *Node) *Node {
	entriesNode := original.CreateReplacement(SequenceNode, "!!seq", "")
	for index := 0; index+1 < len(node.Content); index = index + 2 {
		key := node.Content[index]
		value := node.Content[index+1]
		entriesNode.AddChild(entrySeqFor(key, value))
	}
	return entriesNode
}

func toEntriesFromSeq(original *Node, node *Node) *Node {
	entriesNode := original.CreateReplacement(SequenceNode, "!!seq", "")
	for index := 0; index < len(node.Content); index = index + 1 {
		key := createScalar("!!int", fmt.Sprintf("%v", index))
		value := node.Content[index]
		entriesNode.AddChild(entrySeqFor(key, value))
	}
	return entriesNode
}

func parseEntry(entry *Node, position int) (*Node, *Node, error) {
	entry = unwrapAlias(entry)
	var key, value *Node
	if entry.Kind == MappingNode {
		for i := 0; i+1 < len(entry.Content); i += 2 {
			k := entry.Content[i]
			if k.Value == "key" || k.Value == "k" {
				if key == nil {
					key = entry.Content[i+1]
				}
			} else if k.Value == "value" || k.Value == "v" {
				if value == nil {
					value = entry.Content[i+1]
				}
			}
		}
	}
	if key == nil {
		return nil, nil, fmt.Errorf("expected to find one 'key' entry but found 0 in position %v", position)
	}
	if value == nil {
		return nil, nil, fmt.Errorf("expected to find one 'value' entry but found 0 in position %v", position)
	}
	return key, value, nil
}

func fromEntries(candidate *Node, node *Node) (*Node, error) {
	mapNode := candidate.CreateReplacement(MappingNode, "!!map", "")
	for index, entry := range node.Content {
		key, value, err := parseEntry(entry, index)
		if err != nil {
			return nil, err
		}
		k := key.Copy()
		if k.Kind == ScalarNode {
			k.Tag = "!!str"
			k.Style = 0
		}
		mapNode.AddKeyValueChild(k, value)
	}
	return mapNode, nil
}

func fromEntriesOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		switch node.Kind {
		case SequenceNode:
			mapNode, err := fromEntries(candidate, node)
			if err != nil {
				return Context{}, err
			}
			results.PushBack(mapNode)
		default:
			return Context{}, fmt.Errorf("from entries only runs against arrays")
		}
	}
	return context.ChildContext(results), nil
}

func withEntriesOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	// to_entries | map(f) | from_entries  (per node)
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		toEntries, err := toEntriesOperator(d, context.SingleChildContext(candidate), nil)
		if err != nil {
			return Context{}, err
		}
		if toEntries.MatchingNodes.Len() == 0 {
			continue
		}
		entries := toEntries.MatchingNodes.Front().Value.(*Node)
		mapped := entries.CreateReplacement(SequenceNode, "!!seq", "")
		for _, entry := range entries.Content {
			res, err := d.GetMatchingNodes(context.SingleChildContext(entry), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			for rel := res.MatchingNodes.Front(); rel != nil; rel = rel.Next() {
				mapped.AddChild(rel.Value.(*Node))
			}
		}
		mapNode, err := fromEntries(candidate, mapped)
		if err != nil {
			return Context{}, err
		}
		results.PushBack(mapNode)
	}
	return context.ChildContext(results), nil
}

// ---- map / map_values

func mapOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind == ScalarNode && node.Tag != "!!null" {
			results.PushBack(candidate)
			continue
		}
		collected := candidate.CreateReplacement(SequenceNode, "!!seq", "")
		splatted, err := splat(context.SingleChildContext(candidate), traversePreferences{})
		if err != nil {
			return Context{}, err
		}
		if node.Kind == ScalarNode && node.Tag == "!!null" {
			results.PushBack(collected)
			continue
		}
		for sel := splatted.MatchingNodes.Front(); sel != nil; sel = sel.Next() {
			child := sel.Value.(*Node)
			res, err := d.GetMatchingNodes(context.SingleChildContext(child), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			for rel := res.MatchingNodes.Front(); rel != nil; rel = rel.Next() {
				collected.AddChild(rel.Value.(*Node))
			}
		}
		results.PushBack(collected)
	}
	return context.ChildContext(results), nil
}

func mapValuesOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	// .[] |= f
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		splatted, err := splat(context.SingleChildContext(candidate), traversePreferences{})
		if err != nil {
			return Context{}, err
		}
		for sel := splatted.MatchingNodes.Front(); sel != nil; sel = sel.Next() {
			child := sel.Value.(*Node)
			res, err := d.GetMatchingNodes(context.SingleChildContext(child), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			first := res.MatchingNodes.Front()
			if first != nil {
				child.UpdateFrom(first.Value.(*Node), assignPreferences{})
			}
		}
	}
	return context, nil
}

// ---- sort

type sortableNode struct {
	Node         *Node
	compareNodes []*Node
	dateTimeLayout string
}

type sortableNodeArray []sortableNode

func (a sortableNodeArray) Len() int      { return len(a) }
func (a sortableNodeArray) Swap(i, j int) { a[i], a[j] = a[j], a[i] }
func (a sortableNodeArray) Less(i, j int) bool {
	lhsNodes := a[i].compareNodes
	rhsNodes := a[j].compareNodes
	for k := 0; k < len(lhsNodes) && k < len(rhsNodes); k++ {
		lhs := lhsNodes[k]
		rhs := rhsNodes[k]
		if compareNodesForSort(lhs, rhs, a[i].dateTimeLayout) {
			return true
		}
		if compareNodesForSort(rhs, lhs, a[i].dateTimeLayout) {
			return false
		}
	}
	return false
}

func compareNodesForSort(lhs *Node, rhs *Node, dateTimeLayout string) bool {
	lhsTag := lhs.Tag
	rhsTag := rhs.Tag
	if !strings.HasPrefix(lhsTag, "!!") && lhs.Kind == ScalarNode {
		lhsTag = guessTag(lhs.Value)
	}
	if !strings.HasPrefix(rhsTag, "!!") && rhs.Kind == ScalarNode {
		rhsTag = guessTag(rhs.Value)
	}
	isDateTime := lhs.Tag == "!!timestamp"
	if lhsTag == "!!str" && dateTimeLayout != time.RFC3339 {
		_, err := parseDateTime(dateTimeLayout, lhs.Value)
		isDateTime = err == nil
	}
	if isDateTime {
		lhsTime, err1 := parseDateTime(dateTimeLayout, lhs.Value)
		rhsTime, err2 := parseDateTime(dateTimeLayout, rhs.Value)
		if err1 == nil && err2 == nil {
			return lhsTime.Before(rhsTime)
		}
	}
	if lhsTag == "!!null" && rhsTag != "!!null" {
		return true
	} else if lhsTag != "!!null" && rhsTag == "!!null" {
		return false
	} else if lhsTag == "!!bool" && rhsTag != "!!bool" {
		return true
	} else if lhsTag != "!!bool" && rhsTag == "!!bool" {
		return false
	} else if lhsTag == "!!bool" && rhsTag == "!!bool" {
		return !isTruthyNode(lhs) && isTruthyNode(rhs)
	} else if lhsTag == "!!int" && rhsTag == "!!int" {
		_, lhsNum, err1 := parseInt64(lhs.Value)
		_, rhsNum, err2 := parseInt64(rhs.Value)
		if err1 == nil && err2 == nil {
			return lhsNum < rhsNum
		}
	} else if (lhsTag == "!!int" || lhsTag == "!!float") && (rhsTag == "!!int" || rhsTag == "!!float") {
		lhsNum, err1 := strconv.ParseFloat(lhs.Value, 64)
		rhsNum, err2 := strconv.ParseFloat(rhs.Value, 64)
		if err1 == nil && err2 == nil {
			return lhsNum < rhsNum
		}
	}
	return lhs.Value < rhs.Value
}

func sortOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	selfExp := &ExpressionNode{Operation: &Operation{OperationType: selfReferenceOpType}}
	return sortBy(d, context, selfExp)
}

func sortByOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return sortBy(d, context, expressionNode.RHS)
}

func sortBy(d *evaluator, context Context, exp *ExpressionNode) (Context, error) {
	results := newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind == MappingNode {
			// sort maps as-is (no change)
			results.PushBack(candidate)
			continue
		}
		if node.Kind != SequenceNode {
			return Context{}, fmt.Errorf("node at path [%v] is not an array or map (it's a %v)", candidate.GetNicePath(), node.Tag)
		}
		sortableArray := make(sortableNodeArray, len(node.Content))
		for i, originalNode := range node.Content {
			sortableArray[i] = sortableNode{Node: originalNode, dateTimeLayout: context.GetDateTimeLayout()}
			compareContext, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(originalNode), exp)
			if err != nil {
				return Context{}, err
			}
			nodes := compareContext.MatchingNodes.Nodes()
			if len(nodes) == 0 {
				nodes = []*Node{{Kind: ScalarNode, Tag: "!!null", Value: ""}}
			}
			sortableArray[i].compareNodes = nodes
		}
		sort.Stable(sortableArray)
		sortedList := candidate.CreateReplacement(SequenceNode, "!!seq", "")
		sortedList.Style = node.Style
		for _, sortedNode := range sortableArray {
			sortedList.AddChild(sortedNode.Node)
		}
		results.PushBack(sortedList)
	}
	return context.ChildContext(results), nil
}

// ---- reverse

func reverseOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	results := newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind != SequenceNode {
			return Context{}, fmt.Errorf("node at path [%v] is not an array (it's a %v)", candidate.GetNicePath(), node.Tag)
		}
		reversedList := candidate.CreateReplacement(SequenceNode, "!!seq", "")
		reversedList.Style = node.Style
		for i := len(node.Content) - 1; i >= 0; i-- {
			reversedList.AddChild(node.Content[i])
		}
		results.PushBack(reversedList)
	}
	return context.ChildContext(results), nil
}

// ---- unique / group_by

func uniqueOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	selfExp := &ExpressionNode{Operation: &Operation{OperationType: selfReferenceOpType}}
	return uniqueBy(d, context, selfExp)
}

func uniqueByOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return uniqueBy(d, context, expressionNode.RHS)
}

func uniqueBy(d *evaluator, context Context, exp *ExpressionNode) (Context, error) {
	results := newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind != SequenceNode {
			return Context{}, fmt.Errorf("only arrays are supported for unique")
		}
		var newMatches = make(map[string]*Node)
		var order []string
		for _, child := range node.Content {
			rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(child), exp)
			if err != nil {
				return Context{}, err
			}
			keyValue := "null"
			if rhs.MatchingNodes.Len() > 0 {
				first := rhs.MatchingNodes.Front().Value.(*Node)
				keyValue = first.Value
			}
			if _, exists := newMatches[keyValue]; !exists {
				newMatches[keyValue] = child
				order = append(order, keyValue)
			}
		}
		resultNode := candidate.CreateReplacement(SequenceNode, "!!seq", "")
		for _, k := range order {
			resultNode.AddChild(newMatches[k])
		}
		results.PushBack(resultNode)
	}
	return context.ChildContext(results), nil
}

func groupByOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	results := newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind != SequenceNode {
			return Context{}, fmt.Errorf("only arrays are supported for group by")
		}
		var newMatches = make(map[string]*Node)
		var order []string
		for _, child := range node.Content {
			rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(child), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			keyValue := "null"
			if rhs.MatchingNodes.Len() > 0 {
				first := rhs.MatchingNodes.Front().Value.(*Node)
				keyValue = first.Value
			}
			group, exists := newMatches[keyValue]
			if !exists {
				group = &Node{Kind: SequenceNode, Tag: "!!seq"}
				newMatches[keyValue] = group
				order = append(order, keyValue)
			}
			group.AddChild(child)
		}
		resultNode := candidate.CreateReplacement(SequenceNode, "!!seq", "")
		for _, k := range order {
			resultNode.AddChild(newMatches[k])
		}
		results.PushBack(resultNode)
	}
	return context.ChildContext(results), nil
}

// ---- min / max

func minOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return minMax(d, context, compareTypePref{Greater: false})
}

func maxOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return minMax(d, context, compareTypePref{Greater: true})
}

func minMax(d *evaluator, context Context, prefs compareTypePref) (Context, error) {
	results := newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		var children []*Node
		if node.Kind == SequenceNode {
			children = node.Content
		} else if node.Kind == MappingNode {
			for i := 1; i < len(node.Content); i += 2 {
				children = append(children, node.Content[i])
			}
		} else {
			continue
		}
		if len(children) == 0 {
			continue
		}
		current := children[0]
		for _, child := range children[1:] {
			res, err := compare(prefs)(d, context, child, current)
			if err != nil {
				return Context{}, err
			}
			if res.Value == "true" {
				current = child
			}
		}
		results.PushBack(current)
	}
	return context.ChildContext(results), nil
}

// ---- contains

func containsOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	return crossFunction(d, context.ReadOnlyClone(), expressionNode, containsCalc, false)
}

func containsCalc(d *evaluator, context Context, lhs *Node, rhs *Node) (*Node, error) {
	lhs = unwrapAlias(lhs)
	rhs = unwrapAlias(rhs)
	if lhs.Kind != rhs.Kind {
		return nil, fmt.Errorf("%v cannot check contained in %v", rhs.Tag, lhs.Tag)
	}
	result, err := containsNode(lhs, rhs)
	if err != nil {
		return nil, err
	}
	return createBooleanCandidate(lhs, result), nil
}

func containsNode(lhs *Node, rhs *Node) (bool, error) {
	lhs = unwrapAlias(lhs)
	rhs = unwrapAlias(rhs)
	if lhs.Kind != rhs.Kind {
		return false, fmt.Errorf("%v cannot check contained in %v", rhs.Tag, lhs.Tag)
	}
	switch lhs.Kind {
	case MappingNode:
		for i := 0; i+1 < len(rhs.Content); i += 2 {
			key := rhs.Content[i]
			idx := lhs.findKeyIndex(key.Value)
			if idx < 0 {
				return false, nil
			}
			ok, err := containsNode(lhs.Content[idx+1], rhs.Content[i+1])
			if err != nil {
				return false, err
			}
			if !ok {
				return false, nil
			}
		}
		return true, nil
	case SequenceNode:
		for _, r := range rhs.Content {
			found := false
			for _, l := range lhs.Content {
				l2 := unwrapAlias(l)
				r2 := unwrapAlias(r)
				if l2.Kind != r2.Kind {
					continue
				}
				ok, err := containsNode(l2, r2)
				if err != nil {
					return false, err
				}
				if ok {
					found = true
					break
				}
			}
			if !found {
				return false, nil
			}
		}
		return true, nil
	default:
		if lhs.Tag == "!!str" && rhs.Tag == "!!str" {
			return strings.Contains(lhs.Value, rhs.Value), nil
		}
		return lhs.Tag == rhs.Tag && lhs.Value == rhs.Value, nil
	}
}

// ---- flatten

func flattenOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	depth := -1
	if p, ok := expressionNode.Operation.Preferences.(flattenPreferences); ok {
		depth = p.depth
	}
	results := newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind != SequenceNode {
			return Context{}, fmt.Errorf("only arrays are supported for flatten")
		}
		flat := candidate.CreateReplacement(SequenceNode, "!!seq", "")
		flat.Style = node.Style
		flattenArray(flat, node, depth)
		results.PushBack(flat)
	}
	return context.ChildContext(results), nil
}

func flattenArray(target *Node, node *Node, depth int) {
	for _, child := range node.Content {
		c := unwrapAlias(child)
		if c.Kind == SequenceNode && depth != 0 {
			flattenArray(target, c, depth-1)
		} else {
			target.AddChild(child)
		}
	}
}

// ---- pick / omit

func pickOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	results := newNodeList()
	rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	var indices []*Node
	if rhs.MatchingNodes.Len() > 0 {
		first := rhs.MatchingNodes.Front().Value.(*Node)
		if first.Kind == SequenceNode {
			indices = first.Content
		}
	}
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		var replacement *Node
		if node.Kind == MappingNode {
			replacement = candidate.CreateReplacementWithComments(MappingNode, "!!map", node.Style)
			for _, index := range indices {
				idx := node.findKeyIndex(index.Value)
				if idx >= 0 {
					replacement.AddKeyValueChild(node.Content[idx], node.Content[idx+1])
				}
			}
		} else if node.Kind == SequenceNode {
			replacement = candidate.CreateReplacementWithComments(SequenceNode, "!!seq", node.Style)
			for _, index := range indices {
				idx, err := strconv.Atoi(index.Value)
				if err == nil && idx >= 0 && idx < len(node.Content) {
					replacement.AddChild(node.Content[idx])
				}
			}
		} else {
			return Context{}, fmt.Errorf("cannot pick indices from type %v (%v)", node.Tag, candidate.GetNicePath())
		}
		results.PushBack(replacement)
	}
	return context.ChildContext(results), nil
}

func omitOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	results := newNodeList()
	rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	var indices []*Node
	if rhs.MatchingNodes.Len() > 0 {
		first := rhs.MatchingNodes.Front().Value.(*Node)
		if first.Kind == SequenceNode {
			indices = first.Content
		}
	}
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		var replacement *Node
		if node.Kind == MappingNode {
			replacement = candidate.CreateReplacementWithComments(MappingNode, "!!map", node.Style)
			for i := 0; i+1 < len(node.Content); i += 2 {
				skip := false
				for _, index := range indices {
					if index.Value == node.Content[i].Value {
						skip = true
						break
					}
				}
				if !skip {
					replacement.AddKeyValueChild(node.Content[i], node.Content[i+1])
				}
			}
		} else if node.Kind == SequenceNode {
			replacement = candidate.CreateReplacementWithComments(SequenceNode, "!!seq", node.Style)
			for i, c := range node.Content {
				skip := false
				for _, index := range indices {
					idx, err := strconv.Atoi(index.Value)
					if err == nil && idx == i {
						skip = true
						break
					}
				}
				if !skip {
					replacement.AddChild(c)
				}
			}
		} else {
			return Context{}, fmt.Errorf("cannot omit indices from type %v (%v)", node.Tag, candidate.GetNicePath())
		}
		results.PushBack(replacement)
	}
	return context.ChildContext(results), nil
}

// ---- path operators

func createPathNodeFor(pathElement interface{}) *Node {
	switch v := pathElement.(type) {
	case string:
		return createStringScalar(v)
	default:
		return createScalar("!!int", fmt.Sprintf("%v", pathElement))
	}
}

func getPathArrayFromNode(funcName string, node *Node) ([]interface{}, error) {
	if node.Kind != SequenceNode {
		return nil, fmt.Errorf("%v: expected path array, but got %v instead", funcName, node.Tag)
	}
	path := make([]interface{}, len(node.Content))
	for i, childNode := range node.Content {
		if childNode.Tag == "!!int" {
			number, err := parseIntValue(childNode.Value)
			if err != nil {
				return nil, fmt.Errorf("%v: could not parse %v as an int: %w", funcName, childNode.Value, err)
			}
			path[i] = number
		} else {
			path[i] = childNode.Value
		}
	}
	return path, nil
}

func getPathOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := candidate.CreateReplacement(SequenceNode, "!!seq", "")
		for _, pathElement := range candidate.GetPath() {
			node.AddChild(createPathNodeFor(pathElement))
		}
		results.PushBack(node)
	}
	return context.ChildContext(results), nil
}

func createTraversalTree(path []interface{}, traversePrefs traversePreferences, targetKey bool) *ExpressionNode {
	if len(path) == 0 {
		return &ExpressionNode{Operation: &Operation{OperationType: selfReferenceOpType}}
	} else if len(path) == 1 {
		lastPrefs := traversePrefs
		if targetKey {
			lastPrefs.IncludeMapKeys = true
			lastPrefs.DontIncludeMapValues = true
		}
		return &ExpressionNode{Operation: &Operation{OperationType: traversePathOpType, Preferences: lastPrefs, Value: path[0], StringValue: fmt.Sprintf("%v", path[0]), CandidateNode: createPathNodeFor(path[0])}}
	}
	return &ExpressionNode{
		Operation: &Operation{OperationType: shortPipeOpType},
		LHS:       createTraversalTree(path[0:1], traversePrefs, false),
		RHS:       createTraversalTree(path[1:], traversePrefs, targetKey),
	}
}

func setPathOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode.RHS.Operation.OperationType != blockOpType {
		return Context{}, fmt.Errorf("SETPATH must be given a block (;), got %v instead", expressionNode.RHS.Operation.OperationType.Type)
	}
	lhsPath, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS.LHS)
	if err != nil {
		return Context{}, err
	}
	if lhsPath.MatchingNodes.Len() != 1 {
		return Context{}, fmt.Errorf("SETPATH: expected single path but found %v results instead", lhsPath.MatchingNodes.Len())
	}
	lhsValue := lhsPath.MatchingNodes.Front().Value.(*Node)
	lhsPathArray, err := getPathArrayFromNode("SETPATH", lhsValue)
	if err != nil {
		return Context{}, err
	}
	lhsTraversalTree := createTraversalTree(lhsPathArray, traversePreferences{}, false)
	assignmentOp := &Operation{OperationType: assignOpType, Preferences: assignPreferences{}}
	assignmentOpNode := &ExpressionNode{Operation: assignmentOp, LHS: lhsTraversalTree, RHS: expressionNode.RHS.RHS}
	return d.GetMatchingNodes(context, assignmentOpNode)
}

func delPathsOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	// single RHS expression that returns an array of paths
	pathsToDelete, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	if pathsToDelete.MatchingNodes.Len() != 1 {
		return Context{}, fmt.Errorf("DELPATHS: expected single value but found %v", pathsToDelete.MatchingNodes.Len())
	}
	pathArraysNode := pathsToDelete.MatchingNodes.Front().Value.(*Node)
	if pathArraysNode.Kind != SequenceNode {
		return Context{}, fmt.Errorf("DELPATHS: expected a sequence of sequences, but found %v", pathArraysNode.Tag)
	}
	results := context
	for i, child := range pathArraysNode.Content {
		if child.Kind != SequenceNode {
			return Context{}, fmt.Errorf("DELPATHS: expected entry [%v] to be a sequence, but its a %v. Note that delpaths takes an array of path arrays, e.g. [[\"a\", \"b\"]]", i, child.Tag)
		}
		childPath, err := getPathArrayFromNode("DELPATHS", child)
		if err != nil {
			return Context{}, err
		}
		childTraversalExp := createTraversalTree(childPath, traversePreferences{}, false)
		deleteChildOp := &Operation{OperationType: deleteChildOpType}
		deleteChildOpNode := &ExpressionNode{Operation: deleteChildOp, RHS: childTraversalExp}
		results, err = d.GetMatchingNodes(results, deleteChildOpNode)
		if err != nil {
			return Context{}, err
		}
	}
	return results, nil
}

// ---- filter / first

func filterOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		collected := candidate.CreateReplacement(SequenceNode, "!!seq", "")
		splatted, err := splat(context.SingleChildContext(candidate), traversePreferences{})
		if err != nil {
			return Context{}, err
		}
		for sel := splatted.MatchingNodes.Front(); sel != nil; sel = sel.Next() {
			child := sel.Value.(*Node)
			res, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(child), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			first := res.MatchingNodes.Front()
			if first != nil && isTruthyNode(first.Value.(*Node)) {
				collected.AddChild(child)
			}
		}
		results.PushBack(collected)
	}
	return context.ChildContext(results), nil
}

func firstOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		splatted, err := splat(context.SingleChildContext(candidate), traversePreferences{})
		if err != nil {
			return Context{}, err
		}
		for sel := splatted.MatchingNodes.Front(); sel != nil; sel = sel.Next() {
			child := sel.Value.(*Node)
			res, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(child), expressionNode.RHS)
			if err != nil {
				return Context{}, err
			}
			first := res.MatchingNodes.Front()
			if first != nil && isTruthyNode(first.Value.(*Node)) {
				results.PushBack(child)
				break
			}
		}
	}
	return context.ChildContext(results), nil
}

// ---- pivot

func pivotOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind != SequenceNode {
			return Context{}, fmt.Errorf("cannot pivot node of type %v", node.Tag)
		}
		if len(node.Content) == 0 {
			results.PushBack(candidate.CreateReplacement(SequenceNode, "!!seq", ""))
			continue
		}
		first := unwrapAlias(node.Content[0])
		if first.Kind == MappingNode {
			result := candidate.CreateReplacement(MappingNode, "!!map", "")
			var keys []string
			for _, row := range node.Content {
				row = unwrapAlias(row)
				for i := 0; i+1 < len(row.Content); i += 2 {
					k := row.Content[i].Value
					found := false
					for _, existing := range keys {
						if existing == k {
							found = true
							break
						}
					}
					if !found {
						keys = append(keys, k)
					}
				}
			}
			for _, k := range keys {
				column := &Node{Kind: SequenceNode, Tag: "!!seq"}
				for _, row := range node.Content {
					row = unwrapAlias(row)
					idx := row.findKeyIndex(k)
					if idx >= 0 {
						column.AddChild(row.Content[idx+1])
					} else {
						column.AddChild(createNull())
					}
				}
				result.AddKeyValueChild(createStringScalar(k), column)
			}
			results.PushBack(result)
		} else if first.Kind == SequenceNode {
			result := candidate.CreateReplacement(SequenceNode, "!!seq", "")
			maxLen := 0
			for _, row := range node.Content {
				if len(unwrapAlias(row).Content) > maxLen {
					maxLen = len(unwrapAlias(row).Content)
				}
			}
			for i := 0; i < maxLen; i++ {
				column := &Node{Kind: SequenceNode, Tag: "!!seq"}
				for _, row := range node.Content {
					row = unwrapAlias(row)
					if i < len(row.Content) {
						column.AddChild(row.Content[i])
					} else {
						column.AddChild(createNull())
					}
				}
				result.AddChild(column)
			}
			results.PushBack(result)
		} else {
			return Context{}, fmt.Errorf("can only pivot elements of !!seq or !!map types, received %v", first.Tag)
		}
	}
	return context.ChildContext(results), nil
}

// ---- shuffle

func shuffleOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	results := newNodeList()
	rnd := rand.New(rand.NewSource(time.Now().UnixNano()))
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind != SequenceNode {
			return Context{}, fmt.Errorf("node at path [%v] is not an array (it's a %v)", candidate.GetNicePath(), node.Tag)
		}
		result := candidate.CreateReplacement(SequenceNode, "!!seq", "")
		result.Style = node.Style
		perm := rnd.Perm(len(node.Content))
		for _, i := range perm {
			result.AddChild(node.Content[i])
		}
		results.PushBack(result)
	}
	return context.ChildContext(results), nil
}
