// ---- explode

func explodeOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		rhs, err := d.GetMatchingNodes(context.SingleChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		for childEl := rhs.MatchingNodes.Front(); childEl != nil; childEl = childEl.Next() {
			err = explodeNode(childEl.Value.(*Node), context)
			if err != nil {
				return Context{}, err
			}
		}
	}
	return context, nil
}

func explodeNode(node *Node, context Context) error {
	node.Anchor = ""
	switch node.Kind {
	case SequenceNode:
		for _, child := range node.Content {
			if err := explodeNode(child, context); err != nil {
				return err
			}
		}
	case AliasNode:
		if node.Alias != nil {
			target := node.Alias
			node.Kind = target.Kind
			node.Style = target.Style
			node.Tag = target.Tag
			node.Value = target.Value
			node.Content = nil
			for i, c := range target.Content {
				cc := c.Copy()
				cc.Parent = node
				if target.Kind == MappingNode && i%2 == 1 {
					cc.Key = node.Content[i-1]
				}
				node.Content = append(node.Content, cc)
			}
			node.Alias = nil
			// the copied content may itself contain aliases
			return explodeNode(node, context)
		}
	case MappingNode:
		// map keys are not exploded
		var newContent []*Node
		for i := 0; i+1 < len(node.Content); i += 2 {
			keyNode := node.Content[i]
			valueNode := node.Content[i+1]
			if keyNode.Tag == "!!merge" {
				// merge anchor: explode the alias(es) and merge them in
				if err := applyMergeAlias(node, valueNode, &newContent, context); err != nil {
					return err
				}
			} else {
				if err := explodeNode(valueNode, context); err != nil {
					return err
				}
				newContent = overrideEntry(newContent, keyNode, valueNode)
			}
		}
		node.Content = newContent
	}
	return nil
}

func overrideEntry(content []*Node, key *Node, value *Node) []*Node {
	for i := 0; i+1 < len(content); i += 2 {
		if content[i].Value == key.Value {
			content[i] = key
			content[i+1] = value
			return content
		}
	}
	return append(content, key, value)
}

func applyMergeAlias(node *Node, valueNode *Node, newContent *[]*Node, context Context) error {
	switch valueNode.Kind {
	case AliasNode:
		if valueNode.Alias == nil {
			return nil
		}
		copied := valueNode.Alias.Copy()
		if err := explodeNode(copied, context); err != nil {
			return err
		}
		if copied.Kind != MappingNode {
			return fmt.Errorf("can only use merge anchors with maps (!!map), but got %v", copied.Tag)
		}
		for i := 0; i+1 < len(copied.Content); i += 2 {
			k := copied.Content[i]
			v := copied.Content[i+1]
			k.Parent = node
			v.Parent = node
			v.Key = k
			if !mergeKeyExists(*newContent, k.Value) && !existsLaterInMap(node, valueNode, k.Value) {
				*newContent = append(*newContent, k, v)
			}
		}
	case SequenceNode:
		for _, child := range valueNode.Content {
			if err := applyMergeAlias(node, child, newContent, context); err != nil {
				return err
			}
		}
	default:
		return fmt.Errorf("can only use merge anchors with maps (!!map), but got %v", valueNode.Tag)
	}
	return nil
}

func mergeKeyExists(content []*Node, key string) bool {
	for i := 0; i+1 < len(content); i += 2 {
		if content[i].Value == key {
			return true
		}
	}
	return false
}

// existsLaterInMap reports whether the key is explicitly defined in the map
// after the given merge value node (explicit keys win over merged ones).
func existsLaterInMap(node *Node, mergeValue *Node, key string) bool {
	found := false
	for i := 0; i+1 < len(node.Content); i += 2 {
		if node.Content[i+1] == mergeValue {
			found = true
			continue
		}
		if found && node.Content[i].Tag != "!!merge" && node.Content[i].Value == key {
			return true
		}
	}
	return false
}

// ---- comments

var startCommentCharacterRegExp = regexp.MustCompile("^# ")
var subsequentCommentCharacterRegExp = regexp.MustCompile("\n# ")

func getCommentsOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	preferences := expressionNode.Operation.Preferences.(commentOpPreferences)
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		comment := ""
		if preferences.LineComment {
			comment = candidate.LineComment
		} else if preferences.HeadComment && candidate.LeadingContent != "" {
			var output strings.Builder
			reader := bufio.NewReader(strings.NewReader(candidate.LeadingContent))
			for {
				readline, errReading := reader.ReadString('\n')
				if errReading != nil && !errors.Is(errReading, io.EOF) {
					return Context{}, errReading
				}
				if !strings.Contains(readline, "$yqDocSeparator$") {
					output.WriteString(readline)
				}
				if errors.Is(errReading, io.EOF) {
					break
				}
			}
			comment = output.String()
			comment = regexp.MustCompile(`\n$`).ReplaceAllString(comment, "")
		} else if preferences.HeadComment {
			comment = candidate.HeadComment
		} else if preferences.FootComment {
			comment = candidate.FootComment
		}
		comment = startCommentCharacterRegExp.ReplaceAllString(comment, "")
		comment = subsequentCommentCharacterRegExp.ReplaceAllString(comment, "\n")
		result := candidate.CreateReplacement(ScalarNode, "!!str", comment)
		results.PushBack(result)
	}
	return context.ChildContext(results), nil
}

