func getParentOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	prefs := parentOpPreferences{Level: 1}
	if p, ok := expressionNode.Operation.Preferences.(parentOpPreferences); ok {
		prefs = p
	}
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		currentLevel := 0
		for currentLevel < prefs.Level && candidate != nil {
			candidate = candidate.Parent
			currentLevel++
		}
		if prefs.Level < 0 {
			for candidate != nil && candidate.Parent != nil {
				candidate = candidate.Parent
			}
		}
		if candidate != nil {
			results.PushBack(candidate)
		}
	}
	return context.ChildContext(results), nil
