	var index uint
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		clone := candidate.CopyWithoutContent()
		clone.Content = candidate.Content
		clone.Parent = nil
		clone.Document = index
		clone.FileIndex = candidate.GetFileIndex()
		clone.Filename = candidate.GetFilename()
		results.PushBack(clone)
		index++
	}
	return context.ChildContext(results), nil
}

// ---- recursive descent

func recursiveDescentOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	preferences := expressionNode.Operation.Preferences.(recursiveDescentPreferences)
	err := recursiveDecent(results, context, preferences)
	if err != nil {
		return Context{}, err
	}
	return context.ChildContext(results), nil
}

func recursiveDecent(results *NodeList, context Context, preferences recursiveDescentPreferences) error {
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		results.PushBack(candidate)
		if candidate.Kind != AliasNode && len(candidate.Content) > 0 &&
			(preferences.RecurseArray || candidate.Kind != SequenceNode) {
			children, err := splat(context.SingleChildContext(candidate), preferences.TraversePreferences)
			if err != nil {
				return err
			}
			err = recursiveDecent(results, children, preferences)
			if err != nil {
				return err
			}
		}
	}
	return nil
}

// ---- with

func withOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	// with(path, exp)
	if expressionNode.RHS.Operation.OperationType != blockOpType {
		return Context{}, fmt.Errorf("with must be given a block (;), got %v instead", expressionNode.RHS.Operation.OperationType.Type)
	}
	pathExp := expressionNode.RHS.LHS
	updateExp := expressionNode.RHS.RHS
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		pathContext, err := d.GetMatchingNodes(context.SingleChildContext(candidate), pathExp)
		if err != nil {
			return Context{}, err
		}
		_, err = d.GetMatchingNodes(pathContext, updateExp)
		if err != nil {
			return Context{}, err
		}
	}
	return context, nil
}

// ---- eval

func evalOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		expressions, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		for expEl := expressions.MatchingNodes.Front(); expEl != nil; expEl = expEl.Next() {
			expStr := expEl.Value.(*Node).Value
			tree, err := parseExpression(expStr)
			if err != nil {
				return Context{}, err
			}
			result, err := d.GetMatchingNodes(context.SingleChildContext(candidate), tree)
			if err != nil {
				return Context{}, err
			}
			for rel := result.MatchingNodes.Front(); rel != nil; rel = rel.Next() {
				results.PushBack(rel.Value)
			}
		}
	}
	return context.ChildContext(results), nil
}

// ---- error

func errorOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	rhs, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	errorMessage := "aborted"
	if rhs.MatchingNodes.Len() > 0 {
		errorMessage = rhs.MatchingNodes.Front().Value.(*Node).Value
	}
	return Context{}, errors.New(errorMessage)
}
