func addMatch(original *Node, match string, offset int, name string) *Node {
	newMatch := original.CreateReplacement(MappingNode, "!!map", "")
	newMatch.Parent = nil
	newMatch.Key = nil
	if offset < 0 {
		// no match
		newMatch.AddKeyValueChild(createStringScalar("string"), createNull())
	} else {
		newMatch.AddKeyValueChild(createStringScalar("string"), createStringScalar(match))
	}
	newMatch.AddKeyValueChild(createStringScalar("offset"), createScalar("!!int", fmt.Sprintf("%v", offset)))
	newMatch.AddKeyValueChild(createStringScalar("length"), createScalar("!!int", fmt.Sprintf("%v", len(match))))
	if name != "" {
		newMatch.AddKeyValueChild(createStringScalar("name"), createStringScalar(name))
	}
	return newMatch
}

func match(matchPrefs matchPreferences, regEx *regexp.Regexp, candidate *Node, value string, results *NodeList) {
	var allMatches [][]int
	if matchPrefs.Global {
		allMatches = regEx.FindAllStringSubmatchIndex(value, -1)
	} else {
		allMatches = [][]int{regEx.FindStringSubmatchIndex(value)}
	}
	subNames := regEx.SubexpNames()
	for _, matches := range allMatches {
		if len(matches) == 0 || matches[0] == -1 {
			continue
		}
		capturesNode := &Node{Kind: SequenceNode}
		match, submatches := matches[0], matches[1:]
		for i := 0; i < len(submatches); i += 2 {
			start, end := submatches[i], submatches[i+1]
			if start == -1 {
				cap := addMatch(candidate, "", -1, subNames[i/2+1])
				capturesNode.AddChild(cap)
			} else {
				cap := addMatch(candidate, value[start:end], start, subNames[i/2+1])
				capturesNode.AddChild(cap)
			}
		}
		node := addMatch(candidate, value[match:matches[1]], match, "")
		node.AddKeyValueChild(createStringScalar("captures"), capturesNode)
		results.PushBack(node)
	}
}

func matchOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	regExStr, matchPrefs, err := getMatchParams(d, context, expressionNode)
	if err != nil {
		return Context{}, err
	}
	regEx, err := regexp.Compile(regExStr)
	if err != nil {
		return Context{}, err
	}
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind != ScalarNode || nodeTag(node) != "!!str" {
			return Context{}, fmt.Errorf("cannot match with %v, can only match strings. Hint: Most often you'll want to use '|=' over '=' for this operation", node.Tag)
		}
		match(matchPrefs, regEx, candidate, node.Value, results)
	}
	return context.ChildContext(results), nil
}

func captureOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	regExStr, matchPrefs, err := getMatchParams(d, context, expressionNode)
	if err != nil {
		return Context{}, err
	}
	regEx, err := regexp.Compile(regExStr)
	if err != nil {
		return Context{}, err
