	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind != ScalarNode || nodeTag(node) != "!!str" {
			return Context{}, fmt.Errorf("cannot match with %v, can only match strings. Hint: Most often you'll want to use '|=' over '=' for this operation", node.Tag)
		}
		matches := newNodeList()
		match(matchPrefs, regEx, candidate, node.Value, matches)
		for mel := matches.Front(); mel != nil; mel = mel.Next() {
			matchNode := mel.Value.(*Node)
			capturesNode := matchNode.Content[len(matchNode.Content)-1]
			captureMap := candidate.CreateReplacement(MappingNode, "!!map", "")
			captureMap.Parent = nil
			captureMap.Key = nil
			for _, capture := range capturesNode.Content {
				name := ""
				var value *Node
				for i := 0; i+1 < len(capture.Content); i += 2 {
					if capture.Content[i].Value == "name" {
						name = capture.Content[i+1].Value
					}
					if capture.Content[i].Value == "string" {
						value = capture.Content[i+1]
					}
				}
				captureMap.AddKeyValueChild(createStringScalar(name), value)
			}
			results.PushBack(captureMap)
		}
	}
	return context.ChildContext(results), nil
}

