// ---- string interpolation

func stringInterpolationOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	if context.MatchingNodes.Len() == 0 {
		value, err := interpolate(d, context, expressionNode.Operation.StringValue)
		if err != nil {
			return Context{}, err
		}
		node := createStringScalar(value)
		results.PushBack(node)
		return context.ChildContext(results), nil
	}
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		value, err := interpolate(d, context.SingleChildContext(candidate), expressionNode.Operation.StringValue)
		if err != nil {
			return Context{}, err
		}
		node := candidate.CreateReplacement(ScalarNode, "!!str", value)
		results.PushBack(node)
	}
	return context.ChildContext(results), nil
}

func evaluateInterpolation(d *evaluator, context Context, expStr string) (string, error) {
	exp, err := parseExpression(expStr)
	if err != nil {
		return "", err
	}
	value, err := d.GetMatchingNodes(context, exp)
	if err != nil {
		return "", err
	}
	if value.MatchingNodes.Len() == 0 {
		return "", nil
	}
	node := value.MatchingNodes.Front().Value.(*Node)
	if node.Kind == ScalarNode {
		return node.Value, nil
	}
	s, err := encodeToString(node, "yaml", 2)
	if err != nil {
		return "", err
	}
	return chomp(s), nil
}

func interpolate(d *evaluator, context Context, str string) (string, error) {
	var sb strings.Builder
	var expSb strings.Builder
	inExpression := false
	nestedBracketsCounter := 0
	runes := []rune(str)
	for i := 0; i < len(runes); i++ {
		char := runes[i]
		if !inExpression {
			if char == '\\' && i+1 < len(runes) && runes[i+1] == '(' {
				inExpression = true
				i++
				continue
			}
			sb.WriteRune(char)
			continue
		}
		// we are in an expression
		if char == ')' {
			if nestedBracketsCounter == 0 {
				value, err := evaluateInterpolation(d, context, expSb.String())
				if err != nil {
					return "", err
				}
				sb.WriteString(value)
				expSb.Reset()
				inExpression = false
				continue
			}
			nestedBracketsCounter--
		} else if char == '(' {
			nestedBracketsCounter++
		}
		expSb.WriteRune(char)
	}
	if inExpression {
		logWarn("unclosed interpolation string, skipping interpolation")
		sb.WriteString(`\(`)
		sb.WriteString(expSb.String())
	}
	return sb.String(), nil
}

func chomp(s string) string {
	return strings.TrimSuffix(s, "\n")
}

func quoteIfNeeded(s string) string {
	return strconv.Quote(s)
}
