	matchPrefs := matchPreferences{}
	// we got given parameters e.g. match(exp; params)
	if expressionNode.RHS.Operation.OperationType == blockOpType {
		block := expressionNode.RHS
		regExNodes, err := d.GetMatchingNodes(context.ReadOnlyClone(), block.LHS)
		if err != nil {
			return "", matchPrefs, err
		}
		if regExNodes.MatchingNodes.Front() != nil {
			regEx = regExNodes.MatchingNodes.Front().Value.(*Node).Value
		}
		replacementNodes, err := d.GetMatchingNodes(context, block.RHS)
		if err != nil {
			return "", matchPrefs, err
		}
		if replacementNodes.MatchingNodes.Front() != nil {
			paramText := replacementNodes.MatchingNodes.Front().Value.(*Node).Value
			if strings.Contains(paramText, "g") {
				paramText = strings.ReplaceAll(paramText, "g", "")
				matchPrefs.Global = true
			}
			if strings.Contains(paramText, "i") {
				return "", matchPrefs, fmt.Errorf(`'i' is not a valid option for match. To ignore case, use an expression like match("(?i)cat")`)
			}
			if len(paramText) > 0 {
				return "", matchPrefs, fmt.Errorf(`unrecognised match params '%v', please see docs at https://mikefarah.gitbook.io/yq/operators/string-operators`, paramText)
			}
		}
	} else {
		regExNodes, err := d.GetMatchingNodes(context.ReadOnlyClone(), expressionNode.RHS)
		if err != nil {
			return "", matchPrefs, err
		}
		if regExNodes.MatchingNodes.Front() != nil {
			regEx = regExNodes.MatchingNodes.Front().Value.(*Node).Value
		}
	}
	return regEx, matchPrefs, nil
}

func addMatch(original *Node, match string, offset int, name string) *Node {
	newMatch := original.CreateReplacement(MappingNode, "!!map", "")
	newMatch.Parent = nil
	newMatch.Key = nil
	if offset < 0 {
		// no match
		newMatch.AddKeyValueChild(createStringScalar("string"), createNull())
	} else {
		newMatch.AddKeyValueChild(createStringScalar("string"), createStringScalar(match))
	}
	newMatch.AddKeyValueChild(createStringScalar("offset"), createScalar("!!int", fmt.Sprintf("%v", offset)))
	newMatch.AddKeyValueChild(createStringScalar("length"), createScalar("!!int", fmt.Sprintf("%v", len(match))))
	if name != "" {
		newMatch.AddKeyValueChild(createStringScalar("name"), createStringScalar(name))
	}
	return newMatch
}

func match(matchPrefs matchPreferences, regEx *regexp.Regexp, candidate *Node, value string, results *NodeList) {
	var allMatches [][]int
	if matchPrefs.Global {
		allMatches = regEx.FindAllStringSubmatchIndex(value, -1)
	} else {
		allMatches = [][]int{regEx.FindStringSubmatchIndex(value)}
	}
	subNames := regEx.SubexpNames()
	for _, matches := range allMatches {
		if len(matches) == 0 || matches[0] == -1 {
			continue
		}
		capturesNode := &Node{Kind: SequenceNode}
		match, submatches := matches[0], matches[1:]
		for i := 0; i < len(submatches); i += 2 {
			start, end := submatches[i], submatches[i+1]
			if start == -1 {
				cap := addMatch(candidate, "", -1, subNames[i/2+1])
				capturesNode.AddChild(cap)
			} else {
				cap := addMatch(candidate, value[start:end], start, subNames[i/2+1])
				capturesNode.AddChild(cap)
			}
		}
		node := addMatch(candidate, value[match:matches[1]], match, "")
		node.AddKeyValueChild(createStringScalar("captures"), capturesNode)
		results.PushBack(node)
	}
}

func matchOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	regExStr, matchPrefs, err := getMatchParams(d, context, expressionNode)
	if err != nil {
		return Context{}, err
	}
	regEx, err := regexp.Compile(regExStr)
	if err != nil {
		return Context{}, err
	}
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind != ScalarNode || nodeTag(node) != "!!str" {
			return Context{}, fmt.Errorf("cannot match with %v, can only match strings. Hint: Most often you'll want to use '|=' over '=' for this operation", node.Tag)
		}
		match(matchPrefs, regEx, candidate, node.Value, results)
	}
	return context.ChildContext(results), nil
}

func captureOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	regExStr, matchPrefs, err := getMatchParams(d, context, expressionNode)
	if err != nil {
		return Context{}, err
	}
	regEx, err := regexp.Compile(regExStr)
	if err != nil {
		return Context{}, err
	}
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind != ScalarNode || nodeTag(node) != "!!str" {
			return Context{}, fmt.Errorf("cannot match with %v, can only match strings. Hint: Most often you'll want to use '|=' over '=' for this operation", node.Tag)
		}
		matches := newNodeList()
		match(matchPrefs, regEx, candidate, node.Value, matches)
		for mel := matches.Front(); mel != nil; mel = mel.Next() {
			matchNode := mel.Value.(*Node)
			capturesNode := matchNode.Content[len(matchNode.Content)-1]
			captureMap := candidate.CreateReplacement(MappingNode, "!!map", "")
			captureMap.Parent = nil
			captureMap.Key = nil
			for _, capture := range capturesNode.Content {
				name := ""
				var value *Node
				for i := 0; i+1 < len(capture.Content); i += 2 {
					if capture.Content[i].Value == "name" {
						name = capture.Content[i+1].Value
					}
					if capture.Content[i].Value == "string" {
						value = capture.Content[i+1]
					}
				}
				captureMap.AddKeyValueChild(createStringScalar(name), value)
			}
			results.PushBack(captureMap)
		}
	}
	return context.ChildContext(results), nil
}

func testOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	regExStr, _, err := getMatchParams(d, context, expressionNode)
	if err != nil {
		return Context{}, err
	}
	regEx, err := regexp.Compile(regExStr)
	if err != nil {
		return Context{}, err
	}
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Kind != ScalarNode || nodeTag(node) != "!!str" {
			return Context{}, fmt.Errorf("cannot match with %v, can only match strings. Hint: Most often you'll want to use '|=' over '=' for this operation", node.Tag)
		}
		matches := regEx.MatchString(node.Value)
		results.PushBack(createBooleanCandidate(candidate, matches))
	}
	return context.ChildContext(results), nil
}

// ---- string interpolation

func stringInterpolationOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	if context.MatchingNodes.Len() == 0 {
		value, err := interpolate(d, context, expressionNode.Operation.StringValue)
		if err != nil {
			return Context{}, err
		}
		node := createStringScalar(value)
		results.PushBack(node)
		return context.ChildContext(results), nil
	}
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		value, err := interpolate(d, context.SingleChildContext(candidate), expressionNode.Operation.StringValue)
		if err != nil {
			return Context{}, err
		}
		node := candidate.CreateReplacement(ScalarNode, "!!str", value)
		results.PushBack(node)
	}
	return context.ChildContext(results), nil
}

func evaluateInterpolation(d *evaluator, context Context, expStr string) (string, error) {
	exp, err := parseExpression(expStr)
	if err != nil {
		return "", err
	}
	value, err := d.GetMatchingNodes(context, exp)
	if err != nil {
		return "", err
	}
	if value.MatchingNodes.Len() == 0 {
		return "", nil
	}
	node := value.MatchingNodes.Front().Value.(*Node)
	if node.Kind == ScalarNode {
		return node.Value, nil
	}
	s, err := encodeToString(node, "yaml", 2)
	if err != nil {
		return "", err
	}
	return chomp(s), nil
}

func interpolate(d *evaluator, context Context, str string) (string, error) {
	var sb strings.Builder
	var expSb strings.Builder
	inExpression := false
	nestedBracketsCounter := 0
	runes := []rune(str)
	for i := 0; i < len(runes); i++ {
		char := runes[i]
		if !inExpression {
			if char == '\\' && i+1 < len(runes) && runes[i+1] == '(' {
				inExpression = true
				i++
				continue
			}
			sb.WriteRune(char)
			continue
		}
		// we are in an expression
		if char == ')' {
			if nestedBracketsCounter == 0 {
				value, err := evaluateInterpolation(d, context, expSb.String())
				if err != nil {
					return "", err
				}
				sb.WriteString(value)
				expSb.Reset()
				inExpression = false
				continue
			}
			nestedBracketsCounter--
		} else if char == '(' {
			nestedBracketsCounter++
		}
		expSb.WriteRune(char)
	}
	if inExpression {
		logWarn("unclosed interpolation string, skipping interpolation")
		sb.WriteString(`\(`)
		sb.WriteString(expSb.String())
	}
	return sb.String(), nil
}

func chomp(s string) string {
	return strings.TrimSuffix(s, "\n")
}

func quoteIfNeeded(s string) string {
	return strconv.Quote(s)
}
