package main

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
)

var securityDisableEnvOps = false
var securityDisableFileOps = false
var securityEnableSystemOperator = false

func envOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if securityDisableEnvOps {
		return Context{}, fmt.Errorf("env operations are disabled by security policy")
	}
	envName := expressionNode.Operation.StringValue
	rawValue := os.Getenv(envName)
	preferences := expressionNode.Operation.Preferences.(envOpPreferences)
	var node *Node
	if preferences.StringValue {
		node = &Node{Kind: ScalarNode, Tag: "!!str", Value: rawValue}
	} else if rawValue == "" {
		return Context{}, fmt.Errorf("value for env variable '%v' not provided in env()", envName)
	} else {
		decoded, err := decodeStringValue(rawValue, "yaml")
		if err != nil {
			return Context{}, err
		}
		node = decoded
	}
	return context.SingleChildContext(node), nil
}

func envSubstOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if securityDisableEnvOps {
		return Context{}, fmt.Errorf("env operations are disabled by security policy")
	}
	prefs := expressionNode.Operation.Preferences.(envSubstPreferences)
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		node := unwrapAlias(candidate)
		if node.Tag != "!!str" {
			logWarn(fmt.Sprintf("EnvSubstOperator, env name: %v", node.Tag))
			return Context{}, fmt.Errorf("cannot substitute with %v, can only substitute strings. Hint: Most often you'll want to use '|=' over '=' for this operation", node.Tag)
		}
		value, err := envsubstString(node.Value, prefs)
		if err != nil {
			return Context{}, err
		}
		result := candidate.CreateReplacement(ScalarNode, "!!str", value)
		result.Style = node.Style
		results.PushBack(result)
	}
	return context.ChildContext(results), nil
}

// envsubstString performs shell-like variable substitution.
func envsubstString(s string, prefs envSubstPreferences) (string, error) {
	var sb strings.Builder
	runes := []rune(s)
	for i := 0; i < len(runes); i++ {
		c := runes[i]
		if c != '$' {
			sb.WriteRune(c)
			continue
		}
		if i+1 >= len(runes) {
			sb.WriteRune(c)
			continue
		}
		next := runes[i+1]
		if next == '$' {
			sb.WriteRune('$')
			i++
			continue
		}
		if next == '{' {
			end := -1
			for j := i + 2; j < len(runes); j++ {
				if runes[j] == '}' {
					end = j
					break
				}
			}
			if end < 0 {
				sb.WriteRune(c)
				continue
			}
			inner := string(runes[i+2 : end])
			if inner == "" {
				sb.WriteString("${}")
				i = end
				continue
			}
			value, err := substituteVariable(inner, prefs)
			if err != nil {
				return "", err
			}
			sb.WriteString(value)
			i = end
			continue
		}
		if isVarStart(next) {
			j := i + 1
			for j < len(runes) && isVarChar(runes[j]) {
				j++
			}
			name := string(runes[i+1 : j])
			value, err := substituteVariable(name, prefs)
			if err != nil {
				return "", err
			}
			sb.WriteString(value)
			i = j - 1
			continue
		}
		sb.WriteRune(c)
	}
	return sb.String(), nil
}

func isVarStart(r rune) bool {
	return r == '_' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
}

func isVarChar(r rune) bool {
	return isVarStart(r) || (r >= '0' && r <= '9')
}

func substituteVariable(expr string, prefs envSubstPreferences) (string, error) {
	name := expr
	op := ""
	word := ""
	for _, candidate := range []string{":-", ":+", ":=", ":?", "-", "+", "=", "?"} {
		if idx := strings.Index(expr, candidate); idx > 0 {
			name = expr[:idx]
			op = candidate
			word = expr[idx+len(candidate):]
			break
		}
	}
	value, set := os.LookupEnv(name)
	switch op {
	case ":-":
		if !set || value == "" {
			return word, nil
		}
		return value, nil
	case "-":
		if !set {
			return word, nil
		}
		return value, nil
	case ":+":
		if set && value != "" {
			return word, nil
		}
		return "", nil
	case "+":
		if set {
			return word, nil
		}
		return "", nil
	case ":?":
		if !set || value == "" {
			if word == "" {
				return "", fmt.Errorf("variable ${%s} not set", name)
			}
			return "", fmt.Errorf("%s", word)
		}
		return value, nil
	case "?":
		if !set {
			if word == "" {
				return "", fmt.Errorf("variable ${%s} not set", name)
			}
			return "", fmt.Errorf("%s", word)
		}
		return value, nil
	case ":=", "=":
		if !set || (op == ":=" && value == "") {
			return word, nil
		}
		return value, nil
	}
	if !set {
		if prefs.NoUnset {
			return "", fmt.Errorf("variable ${%s} not set", name)
		}
		return "", nil
	}
	if value == "" && prefs.NoEmpty {
		return "", fmt.Errorf("variable ${%s} set but empty", name)
	}
	return value, nil
}

func loadOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if securityDisableFileOps {
		return Context{}, fmt.Errorf("file operations are disabled by security policy")
	}
	prefs := expressionNode.Operation.Preferences.(loadPrefs)
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		if rhs.MatchingNodes.Front() == nil {
			return Context{}, fmt.Errorf("filename expression returned nil")
		}
		nameCandidateNode := rhs.MatchingNodes.Front().Value.(*Node)
		filename := nameCandidateNode.Value
		var contentsNode *Node
		if prefs.loadAsString {
			contents, err := os.ReadFile(filename)
			if err != nil {
				return Context{}, fmt.Errorf("failed to load %v: %w", filename, err)
			}
			contentsNode = &Node{Kind: ScalarNode, Tag: "!!str", Value: string(contents)}
		} else {
			docs, err := loadFile(filename, prefs.decoder)
			if err != nil {
				return Context{}, fmt.Errorf("failed to load %v: %w", filename, err)
			}
			if len(docs) == 0 {
				contentsNode = createNull()
			} else if len(docs) == 1 {
				contentsNode = docs[0]
				contentsNode.LeadingContent = ""
			} else {
				contentsNode = &Node{Kind: SequenceNode, Tag: "!!seq"}
				for _, doc := range docs {
					doc.LeadingContent = ""
					contentsNode.AddChild(doc)
				}
			}
		}
		results.PushBack(contentsNode)
	}
	return context.ChildContext(results), nil
}

func systemOperator(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if !securityEnableSystemOperator {
		return Context{}, fmt.Errorf("system operations are disabled, use --security-enable-system-operator to enable")
	}
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(candidate), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		if rhs.MatchingNodes.Front() == nil {
			continue
		}
		command := rhs.MatchingNodes.Front().Value.(*Node).Value
		cmd := exec.Command("sh", "-c", command)
		out, err := cmd.Output()
		if err != nil {
			return Context{}, fmt.Errorf("failed to execute command: %w", err)
		}
		results.PushBack(candidate.CreateReplacement(ScalarNode, "!!str", strings.TrimSuffix(string(out), "\n")))
	}
	return context.ChildContext(results), nil
}
