func withDateTimeFormat(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	if expressionNode.RHS.Operation.OperationType == blockOpType {
		layoutExp := expressionNode.RHS.LHS
		layout, err := getStringParameter("layout", d, context, layoutExp)
		if err != nil {
			return Context{}, err
		}
		newContext := context.Clone()
		newContext.datetimeLayout = layout
		return d.GetMatchingNodes(newContext, expressionNode.RHS.RHS)
	}
	return Context{}, fmt.Errorf(`must provide a date time format string and an expression, e.g. with_dtf("Monday, 02-Jan-06 at 3:04PM MST"; <exp>)`)
}

func formatDateTime(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	format, err := getStringParameter("format", d, context, expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	layout := context.GetDateTimeLayout()
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		parsedTime, err := parseDateTime(layout, candidate.Value)
		if err != nil {
			return Context{}, fmt.Errorf("could not parse datetime of [%v]: %w", candidate.GetNicePath(), err)
		}
		formattedTimeStr := parsedTime.Format(format)
		node := candidate.CreateReplacement(ScalarNode, guessTag(formattedTimeStr), formattedTimeStr)
		results.PushBack(node)
	}
	return context.ChildContext(results), nil
}

func tzOp(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	timezoneStr, err := getStringParameter("timezone", d, context, expressionNode.RHS)
	if err != nil {
		return Context{}, err
	}
	layout := context.GetDateTimeLayout()
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		parsedTime, err := parseDateTime(layout, candidate.Value)
		if err != nil {
			return Context{}, fmt.Errorf("could not parse datetime of [%v] using layout [%v]: %w", candidate.GetNicePath(), layout, err)
		}
		timezone, err := time.LoadLocation(timezoneStr)
		if err != nil {
			return Context{}, fmt.Errorf("could not load tz [%v]: %w", timezoneStr, err)
		}
		tzTime := parsedTime.In(timezone)
		node := candidate.CreateReplacement(ScalarNode, candidate.Tag, tzTime.Format(layout))
		node.Style = candidate.Style
		results.PushBack(node)
	}
	return context.ChildContext(results), nil
}

func nowOp(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	node := &Node{Kind: ScalarNode, Tag: "!!timestamp", Value: time.Now().Format(time.RFC3339)}
	return context.SingleChildContext(node), nil
}

func fromUnixOp(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		if nodeTag(candidate) != "!!int" && nodeTag(candidate) != "!!float" {
			return Context{}, fmt.Errorf("from_unix only works on numbers, found %v instead", candidate.Tag)
		}
		var actualNumber int64
		if nodeTag(candidate) == "!!int" {
			_, n, err := parseInt64(candidate.Value)
			if err != nil {
				return Context{}, err
			}
			actualNumber = n
		} else {
			f, err := strconv.ParseFloat(candidate.Value, 64)
			if err != nil {
				return Context{}, err
			}
			actualNumber = int64(f)
		}
		t := time.Unix(actualNumber, 0).UTC()
		node := candidate.CreateReplacement(ScalarNode, "!!timestamp", t.Format(context.GetDateTimeLayout()))
		results.PushBack(node)
	}
	return context.ChildContext(results), nil
}

func toUnixOp(d *evaluator, context Context, expressionNode *ExpressionNode) (Context, error) {
	layout := context.GetDateTimeLayout()
	var results = newNodeList()
	for el := context.MatchingNodes.Front(); el != nil; el = el.Next() {
		candidate := el.Value.(*Node)
		parsedTime, err := parseDateTime(layout, candidate.Value)
		if err != nil {
			return Context{}, fmt.Errorf("could not parse datetime of [%v] using layout [%v]: %w", candidate.GetNicePath(), layout, err)
		}
		node := candidate.CreateReplacement(ScalarNode, "!!int", fmt.Sprintf("%v", parsedTime.Unix()))
		results.PushBack(node)
	}
	return context.ChildContext(results), nil
}
