// ---- decoding

func fromYamlNode(y *yaml.Node, parent *Node) *Node {
	n := &Node{
		Kind:        Kind(y.Kind),
		Style:       Style(y.Style),
		Tag:         y.Tag,
		Value:       y.Value,
		Anchor:      y.Anchor,
		HeadComment: y.HeadComment,
		LineComment: y.LineComment,
		FootComment: y.FootComment,
		Line:        y.Line,
		Column:      y.Column,
		Parent:      parent,
	}
	if y.Kind == yaml.MappingNode {
		for i := 0; i+1 < len(y.Content); i += 2 {
			key := fromYamlNode(y.Content[i], n)
			key.IsMapKey = true
			value := fromYamlNode(y.Content[i+1], n)
			value.Key = key
			n.Content = append(n.Content, key, value)
		}
	} else if y.Kind == yaml.SequenceNode {
		for i, c := range y.Content {
			child := fromYamlNode(c, n)
			child.Key = createScalar("!!int", fmt.Sprintf("%v", i))
			n.Content = append(n.Content, child)
		}
	} else if y.Kind == yaml.DocumentNode {
		if len(y.Content) > 0 {
			root := fromYamlNode(y.Content[0], nil)
			if y.HeadComment != "" {
				if root.HeadComment != "" {
					root.HeadComment = y.HeadComment + "\n" + root.HeadComment
				} else {
					root.HeadComment = y.HeadComment
				}
			}
			if y.FootComment != "" {
				if root.FootComment != "" {
					root.FootComment = root.FootComment + "\n" + y.FootComment
				} else {
					root.FootComment = y.FootComment
				}
			}
			if y.LineComment != "" && root.LineComment == "" {
				root.LineComment = y.LineComment
			}
			return root
		}
		return &Node{Kind: ScalarNode, Tag: "!!null"}
	}
	return n
}

// resolveAliases links alias nodes to their anchor targets.
func resolveAliases(root *Node) {
	anchors := map[string]*Node{}
	var collect func(n *Node)
	collect = func(n *Node) {
		if n.Anchor != "" {
			anchors[n.Anchor] = n
		}
		for _, c := range n.Content {
			collect(c)
		}
	}
	collect(root)
	var link func(n *Node)
	link = func(n *Node) {
		if n.Kind == AliasNode {
			if target, ok := anchors[n.Value]; ok {
				n.Alias = target
			}
		}
		for _, c := range n.Content {
			link(c)
		}
	}
	link(root)
}

func fromYamlNodeWithAliases(y *yaml.Node) *Node {
	// yaml.v3 links alias nodes already; we rebuild via anchor names
	root := fromYamlNode(y, nil)
	resolveAliases(root)
	return root
}

type yamlDecoder struct {
	reader   io.Reader
	decoder  *yaml.Decoder
	prefs    *globalPrefs
	readAnything bool
	firstFile bool
	documentIndex uint
	leadingContent string
	bufferRead bytes.Buffer
}

var commentLineRegEx = regexp.MustCompile(`^\s*#`)
var yamlDirectiveLineRegEx = regexp.MustCompile(`^\s*%YA`)

func processReadStream(reader *bufio.Reader) (io.Reader, string, error) {
	var sb strings.Builder
	for {
		peekBytes, err := reader.Peek(3)
		if errors.Is(err, io.EOF) {
			// EOF are handled else where..
			return reader, sb.String(), nil
		} else if err != nil {
			return reader, sb.String(), err
		} else if string(peekBytes) == "---" {
			_, err := reader.ReadString('\n')
			sb.WriteString("$yqDocSeparator$\n")
			if errors.Is(err, io.EOF) {
				return reader, sb.String(), nil
			} else if err != nil {
				return reader, sb.String(), err
			}
		} else if commentLineRegEx.MatchString(string(peekBytes)) || yamlDirectiveLineRegEx.MatchString(string(peekBytes)) {
			line, err := reader.ReadString('\n')
			sb.WriteString(line)
			if errors.Is(err, io.EOF) {
				return reader, sb.String(), nil
			} else if err != nil {
				return reader, sb.String(), err
			}
		} else {
			return reader, sb.String(), nil
		}
	}
}

func decodeYamlDocuments(reader io.Reader, headerPreprocess bool) ([]*Node, error) {
	var leadingContent string
	var err error
	if headerPreprocess {
		reader, leadingContent, err = processReadStream(bufio.NewReader(reader))
		if err != nil {
			return nil, err
		}
	}
	decoder := yaml.NewDecoder(reader)
	var docs []*Node
	var index uint
	for {
		var yn yaml.Node
		err := decoder.Decode(&yn)
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, err
		}
		node := fromYamlNodeWithAliases(&yn)
		node.Document = index
		if index == 0 {
			node.LeadingContent = leadingContent
		}
		docs = append(docs, node)
		index++
	}
	if len(docs) == 0 && leadingContent != "" {
		// a document with only comments/separators
		n := &Node{Kind: ScalarNode, Tag: "!!null", Value: "", LeadingContent: leadingContent}
		docs = append(docs, n)
	}
	return docs, nil
}

// ---- encoding

func toYamlNode(n *Node, anchorsSeen map[string]*yaml.Node) *yaml.Node {
	y := &yaml.Node{
		Kind:        yaml.Kind(n.Kind),
		Style:       yaml.Style(n.Style),
		Tag:         n.Tag,
		Value:       n.Value,
		Anchor:      n.Anchor,
		HeadComment: n.HeadComment,
		LineComment: n.LineComment,
		FootComment: n.FootComment,
		Line:        n.Line,
		Column:      n.Column,
	}
	if n.Kind == AliasNode {
		if n.Alias != nil {
			if target, ok := anchorsSeen[n.Value]; ok {
				y.Alias = target
			} else {
				y.Alias = toYamlNode(n.Alias, anchorsSeen)
			}
		} else {
			y.Alias = &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}
		}
		return y
	}
	if n.Anchor != "" {
		anchorsSeen[n.Anchor] = y
	}
	for _, c := range n.Content {
		y.Content = append(y.Content, toYamlNode(c, anchorsSeen))
	}
	return y
}

type yamlEncoderPrefs struct {
	indent           int
	colorsEnabled    bool
	unwrapScalar     bool
	printDocSeparators bool
	compactSeqIndent bool
}

func encodeYaml(writer io.Writer, node *Node, prefs yamlEncoderPrefs) error {
	if node.Kind == ScalarNode && prefs.unwrapScalar {
		_, err := writer.Write([]byte(node.Value + "\n"))
		return err
	}
	var destination io.Writer = writer
	tempBuffer := bytes.NewBuffer(nil)
	if prefs.colorsEnabled {
		destination = tempBuffer
	}
	encoder := yaml.NewEncoder(destination)
	encoder.SetIndent(prefs.indent)
	if prefs.compactSeqIndent {
		encoder.CompactSeqIndent()
	}
	target := toYamlNode(node, map[string]*yaml.Node{})
	if err := encoder.Encode(target); err != nil {
		return err
	}
	if err := encoder.Close(); err != nil {
		return err
	}
	if prefs.colorsEnabled {
		return colorizeAndPrint(tempBuffer.Bytes(), writer)
	}
	return nil
}

func encodeYamlToString(node *Node, indent int) (string, error) {
	var buf bytes.Buffer
	err := encodeYaml(&buf, node, yamlEncoderPrefs{indent: indent})
	return buf.String(), err
}
