		dec.UseNumber()
		if err := dec.Decode(&v); err != nil {
			return nil, err
		}
		return v, nil
	}
}

func decodeJSONOrdered(reader io.Reader) ([]*Node, error) {
	dec := json.NewDecoder(reader)
	dec.UseNumber()
	var docs []*Node
