package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"strconv"
	"strings"
)

// ---- JSON encoding

type jsonEncoder struct {
	indentString  string
	colorsEnabled bool
	unwrapScalar  bool
}

func newJSONEncoder(indent int, colorsEnabled bool, unwrapScalar bool) *jsonEncoder {
	var indentString = ""
	for index := 0; index < indent; index++ {
		indentString = indentString + " "
	}
	return &jsonEncoder{indentString: indentString, colorsEnabled: colorsEnabled, unwrapScalar: unwrapScalar}
}

func (je *jsonEncoder) Encode(writer io.Writer, node *Node) error {
	if node.Kind == ScalarNode && je.unwrapScalar {
		_, err := writer.Write([]byte(node.Value + "\n"))
		return err
	}
	var buf bytes.Buffer
	if err := writeJSON(&buf, node, je.indentString, 0); err != nil {
		return fmt.Errorf("json: error calling MarshalJSON for type *yqlib.CandidateNode: %w", err)
	}
	buf.WriteByte('\n')
	if je.colorsEnabled {
		return colorizeJSONAndPrint(buf.Bytes(), writer)
	}
	_, err := writer.Write(buf.Bytes())
	return err
}

func formatJSONFloat(f float64) (string, error) {
	if math.IsInf(f, 0) || math.IsNaN(f) {
		return "", fmt.Errorf("json: unsupported value: %v", strconv.FormatFloat(f, 'g', -1, 64))
	}
	abs := math.Abs(f)
	format := byte('f')
	if abs != 0 {
		if abs < 1e-6 || abs >= 1e21 {
			format = 'e'
		}
	}
	return strconv.FormatFloat(f, format, -1, 64), nil
}

func jsonScalarValue(node *Node) (string, error) {
	tag := node.Tag
	if !strings.HasPrefix(tag, "!!") {
		tag = guessTag(node.Value)
		if node.Value == "" {
			tag = "!!str"
		}
	}
	switch tag {
	case "!!int":
		_, v, err := parseInt64(node.Value)
		if err != nil {
			return "", err
		}
		return strconv.FormatInt(v, 10), nil
	case "!!float":
		f, err := strconv.ParseFloat(strings.ReplaceAll(node.Value, "_", ""), 64)
		if err != nil {
			return "", err
		}
		return formatJSONFloat(f)
	case "!!bool":
		if isTruthyNode(node) {
			return "true", nil
		}
		return "false", nil
	case "!!null":
		return "null", nil
	}
	return jsonString(node.Value), nil
}

func jsonString(s string) string {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	_ = enc.Encode(s)
	return strings.TrimSuffix(buf.String(), "\n")
}

func writeJSON(buf *bytes.Buffer, node *Node, indent string, level int) error {
	node = unwrapAlias(node)
	switch node.Kind {
	case ScalarNode:
		v, err := jsonScalarValue(node)
		if err != nil {
			return err
		}
		buf.WriteString(v)
	case MappingNode:
		if len(node.Content) == 0 {
			buf.WriteString("{}")
			return nil
		}
		buf.WriteByte('{')
		for i := 0; i+1 < len(node.Content); i += 2 {
			if i > 0 {
				buf.WriteByte(',')
			}
			if indent != "" {
				buf.WriteByte('\n')
				buf.WriteString(strings.Repeat(indent, level+1))
			}
			key := unwrapAlias(node.Content[i])
			buf.WriteString(jsonString(key.Value))
			buf.WriteByte(':')
			if indent != "" {
				buf.WriteByte(' ')
			}
			if err := writeJSON(buf, node.Content[i+1], indent, level+1); err != nil {
				return err
			}
		}
		if indent != "" {
			buf.WriteByte('\n')
			buf.WriteString(strings.Repeat(indent, level))
		}
		buf.WriteByte('}')
	case SequenceNode:
		if len(node.Content) == 0 {
			buf.WriteString("[]")
			return nil
		}
		buf.WriteByte('[')
		for i, c := range node.Content {
			if i > 0 {
				buf.WriteByte(',')
			}
			if indent != "" {
				buf.WriteByte('\n')
				buf.WriteString(strings.Repeat(indent, level+1))
			}
			if err := writeJSON(buf, c, indent, level+1); err != nil {
				return err
			}
		}
		if indent != "" {
			buf.WriteByte('\n')
			buf.WriteString(strings.Repeat(indent, level))
		}
		buf.WriteByte(']')
	default:
		buf.WriteString("null")
	}
	return nil
}

// ---- JSON decoding

func decodeJSONDocuments(reader io.Reader) ([]*Node, error) {
	dec := json.NewDecoder(reader)
	dec.UseNumber()
	var docs []*Node
	var index uint
	for {
		var v interface{}
		err := dec.Decode(&v)
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, fmt.Errorf("json: object of object %w", err)
		}
		node := fromInterface(v, nil)
		node.Document = index
		docs = append(docs, node)
		index++
	}
	return docs, nil
}

// fromInterface converts a decoded json value to a Node. Note that json
// objects lose their order when decoded into map[string]interface{}, so we
// use a custom ordered decoding below.
func fromInterface(v interface{}, parent *Node) *Node {
	switch t := v.(type) {
	case nil:
		return &Node{Kind: ScalarNode, Tag: "!!null", Value: "null", Parent: parent}
	case bool:
		return &Node{Kind: ScalarNode, Tag: "!!bool", Value: fmt.Sprintf("%v", t), Parent: parent}
	case string:
		return &Node{Kind: ScalarNode, Tag: "!!str", Value: t, Parent: parent}
	case json.Number:
		return numberNode(t.String(), parent)
	case float64:
		return numberNode(formatFloat(t), parent)
	case []interface{}:
		n := &Node{Kind: SequenceNode, Tag: "!!seq", Parent: parent}
		for i, c := range t {
			child := fromInterface(c, n)
			child.Key = createScalar("!!int", fmt.Sprintf("%v", i))
			n.Content = append(n.Content, child)
		}
		return n
	case *orderedMap:
		n := &Node{Kind: MappingNode, Tag: "!!map", Parent: parent}
		for _, kv := range t.entries {
			key := &Node{Kind: ScalarNode, Tag: "!!str", Value: kv.key, Parent: n, IsMapKey: true}
			value := fromInterface(kv.value, n)
			value.Key = key
			n.Content = append(n.Content, key, value)
		}
		return n
	}
	return &Node{Kind: ScalarNode, Tag: "!!str", Value: fmt.Sprintf("%v", v), Parent: parent}
}

func numberNode(s string, parent *Node) *Node {
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return &Node{Kind: ScalarNode, Tag: "!!str", Value: s, Parent: parent}
	}
	formatted := formatFloat(f)
	tag := "!!float"
	if f == math.Trunc(f) && !strings.ContainsAny(formatted, "e.") {
		tag = "!!int"
	} else if guessTag(formatted) == "!!int" {
		tag = "!!int"
	}
	if tag == "!!float" && guessTag(formatted) == "!!int" {
		tag = "!!int"
	}
	return &Node{Kind: ScalarNode, Tag: tag, Value: formatted, Parent: parent}
}

type orderedMapEntry struct {
	key   string
	value interface{}
}

type orderedMap struct {
	entries []orderedMapEntry
}

func (o *orderedMap) UnmarshalJSON(data []byte) error {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	// read open brace
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	if delim, ok := tok.(json.Delim); !ok || delim != '{' {
		return fmt.Errorf("expected object")
	}
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return err
		}
		key, ok := keyTok.(string)
		if !ok {
			return fmt.Errorf("expected string key")
		}
		var raw json.RawMessage
		if err := dec.Decode(&raw); err != nil {
			return err
		}
		value, err := decodeRawJSON(raw)
		if err != nil {
			return err
		}
		o.entries = append(o.entries, orderedMapEntry{key: key, value: value})
	}
	// closing brace
	if _, err := dec.Token(); err != nil {
		return err
	}
	return nil
}

func decodeRawJSON(raw json.RawMessage) (interface{}, error) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 {
		return nil, fmt.Errorf("unexpected end of JSON input")
	}
	switch trimmed[0] {
	case '{':
		om := &orderedMap{}
		if err := om.UnmarshalJSON(trimmed); err != nil {
			return nil, err
		}
		return om, nil
	case '[':
		dec := json.NewDecoder(bytes.NewReader(trimmed))
		dec.UseNumber()
		if _, err := dec.Token(); err != nil {
			return nil, err
		}
		var arr []interface{}
		for dec.More() {
			var raw json.RawMessage
			if err := dec.Decode(&raw); err != nil {
				return nil, err
			}
			v, err := decodeRawJSON(raw)
			if err != nil {
				return nil, err
			}
			arr = append(arr, v)
		}
		if arr == nil {
			arr = []interface{}{}
		}
		return arr, nil
	default:
		var v interface{}
		dec := json.NewDecoder(bytes.NewReader(trimmed))
		dec.UseNumber()
		if err := dec.Decode(&v); err != nil {
			return nil, err
		}
		return v, nil
	}
}

func decodeJSONOrdered(reader io.Reader) ([]*Node, error) {
	dec := json.NewDecoder(reader)
	dec.UseNumber()
	var docs []*Node
	var index uint
	for {
		var raw json.RawMessage
		err := dec.Decode(&raw)
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, fmt.Errorf("json: object of object %w", err)
		}
		v, err := decodeRawJSON(raw)
		if err != nil {
			return nil, fmt.Errorf("json: object of object %w", err)
		}
		node := fromInterface(v, nil)
		node.Document = index
		docs = append(docs, node)
		index++
	}
	return docs, nil
}
