type charFlag struct {
	target *string
}

func newCharFlag(target *string, def string) *charFlag {
	*target = def
	return &charFlag{target: target}
}

func (c *charFlag) String() string { return *c.target }
func (c *charFlag) Set(v string) error {
	if len(v) != 1 {
		return fmt.Errorf("[%v] is not a valid character. Must be length 1 was %v", v, len(v))
	}
	*c.target = v
	return nil
}
