func main() {
	rootCmd = newRootCommand()
	// cobra's default help command handling
	rootCmd.SetHelpCommand(&cobra.Command{Use: "help [command]", Short: "Help about any command", Hidden: true, RunE: func(cmd *cobra.Command, args []string) error {
		return rootCmd.Help()
	}})
	rootCmd.SetHelpCommand(nil)
	// disable the default help subcommand being picked for `yq help` when stdin piped: handled in arg processing
	rootCmd.InitDefaultHelpCmd()
	if err := rootCmd.Execute(); err != nil {
		fmt.Fprintln(os.Stderr, "Error:", err.Error())
		if isUsageError(err) {
			// cobra already printed usage via our handling
		}
		os.Exit(1)
	}
}

type usageError struct{ err error }

func (u usageError) Error() string { return u.err.Error() }

func isUsageError(err error) bool {
	var ue usageError
	return errors.As(err, &ue)
}

func stdinIsTerminalOrDevice() bool {
	stat, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return (stat.Mode() & os.ModeCharDevice) != 0
}

// ---- expression / argument processing

func initCommandAndProcessArgs(cmd *cobra.Command, args []string) (string, []string, error) {
	// collect expression and files
	expression := ""
	var files []string
	if prefs.forceExpression != "" {
		expression = prefs.forceExpression
		files = args
	} else if prefs.expressionFile != "" {
		data, err := os.ReadFile(prefs.expressionFile)
		if err != nil {
			return "", nil, err
		}
		expression = string(data)
		files = args
	} else if len(args) == 0 {
		expression = "."
	} else {
		// is the first argument a file?
		if maybeFile(args[0]) {
			expression = "."
			files = args
		} else {
			expression = args[0]
			files = args[1:]
		}
	}
	return expression, files, nil
}

func maybeFile(path string) bool {
	stat, err := os.Stat(path)
	return err == nil && !stat.IsDir()
}

func evaluateSequence(cmd *cobra.Command, args []string) error {
	return evaluate(cmd, args, false)
}

func evaluateAll(cmd *cobra.Command, args []string) error {
	return evaluate(cmd, args, true)
}

func evaluate(cmd *cobra.Command, args []string, allAtOnce bool) error {
	if prefs.verbose {
		verboseLogging = true
	}
	stringInterpolationEnabled = prefs.stringInterpolation
	prefs.inputFormatSet = cmd.Flags().Changed("input-format")
	prefs.unwrapScalarSet = cmd.Flags().Changed("unwrapScalar")

	// print usage when there is nothing to process
	if len(args) == 0 && !prefs.nullInput && stdinIsTerminalOrDevice() && prefs.forceExpression == "" && prefs.expressionFile == "" {
		cmd.SilenceUsage = false
		return cmd.Usage()
	}
	if len(args) == 1 && !prefs.nullInput && stdinIsTerminalOrDevice() && prefs.forceExpression == "" && prefs.expressionFile == "" && !maybeFile(args[0]) {
		// expression given but no input
		var evalCmd *cobra.Command
		for _, c := range rootCmd.Commands() {
			if c.Name() == "eval" {
				evalCmd = c
			}
		}
		if evalCmd == nil {
			evalCmd = cmd
		}
		return evalCmd.Usage()
	}

	expression, files, err := initCommandAndProcessArgs(cmd, args)
	if err != nil {
		return err
	}

	if prefs.nullInput && len(files) > 0 {
		return fmt.Errorf("cannot pass files in when using null-input flag")
	}
	if prefs.writeInplace && (len(files) == 0 || prefs.nullInput) {
		if prefs.nullInput {
			return fmt.Errorf("write inplace cannot be used with null-input flag")
		}
		return fmt.Errorf("write in place flag only applicable when giving an expression and at least one file")
	}

	// formats
	inputFormat, err := resolveInputFormat(prefs.inputFormat, files)
	if err != nil {
		return err
	}
	outputFormat, err := resolveOutputFormat(prefs.outputFormat, inputFormat, files)
	if err != nil {
		return err
	}

	if prefs.indent < 0 {
		panic("yaml: cannot indent to a negative number of spaces")
	}

	// colors
	colors := false
	if prefs.forceColor {
		colors = true
	} else if prefs.forceNoColor {
		colors = false
	} else {
		colors = stdoutIsTerminal()
	}

	unwrapScalar := prefs.unwrapScalar
	if !prefs.unwrapScalarSet {
		unwrapScalar = outputFormat == "yaml"
	}

	if prefs.prettyPrint {
		expression = fmt.Sprintf("%v | ... style=\"\"", expression)
	}

	splitExp := prefs.splitFileExp
	if prefs.splitFileExpFile != "" {
		data, err := os.ReadFile(prefs.splitFileExpFile)
		if err != nil {
			return err
		}
		splitExp = string(data)
	}

	runner := &runner{
		expression:    expression,
		files:         files,
		inputFormat:   inputFormat,
		outputFormat:  outputFormat,
		indent:        prefs.indent,
		colors:        colors,
		unwrapScalar:  unwrapScalar,
		allAtOnce:     allAtOnce,
		splitExp:      splitExp,
	}
	return runner.run()
}

func stdoutIsTerminal() bool {
	stat, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (stat.Mode() & os.ModeCharDevice) != 0
}

var formatNames = "[yaml|y|kyaml|ky|json|j|props|p|csv|c|tsv|t|xml|x|base64|uri|toml|hcl|h|shell|s|lua|l|ini|i]"

func normaliseFormat(name string) (string, bool) {
	switch strings.ToLower(name) {
	case "yaml", "y", "yml":
		return "yaml", true
	case "kyaml", "ky":
		return "kyaml", true
	case "json", "j":
		return "json", true
	case "props", "p", "properties":
		return "props", true
	case "csv", "c":
		return "csv", true
	case "tsv", "t":
		return "tsv", true
	case "xml", "x":
		return "xml", true
	case "base64":
		return "base64", true
	case "uri":
		return "uri", true
	case "toml":
		return "toml", true
	case "hcl", "h":
		return "hcl", true
	case "shell", "s", "sh":
		return "shell", true
	case "lua", "l":
		return "lua", true
	case "ini", "i":
		return "ini", true
	case "auto", "a":
		return "auto", true
	}
	return "", false
}

func formatFromExtension(filename string) string {
	idx := strings.LastIndex(filename, ".")
	if idx < 0 {
		return ""
	}
	ext := strings.ToLower(filename[idx+1:])
	switch ext {
	case "yaml", "yml":
		return "yaml"
	case "json":
		return "json"
	case "props", "properties":
		return "props"
	case "csv":
		return "csv"
	case "tsv":
		return "tsv"
	case "xml":
		return "xml"
	case "toml":
		return "toml"
	case "hcl", "tf":
		return "hcl"
	case "lua":
		return "lua"
	case "ini":
		return "ini"
	case "kyaml":
		return "kyaml"
	}
	return ""
}

func resolveInputFormat(flag string, files []string) (string, error) {
	f, ok := normaliseFormat(flag)
	if !ok {
		return "", fmt.Errorf("unknown format '%v' please use %v", flag, "[auto|a|yaml|y|kyaml|ky|json|j|props|p|csv|c|tsv|t|xml|x|base64|uri|toml|hcl|h|lua|l|ini|i]")
	}
	if f != "auto" {
		return f, nil
	}
	if len(files) > 0 {
		if ext := formatFromExtension(files[0]); ext != "" {
			return ext, nil
		}
	}
	return "yaml", nil
}

func resolveOutputFormat(flag string, inputFormat string, files []string) (string, error) {
	f, ok := normaliseFormat(flag)
	if !ok {
		return "", fmt.Errorf("unknown format '%v' please use %v", flag, formatNames)
	}
	if f != "auto" {
		return f, nil
	}
	detected := ""
	if len(files) > 0 {
		detected = formatFromExtension(files[0])
	}
	if prefs.inputFormatSet {
		wouldBe := detected
		if wouldBe == "" {
			wouldBe = inputFormat
		}
		logWarn(fmt.Sprintf("yq default output is now 'auto' (based on the filename extension). Normally yq would output '%v', but for backwards compatibility 'yaml' has been set. Please use -oy to specify yaml, or drop the -p flag.", wouldBe))
		return "yaml", nil
	}
	if detected != "" {
		switch detected {
		case "yaml", "kyaml", "json", "props", "csv", "tsv", "xml", "toml", "hcl", "lua", "ini":
			return detected, nil
		}
	}
	return "yaml", nil
}
EOF
echo ok

