package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

type encoder interface {
	Encode(writer io.Writer, node *Node) error
	PrintDocumentSeparator(writer io.Writer) error
	PrintLeadingContent(writer io.Writer, content string) error
	CanHandleAliases() bool
}

type printer struct {
	writer             io.Writer
	outputFormat       string
	encoder            encoder
	printDocSeparators bool
	previousDocIndex   uint
	previousFileIndex  int
	printedAnything    bool
	printedMatches     bool
	nulSepOutput       bool
	unwrapScalar       bool
	appendix           string
	splitExp           *ExpressionNode
	splitIndex         int
	evaluator          *evaluator
	treeNavigatorFn    func() *evaluator
}

func (p *printer) writeString(writer io.Writer, s string) error {
	_, err := writer.Write([]byte(s))
	return err
}

func (p *printer) processLeadingContent(node *Node, writer io.Writer, firstInCall bool, docSepPrinted bool) error {
	if node.LeadingContent == "" {
		return nil
	}
	if p.outputFormat != "yaml" {
		return p.encoder.PrintLeadingContent(writer, node.LeadingContent)
	}
	reader := bufio.NewReader(strings.NewReader(node.LeadingContent))
	for {
		readline, errReading := reader.ReadString('\n')
		if errReading != nil && !errors.Is(errReading, io.EOF) {
			return errReading
		}
		if strings.Contains(readline, "$yqDocSeparator$") {
			if p.printDocSeparators && (firstInCall || !docSepPrinted) {
				if err := p.writeString(writer, "---\n"); err != nil {
					return err
				}
			}
		} else {
			if err := p.writeString(writer, readline); err != nil {
				return err
			}
		}
		if errors.Is(errReading, io.EOF) {
			if readline != "" && !strings.HasSuffix(readline, "\n") {
				if err := p.writeString(writer, "\n"); err != nil {
					return err
				}
			}
			break
		}
	}
	return nil
}

func (p *printer) PrintResults(matchingNodes *NodeList) error {
	if matchingNodes.Len() == 0 {
		return nil
	}
	firstInCall := true
	index := 0
	for el := matchingNodes.Front(); el != nil; el = el.Next() {
		mappedDoc := el.Value.(*Node)
		writer := p.writer
		var splitFile *os.File
		if p.splitExp != nil {
			f, err := p.openSplitFile(mappedDoc)
			if err != nil {
				return err
			}
			splitFile = f
			writer = f
			defer splitFile.Close()
		}
		docSepPrinted := false
		doc := mappedDoc.GetDocument()
		file := mappedDoc.GetFileIndex()
		if !p.printedAnything {
			p.previousDocIndex = doc
			p.previousFileIndex = file
		} else if p.printDocSeparators && (p.previousDocIndex != doc || p.previousFileIndex != file) && !strings.HasPrefix(mappedDoc.LeadingContent, "$yqDocSeparator$") {
			if err := p.encoder.PrintDocumentSeparator(writer); err != nil {
				return err
			}
			docSepPrinted = true
		}
		if err := p.processLeadingContent(mappedDoc, writer, firstInCall, docSepPrinted); err != nil {
			return err
		}
		if p.nulSepOutput {
			var buf bytes.Buffer
			if err := p.encoder.Encode(&buf, mappedDoc); err != nil {
				return err
			}
			out := buf.Bytes()
			if p.unwrapScalar && mappedDoc.Kind == ScalarNode && bytes.Contains(out, []byte{0}) {
				return fmt.Errorf("can't serialise value because it contains NUL char and you are using NUL separated output")
			}
			out = bytes.TrimSuffix(out, []byte("\n"))
			if _, err := writer.Write(out); err != nil {
				return err
			}
			if _, err := writer.Write([]byte{0}); err != nil {
				return err
			}
		} else {
			if err := p.encoder.Encode(writer, mappedDoc); err != nil {
				return err
			}
		}
		p.previousDocIndex = doc
		p.printedAnything = true
		p.printedMatches = true
		firstInCall = false
		index++
		if splitFile != nil {
			splitFile.Close()
		}
		p.splitIndex++
	}
	return nil
}

func (p *printer) openSplitFile(node *Node) (*os.File, error) {
	ctx := Context{MatchingNodes: nodeListOf(node)}
	ctx.SetVariable("index", nodeListOf(createScalar("!!int", fmt.Sprintf("%v", p.splitIndex))))
	result, err := p.evaluator.GetMatchingNodes(ctx, p.splitExp)
	if err != nil {
		return nil, err
	}
	if result.MatchingNodes.Len() == 0 {
		return nil, fmt.Errorf("unable to determine filename for split")
	}
	name := result.MatchingNodes.Front().Value.(*Node).Value
	if filepath.Ext(name) == "" {
		name = name + "." + splitExtension(p.outputFormat)
	}
	dir := filepath.Dir(name)
	if dir != "." && dir != "" {
		if err := os.MkdirAll(dir, 0750); err != nil {
			return nil, err
		}
	}
	return os.OpenFile(name, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)
}

func splitExtension(format string) string {
	switch format {
	case "yaml", "kyaml":
		return "yml"
	case "json":
		return "json"
	case "props":
		return "properties"
	case "csv":
		return "csv"
	case "tsv":
		return "tsv"
	case "xml":
		return "xml"
	case "toml":
		return "toml"
	case "hcl":
		return "hcl"
	case "lua":
		return "lua"
	case "ini":
		return "ini"
	case "shell":
		return "sh"
	}
	return format
}
