	lhs, err := d.GetMatchingNodes(context, expressionNode.LHS)
	if err != nil {
		return Context{}, err
	}
	prefs := traversePreferences{}
	if p, ok := expressionNode.Operation.Preferences.(traversePreferences); ok {
		prefs = p
	}
	var matches = newNodeList()
	for el := lhs.MatchingNodes.Front(); el != nil; el = el.Next() {
		node := el.Value.(*Node)
		// rhs is a collect expression (an array of indices), evaluated relative to the lhs node
		rhs, err := d.GetMatchingNodes(context.SingleReadonlyChildContext(node), expressionNode.RHS)
		if err != nil {
			return Context{}, err
		}
		var indicesToTraverse []*Node
		if rhs.MatchingNodes.Len() > 0 {
			first := rhs.MatchingNodes.Front().Value.(*Node)
			indicesToTraverse = first.Content
		}
		newNodes, err := traverseArrayWithIndicesCtx(context, node, indicesToTraverse, prefs)
		if err != nil {
			return Context{}, err
		}
		for _, n := range newNodes {
			matches.PushBack(n)
		}
	}
