package main

import (
	"bufio"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// ---- properties encoding

func (e *propertiesEncoder) Encode(writer io.Writer, node *Node) error {
	if node.Kind == ScalarNode && e.unwrapScalar {
		_, err := writer.Write([]byte(node.Value + "\n"))
		return err
	}
	exploded := node.Copy()
	exploded.Parent = nil
	if err := explodeNode(exploded, Context{}); err != nil {
		return err
	}
	var sb strings.Builder
	if err := e.doEncode(&sb, exploded, "", nil); err != nil {
		return err
	}
	_, err := writer.Write([]byte(sb.String()))
	return err
}

func (e *propertiesEncoder) PrintDocumentSeparator(writer io.Writer) error { return nil }

func (e *propertiesEncoder) PrintLeadingContent(writer io.Writer, content string) error {
	reader := bufio.NewReader(strings.NewReader(content))
	for {
		readline, errReading := reader.ReadString('\n')
		if errReading != nil && errReading != io.EOF {
			return errReading
		}
		if !strings.Contains(readline, "$yqDocSeparator$") {
			if _, err := writer.Write([]byte(readline)); err != nil {
				return err
			}
		}
		if errReading == io.EOF {
			if readline != "" && !strings.HasSuffix(readline, "\n") {
				writer.Write([]byte("\n"))
			}
			break
		}
	}
	return nil
}

func (e *propertiesEncoder) CanHandleAliases() bool { return false }

func propsComment(sb *strings.Builder, comment string) {
	comment = strings.TrimSpace(comment)
	if comment == "" {
		return
	}
	for _, line := range strings.Split(comment, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if !strings.HasPrefix(line, "#") && !strings.HasPrefix(line, "!") {
			line = "# " + line
		}
		sb.WriteString(line)
		sb.WriteString("\n")
	}
}

func (e *propertiesEncoder) doEncode(sb *strings.Builder, node *Node, path string, keyNode *Node) error {
	comments := ""
	if keyNode != nil {
		comments = keyNode.HeadComment
	}
	if node.HeadComment != "" {
		if comments != "" {
			comments += "\n"
		}
		comments += node.HeadComment
	}
	if node.LineComment != "" {
		if comments != "" {
