package main

import (
	"fmt"
	"io"
	"regexp"
	"strings"
)

type shellEncoder struct {
	unwrapScalar bool
}

func (e *shellEncoder) PrintDocumentSeparator(writer io.Writer) error               { return nil }
func (e *shellEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }
func (e *shellEncoder) CanHandleAliases() bool                                    { return false }

var shellSafeRegex = regexp.MustCompile(`^[a-zA-Z0-9,._+:@%/-]*$`)
var shellKeyUnsafe = regexp.MustCompile(`[^a-zA-Z0-9_]`)

func shellQuoteValue(s string) string {
	if shellSafeRegex.MatchString(s) && s != "" {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

func (e *shellEncoder) Encode(writer io.Writer, node *Node) error {
	exploded := node.Copy()
	exploded.Parent = nil
	if err := explodeNode(exploded, Context{}); err != nil {
		return err
	}
	var sb strings.Builder
	if exploded.Kind == ScalarNode {
		sb.WriteString("value=")
		sb.WriteString(e.encodeScalar(exploded))
		sb.WriteString("\n")
	} else {
		e.doEncode(&sb, exploded, "")
	}
	_, err := writer.Write([]byte(sb.String()))
	return err
}

func (e *shellEncoder) encodeScalar(node *Node) string {
	if node.Tag == "!!str" {
		return shellQuoteValue(node.Value)
	}
	return node.Value
}

func (e *shellEncoder) doEncode(sb *strings.Builder, node *Node, path string) {
	switch node.Kind {
	case ScalarNode:
		sb.WriteString(path)
		sb.WriteString("=")
		sb.WriteString(e.encodeScalar(node))
		sb.WriteString("\n")
	case SequenceNode:
		for i, child := range node.Content {
			childPath := fmt.Sprintf("%v%v%v", path, prefs.shellKeySeparator, i)
			if path == "" {
				childPath = fmt.Sprintf("%v", i)
			}
			e.doEncode(sb, child, childPath)
		}
	case MappingNode:
		for i := 0; i+1 < len(node.Content); i += 2 {
			key := shellKeyUnsafe.ReplaceAllString(node.Content[i].Value, "_")
			childPath := key
			if path != "" {
				childPath = path + prefs.shellKeySeparator + key
			}
			e.doEncode(sb, node.Content[i+1], childPath)
		}
	}
}

// ---- lua

type luaEncoder struct {
	indent       int
	unwrapScalar bool
}

func (e *luaEncoder) PrintDocumentSeparator(writer io.Writer) error               { return nil }
func (e *luaEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }
func (e *luaEncoder) CanHandleAliases() bool                                    { return false }

func luaEscapeString(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString(`\"`)
		case '\\':
			sb.WriteString(`\\`)
		case '\n':
			sb.WriteString(`\n`)
		case '\r':
			sb.WriteString(`\r`)
		case '\t':
			sb.WriteString(`\t`)
		case 0:
			sb.WriteString(`\0`)
		default:
			if r < 0x20 {
				sb.WriteString(fmt.Sprintf("\\%d", r))
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

var luaIdentifier = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)
var luaKeywords = map[string]bool{"and": true, "break": true, "do": true, "else": true, "elseif": true, "end": true, "false": true, "for": true, "function": true, "goto": true, "if": true, "in": true, "local": true, "nil": true, "not": true, "or": true, "repeat": true, "return": true, "then": true, "true": true, "until": true, "while": true}

func (e *luaEncoder) encodeKey(key *Node) string {
	if prefs.luaUnquoted && key.Tag == "!!str" && luaIdentifier.MatchString(key.Value) && !luaKeywords[key.Value] {
		return key.Value
	}
	return "[" + e.encodeScalar(key) + "]"
}

func (e *luaEncoder) encodeScalar(node *Node) string {
	tag := nodeTag(node)
	switch tag {
	case "!!null":
		return "nil"
	case "!!bool":
		if isTruthyNode(node) {
			return "true"
		}
		return "false"
	case "!!int":
		_, v, err := parseInt64(node.Value)
		if err == nil {
			return fmt.Sprintf("%d", v)
		}
		return node.Value
	case "!!float":
		return node.Value
	}
	return luaEscapeString(node.Value)
}

func (e *luaEncoder) doEncode(sb *strings.Builder, node *Node, level int) {
	indent := strings.Repeat("\t", level)
	switch node.Kind {
	case ScalarNode:
		sb.WriteString(e.encodeScalar(node))
	case SequenceNode:
		if len(node.Content) == 0 {
			sb.WriteString("{}")
			return
		}
		sb.WriteString("{\n")
		for _, child := range node.Content {
			sb.WriteString(indent + "\t")
			e.doEncode(sb, child, level+1)
			sb.WriteString(",\n")
		}
		sb.WriteString(indent + "}")
	case MappingNode:
		if len(node.Content) == 0 {
			sb.WriteString("{}")
			return
		}
		sb.WriteString("{\n")
		for i := 0; i+1 < len(node.Content); i += 2 {
			sb.WriteString(indent + "\t")
			sb.WriteString(e.encodeKey(node.Content[i]))
			sb.WriteString(" = ")
			e.doEncode(sb, node.Content[i+1], level+1)
			sb.WriteString(";\n")
		}
		sb.WriteString(indent + "}")
	}
}

func (e *luaEncoder) Encode(writer io.Writer, node *Node) error {
	exploded := node.Copy()
	exploded.Parent = nil
	if err := explodeNode(exploded, Context{}); err != nil {
		return err
	}
	var sb strings.Builder
	if prefs.luaGlobals && exploded.Kind == MappingNode {
		for i := 0; i+1 < len(exploded.Content); i += 2 {
			key := exploded.Content[i]
			if luaIdentifier.MatchString(key.Value) {
				sb.WriteString(key.Value)
			} else {
				sb.WriteString("_ENV[" + e.encodeScalar(key) + "]")
			}
			sb.WriteString(" = ")
			e.doEncode(&sb, exploded.Content[i+1], 0)
			sb.WriteString(";\n")
		}
	} else {
		sb.WriteString(prefs.luaPrefix)
		e.doEncode(&sb, exploded, 0)
		sb.WriteString(prefs.luaSuffix)
	}
	_, err := writer.Write([]byte(sb.String()))
	return err
}
