	case SequenceNode:
		if len(node.Content) == 0 {
			sb.WriteString("{}")
			return
		}
		sb.WriteString("{\n")
		for _, child := range node.Content {
			sb.WriteString(indent + "\t")
			e.doEncode(sb, child, level+1)
