func (e *luaEncoder) Encode(writer io.Writer, node *Node) error {
	exploded := node.Copy()
	exploded.Parent = nil
	if err := explodeNode(exploded, Context{}); err != nil {
		return err
	}
	var sb strings.Builder
	if prefs.luaGlobals && exploded.Kind == MappingNode {
		for i := 0; i+1 < len(exploded.Content); i += 2 {
			key := exploded.Content[i]
			if luaIdentifier.MatchString(key.Value) {
				sb.WriteString(key.Value)
			} else {
				sb.WriteString("_ENV[" + e.encodeScalar(key) + "]")
			}
			sb.WriteString(" = ")
			e.doEncode(&sb, exploded.Content[i+1], 0)
			sb.WriteString(";\n")
		}
	} else {
		sb.WriteString(prefs.luaPrefix)
		e.doEncode(&sb, exploded, 0)
		sb.WriteString(prefs.luaSuffix)
	}
	_, err := writer.Write([]byte(sb.String()))
	return err
}
