func (e *xmlEncoder) encodeTopLevelMap(enc *xml.Encoder, node *Node) error {
	if err := e.encodeComment(enc, node.HeadComment); err != nil {
		return err
	}
	for i := 0; i+1 < len(node.Content); i += 2 {
		key := node.Content[i]
		value := node.Content[i+1]
		if err := e.encodeComment(enc, key.HeadComment); err != nil {
			return err
		}
		if strings.HasPrefix(key.Value, prefs.xmlProcInstPrefix) {
			name := strings.TrimPrefix(key.Value, prefs.xmlProcInstPrefix)
