				return err
			}
		} else if key.Value == prefs.xmlDirectiveName {
			if err := enc.EncodeToken(xml.Directive([]byte(value.Value))); err != nil {
				return err
			}
		} else {
			if err := e.doEncode(enc, value, key.Value); err != nil {
				return err
			}
		}
		if err := e.encodeComment(enc, key.FootComment); err != nil {
			return err
		}
