type xmlNode struct {
	name       string
	attrs      [][2]string
	children   []*xmlChild
	data       string
	headComment string
	footComment string
}

type xmlChild struct {
	name string
	node *xmlNode
	// for proc inst / directive / comments
	kind string
	text string
}

func decodeXMLDocuments(reader io.Reader) ([]*Node, error) {
	data, err := io.ReadAll(reader)
	if err != nil {
		return nil, err
	}
	if strings.TrimSpace(string(data)) == "" {
		return nil, io.EOF
	}
	dec := xml.NewDecoder(bytes.NewReader(data))
	dec.Strict = prefs.xmlStrictMode
	root := &xmlNode{}
	stack := []*xmlNode{root}
	var pendingComment []string
	for {
		var tok xml.Token
		if prefs.xmlRawToken {
			tok, err = dec.RawToken()
		} else {
			tok, err = dec.Token()
		}
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, err
		}
		cur := stack[len(stack)-1]
		switch t := tok.(type) {
		case xml.StartElement:
			name := t.Name.Local
			if t.Name.Space != "" && prefs.xmlKeepNamespace {
				name = t.Name.Space + ":" + name
			}
			n := &xmlNode{name: name}
			for _, a := range t.Attr {
				aname := a.Name.Local
				if a.Name.Space != "" {
					aname = a.Name.Space + ":" + aname
				}
				n.attrs = append(n.attrs, [2]string{aname, a.Value})
			}
			if len(pendingComment) > 0 {
				n.headComment = strings.Join(pendingComment, "\n")
				pendingComment = nil
			}
			cur.children = append(cur.children, &xmlChild{name: name, node: n, kind: "element"})
			stack = append(stack, n)
		case xml.EndElement:
			if len(pendingComment) > 0 {
				cur.footComment = strings.Join(pendingComment, "\n")
				pendingComment = nil
			}
			if len(stack) > 1 {
				stack = stack[:len(stack)-1]
			}
		case xml.CharData:
			text := string(t)
			if strings.TrimSpace(text) == "" {
				continue
			}
			cur.data += strings.TrimSpace(text)
		case xml.Comment:
			pendingComment = append(pendingComment, strings.TrimSpace(string(t)))
		case xml.ProcInst:
			if prefs.xmlSkipProcInst {
				continue
			}
			cur.children = append(cur.children, &xmlChild{name: prefs.xmlProcInstPrefix + t.Target, kind: "procinst", text: string(t.Inst)})
		case xml.Directive:
			if prefs.xmlSkipDirectives {
				continue
			}
			cur.children = append(cur.children, &xmlChild{name: prefs.xmlDirectiveName, kind: "directive", text: string(t)})
		}
	}
	if len(root.children) == 0 && root.data == "" {
		return nil, fmt.Errorf("invalid XML: Encountered chardata [%v] outside of XML node", string(data))
	}
	node := xmlToNode(root, true)
	if len(pendingComment) > 0 {
		node.FootComment = strings.Join(pendingComment, "\n")
	}
	return []*Node{node}, nil
}

func xmlToNode(x *xmlNode, isRoot bool) *Node {
	if !isRoot && len(x.attrs) == 0 && len(x.children) == 0 {
		return &Node{Kind: ScalarNode, Tag: "!!str", Value: x.data}
	}
	m := &Node{Kind: MappingNode, Tag: "!!map"}
	for _, a := range x.attrs {
		m.AddKeyValueChild(createStringScalar(prefs.xmlAttributePrefix+a[0]), createStringScalar(a[1]))
	}
	for _, c := range x.children {
		var value *Node
		switch c.kind {
		case "element":
			value = xmlToNode(c.node, false)
			if c.node.headComment != "" {
				value.HeadComment = c.node.headComment
			}
			if c.node.footComment != "" {
				value.FootComment = c.node.footComment
			}
		default:
			value = createStringScalar(c.text)
		}
		idx := m.findKeyIndex(c.name)
		if idx >= 0 {
			existing := m.Content[idx+1]
			if existing.Kind != SequenceNode || existing.Tag != "!!seq" || existing.Value != "xmlseq" {
				seq := &Node{Kind: SequenceNode, Tag: "!!seq", Value: "xmlseq", Parent: m, Key: m.Content[idx]}
				seq.AddChild(existing)
				m.Content[idx+1] = seq
				existing = seq
			}
			existing.AddChild(value)
		} else {
			m.AddKeyValueChild(createStringScalar(c.name), value)
		}
	}
	if x.data != "" {
		m.AddKeyValueChild(createStringScalar(prefs.xmlContentName), createStringScalar(x.data))
	}
	// clear marker values
	clearXMLMarkers(m)
	return m
}

func clearXMLMarkers(n *Node) {
	if n.Kind == SequenceNode && n.Value == "xmlseq" {
		n.Value = ""
	}
	for _, c := range n.Content {
		clearXMLMarkers(c)
	}
}
