{"command":"cd /workspace && cat > format_toml.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/BurntSushi/toml"
)

// ---- TOML decoding (via BurntSushi/toml, preserving key order using metadata)

func decodeTomlDocuments(reader io.Reader) ([]*Node, error) {
	data, err := io.ReadAll(reader)
	if err != nil {
		return nil, err
	}
	if strings.TrimSpace(string(data)) == "" {
		return nil, io.EOF
	}
	var raw map[string]interface{}
	meta, err := toml.Decode(string(data), &raw)
	if err != nil {
		return nil, err
	}
	// build key order from metadata
	order := map[string]int{}
	for i, k := range meta.Keys() {
		key := strings.Join(k, "\x00")
		if _, ok := order[key]; !ok {
			order[key] = i
		}
	}
	node := tomlToNode(raw, nil, order)
	return []*Node{node}, nil
}

func tomlToNode(v interface{}, path []string, order map[string]int) *Node {
	switch t := v.(type) {
	case map[string]interface{}:
		n := &Node{Kind: MappingNode, Tag: "!!map"}
		keys := make([]string, 0, len(t))
		for k := range t {
			keys = append(keys, k)
		}
		sort.SliceStable(keys, func(i, j int) bool {
			pi := strings.Join(append(append([]string{}, path...), keys[i]), "\x00")
			pj := strings.Join(append(append([]string{}, path...), keys[j]), "\x00")
			oi, oki := order[pi]
			oj, okj := order[pj]
			if oki && okj {
				return oi < oj
			}
			if oki {
				return true
			}
			if okj {
				return false
			}
			return keys[i] < keys[j]
		})
		for _, k := range keys {
			child := tomlToNode(t[k], append(append([]string{}, path...), k), order)
			n.AddKeyValueChild(createStringScalar(k), child)
		}
		return n
	case []map[string]interface{}:
		n := &Node{Kind: SequenceNode, Tag: "!!seq"}
		for _, item := range t {
			n.AddChild(tomlToNode(item, path, order))
		}
		return n
	case []interface{}:
		n := &Node{Kind: SequenceNode, Tag: "!!seq"}
		for _, item := range t {
			n.AddChild(tomlToNode(item, path, order))
		}
		return n
	case string:
		return &Node{Kind: ScalarNode, Tag: "!!str", Value: t}
	case int64:
		return &Node{Kind: ScalarNode, Tag: "!!int", Value: strconv.FormatInt(t, 10)}
	case float64:
		return &Node{Kind: ScalarNode, Tag: "!!float", Value: formatFloat(t)}
	case bool:
		return &Node{Kind: ScalarNode, Tag: "!!bool", Value: fmt.Sprintf("%v", t)}
	case time.Time:
		return &Node{Kind: ScalarNode, Tag: "!!timestamp", Value: t.Format(time.RFC3339)}
	case toml.LocalDate:
		return &Node{Kind: ScalarNode, Tag: "!!timestamp", Value: t.String()}
	case toml.LocalDateTime:
		return &Node{Kind: ScalarNode, Tag: "!!timestamp", Value: t.String()}
	case toml.LocalTime:
		return &Node{Kind: ScalarNode, Tag: "!!str", Value: t.String()}
	case nil:
		return createNull()
	}
	return &Node{Kind: ScalarNode, Tag: "!!str", Value: fmt.Sprintf("%v", v)}
}

// ---- TOML encoding

type tomlEncoder struct {
	indent       int
	unwrapScalar bool
}

func (e *tomlEncoder) PrintDocumentSeparator(writer io.Writer) error               { return nil }
func (e *tomlEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }
func (e *tomlEncoder) CanHandleAliases() bool                                    { return false }

func tomlQuote(s string) string {
	return strconv.Quote(s)
}

func tomlKey(k string) string {
	for _, r := range k {
		if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_' || r == '-') {
			return tomlQuote(k)
		}
	}
	if k == "" {
		return `""`
	}
	return k
}

func (e *tomlEncoder) scalar(node *Node) (string, error) {
	switch nodeTag(node) {
	case "!!null":
		return "", fmt.Errorf("toml does not support null values")
	case "!!bool":
		if isTruthyNode(node) {
			return "true", nil
		}
		return "false", nil
	case "!!int":
		_, v, err := parseInt64(node.Value)
		if err != nil {
			return "", err
		}
		return strconv.FormatInt(v, 10), nil
	case "!!float":
		f, err := strconv.ParseFloat(strings.ReplaceAll(node.Value, "_", ""), 64)
		if err != nil {
			return "", err
		}
		return formatFloat(f), nil
	case "!!timestamp":
		return node.Value, nil
	}
	return tomlQuote(node.Value), nil
}

func (e *tomlEncoder) inline(node *Node) (string, error) {
	node = unwrapAlias(node)
	switch node.Kind {
	case ScalarNode:
		return e.scalar(node)
	case SequenceNode:
		parts := make([]string, 0, len(node.Content))
		for _, c := range node.Content {
			s, err := e.inline(c)
			if err != nil {
				return "", err
			}
			parts = append(parts, s)
		}
		return "[" + strings.Join(parts, ", ") + "]", nil
	case MappingNode:
		parts := make([]string, 0, len(node.Content)/2)
		for i := 0; i+1 < len(node.Content); i += 2 {
			s, err := e.inline(node.Content[i+1])
			if err != nil {
				return "", err
			}
			parts = append(parts, tomlKey(node.Content[i].Value)+" = "+s)
		}
		return "{" + strings.Join(parts, ", ") + "}", nil
	}
	return "", fmt.Errorf("unsupported node")
}

func isArrayOfTables(node *Node) bool {
	if node.Kind != SequenceNode || len(node.Content) == 0 {
		return false
	}
	for _, c := range node.Content {
		if unwrapAlias(c).Kind != MappingNode {
			return false
		}
	}
	return true
}

func (e *tomlEncoder) encodeTable(sb *strings.Builder, node *Node, path []string) error {
	// simple key/values first
	for i := 0; i+1 < len(node.Content); i += 2 {
		key := node.Content[i]
		value := unwrapAlias(node.Content[i+1])
		if value.Kind == MappingNode || isArrayOfTables(value) {
			continue
		}
		if key.HeadComment != "" {
			sb.WriteString(tomlComment(key.HeadComment))
		}
		s, err := e.inline(value)
		if err != nil {
			return err
		}
		sb.WriteString(tomlKey(key.Value) + " = " + s)
		if value.LineComment != "" {
			sb.WriteString(" " + strings.TrimSpace(value.LineComment))
		}
		sb.WriteString("\n")
	}
	// then tables
	for i := 0; i+1 < len(node.Content); i += 2 {
		key := node.Content[i]
		value := unwrapAlias(node.Content[i+1])
		childPath := append(append([]string{}, path...), key.Value)
		if value.Kind == MappingNode {
			sb.WriteString("\n")
			if key.HeadComment != "" {
				sb.WriteString(tomlComment(key.HeadComment))
			}
			sb.WriteString("[" + joinTomlPath(childPath) + "]\n")
			if err := e.encodeTable(sb, value, childPath); err != nil {
				return err
			}
		} else if isArrayOfTables(value) {
			for _, item := range value.Content {
				sb.WriteString("\n[[" + joinTomlPath(childPath) + "]]\n")
				if err := e.encodeTable(sb, unwrapAlias(item), childPath); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

func joinTomlPath(path []string) string {
	parts := make([]string, len(path))
	for i, p := range path {
		parts[i] = tomlKey(p)
	}
	return strings.Join(parts, ".")
}

func tomlComment(comment string) string {
	var sb strings.Builder
	for _, line := range strings.Split(comment, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		if !strings.HasPrefix(line, "#") {
			line = "# " + line
		}
		sb.WriteString(line + "\n")
	}
	return sb.String()
}

func (e *tomlEncoder) Encode(writer io.Writer, node *Node) error {
	if node.Kind == ScalarNode {
		if e.unwrapScalar {
			_, err := writer.Write([]byte(node.Value + "\n"))
			return err
		}
		s, err := e.scalar(node)
		if err != nil {
			return err
		}
		_, err = writer.Write([]byte(s + "\n"))
		return err
	}
	exploded := node.Copy()
	exploded.Parent = nil
	if err := explodeNode(exploded, Context{}); err != nil {
		return err
	}
	if exploded.Kind != MappingNode {
		return fmt.Errorf("toml encoding only supports maps at the top level, got %v", exploded.Tag)
	}
	var sb strings.Builder
	if err := e.encodeTable(&sb, exploded, nil); err != nil {
		return err
	}
	out := strings.TrimPrefix(sb.String(), "\n")
	_, err := writer.Write([]byte(out))
	return err
}

// ---- INI

type iniEncoder struct{ unwrapScalar bool }

func (e *iniEncoder) PrintDocumentSeparator(writer io.Writer) error               { return nil }
func (e *iniEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }
func (e *iniEncoder) CanHandleAliases() bool                                    { return false }

func iniValue(node *Node) string {
	node = unwrapAlias(node)
	switch node.Kind {
	case ScalarNode:
		if node.Tag == "!!str" && guessTag(node.Value) != "!!str" {
			return strconv.Quote(node.Value)
		}
		if node.Tag == "!!str" && (strings.ContainsAny(node.Value, "\n\"") || strings.TrimSpace(node.Value) != node.Value || node.Value == "") {
			return strconv.Quote(node.Value)
		}
		return node.Value
	case SequenceNode:
		parts := []string{}
		for _, c := range node.Content {
			parts = append(parts, iniValue(c))
		}
		return "[" + strings.Join(parts, ", ") + "]"
	case MappingNode:
		parts := []string{}
		for i := 0; i+1 < len(node.Content); i += 2 {
			parts = append(parts, node.Content[i].Value+" = "+iniValue(node.Content[i+1]))
		}
		return "{" + strings.Join(parts, ", ") + "}"
	}
	return ""
}

func (e *iniEncoder) Encode(writer io.Writer, node *Node) error {
	if node.Kind == ScalarNode {
		_, err := writer.Write([]byte(node.Value + "\n"))
		return err
	}
	exploded := node.Copy()
	exploded.Parent = nil
	if err := explodeNode(exploded, Context{}); err != nil {
		return err
	}
	if exploded.Kind != MappingNode {
		return fmt.Errorf("ini encoding only supports maps at the top level, got %v", exploded.Tag)
	}
	var sb strings.Builder
	// top level simple values
	for i := 0; i+1 < len(exploded.Content); i += 2 {
		value := unwrapAlias(exploded.Content[i+1])
		if value.Kind == MappingNode {
			continue
		}
		sb.WriteString(exploded.Content[i].Value + " = " + iniValue(value) + "\n")
	}
	first := sb.Len() == 0
	for i := 0; i+1 < len(exploded.Content); i += 2 {
		value := unwrapAlias(exploded.Content[i+1])
		if value.Kind != MappingNode {
			continue
		}
		if !first {
			sb.WriteString("\n")
		}
		first = false
		sb.WriteString("[" + exploded.Content[i].Value + "]\n")
		for j := 0; j+1 < len(value.Content); j += 2 {
			sb.WriteString(value.Content[j].Value + " = " + iniValue(value.Content[j+1]) + "\n")
		}
	}
	_, err := writer.Write([]byte(sb.String()))
	return err
}

func decodeINIDocuments(reader io.Reader) ([]*Node, error) {
	data, err := io.ReadAll(reader)
	if err != nil {
		return nil, err
	}
	if strings.TrimSpace(string(data)) == "" {
		return nil, io.EOF
	}
	root := &Node{Kind: MappingNode, Tag: "!!map"}
	current := root
	for _, rawLine := range strings.Split(string(data), "\n") {
		line := strings.TrimSpace(rawLine)
		if line == "" || strings.HasPrefix(line, ";") || strings.HasPrefix(line, "#") {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			section := strings.TrimSpace(line[1 : len(line)-1])
			idx := root.findKeyIndex(section)
			if idx >= 0 {
				current = root.Content[idx+1]
			} else {
				_, current = root.AddKeyValueChild(createStringScalar(section), &Node{Kind: MappingNode, Tag: "!!map"})
			}
			continue
		}
		eq := strings.IndexAny(line, "=:")
		if eq < 0 {
			current.AddKeyValueChild(createStringScalar(line), createStringScalar(""))
			continue
		}
		key := strings.TrimSpace(line[:eq])
		value := strings.TrimSpace(line[eq+1:])
		var valueNode *Node
		if len(value) >= 2 && value[0] == '"' && value[len(value)-1] == '"' {
			unq, err := strconv.Unquote(value)
			if err != nil {
				unq = value[1 : len(value)-1]
			}
			valueNode = createStringScalar(unq)
		} else {
			tag := guessTag(value)
			if tag == "!!str" || value == "" {
				valueNode = createStringScalar(value)
			} else {
				valueNode = createScalar(tag, value)
			}
		}
		current.AddKeyValueChild(createStringScalar(key), valueNode)
	}
	return []*Node{root}, nil
}

// ---- HCL (basic)

type hclEncoder struct {
	indent       int
	unwrapScalar bool
}

func (e *hclEncoder) PrintDocumentSeparator(writer io.Writer) error               { return nil }
func (e *hclEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }
func (e *hclEncoder) CanHandleAliases() bool                                    { return false }

func hclValue(node *Node, level int) string {
	node = unwrapAlias(node)
	indent := strings.Repeat("  ", level)
	switch node.Kind {
	case ScalarNode:
		if node.Tag == "!!str" {
			if strings.Contains(node.Value, "\n") {
				return `"""` + node.Value + `"""`
			}
			if guessTag(node.Value) != "!!str" {
				return strconv.Quote(node.Value)
			}
			return node.Value
		}
		return node.Value
	case SequenceNode:
		parts := []string{}
		for _, c := range node.Content {
			parts = append(parts, hclValue(c, level+1))
		}
		return "[" + strings.Join(parts, ", ") + "]"
	case MappingNode:
		var sb strings.Builder
		sb.WriteString("{\n")
		for i := 0; i+1 < len(node.Content); i += 2 {
			sb.WriteString(indent + "  " + node.Content[i].Value + " = " + hclValue(node.Content[i+1], level+1) + "\n")
		}
		sb.WriteString(indent + "}")
		return sb.String()
	}
	return ""
}

func (e *hclEncoder) Encode(writer io.Writer, node *Node) error {
	if node.Kind == ScalarNode {
		_, err := writer.Write([]byte(node.Value + "\n"))
		return err
	}
	exploded := node.Copy()
	exploded.Parent = nil
	if err := explodeNode(exploded, Context{}); err != nil {
		return err
	}
	if exploded.Kind != MappingNode {
		return fmt.Errorf("hcl encoding only supports maps at the top level, got %v", exploded.Tag)
	}
	var sb strings.Builder
	for i := 0; i+1 < len(exploded.Content); i += 2 {
		value := unwrapAlias(exploded.Content[i+1])
		if value.Kind == SequenceNode && !isArrayOfTables(value) {
			continue
		}
		sb.WriteString(exploded.Content[i].Value + " = " + hclValue(value, 0) + "\n")
	}
	_, err := writer.Write([]byte(sb.String()))
	return err
}

func decodeHCLDocuments(reader io.Reader) ([]*Node, error) {
	return nil, fmt.Errorf("hcl input is not supported")
}

func decodeLuaDocuments(reader io.Reader) ([]*Node, error) {
	return nil, fmt.Errorf("lua input is not supported")
}

// ---- KYAML

type kyamlEncoder struct {
	indent       int
	unwrapScalar bool
}

func (e *kyamlEncoder) PrintDocumentSeparator(writer io.Writer) error {
	_, err := writer.Write([]byte("---\n"))
	return err
}
func (e *kyamlEncoder) PrintLeadingContent(writer io.Writer, content string) error { return nil }
func (e *kyamlEncoder) CanHandleAliases() bool                                    { return false }

func kyamlKey(k string) string {
	if k != "" && luaIdentifier.MatchString(k) {
		return k
	}
	return strconv.Quote(k)
}

func (e *kyamlEncoder) doEncode(sb *strings.Builder, node *Node, level int) {
	indent := strings.Repeat(strings.Repeat(" ", e.indent), level)
	node = unwrapAlias(node)
	switch node.Kind {
	case ScalarNode:
		if node.Tag == "!!str" {
			sb.WriteString(strconv.Quote(node.Value))
		} else {
			sb.WriteString(node.Value)
		}
	case SequenceNode:
		if len(node.Content) == 0 {
			sb.WriteString("[]")
			return
		}
		sb.WriteString("[\n")
		for _, c := range node.Content {
			sb.WriteString(indent + strings.Repeat(" ", e.indent))
			e.doEncode(sb, c, level+1)
			sb.WriteString(",\n")
		}
		sb.WriteString(indent + "]")
	case MappingNode:
		if len(node.Content) == 0 {
			sb.WriteString("{}")
			return
		}
		sb.WriteString("{\n")
		for i := 0; i+1 < len(node.Content); i += 2 {
			sb.WriteString(indent + strings.Repeat(" ", e.indent))
			sb.WriteString(kyamlKey(node.Content[i].Value) + ": ")
			e.doEncode(sb, node.Content[i+1], level+1)
			sb.WriteString(",\n")
		}
		sb.WriteString(indent + "}")
	}
}

func (e *kyamlEncoder) Encode(writer io.Writer, node *Node) error {
	if node.Kind == ScalarNode && e.unwrapScalar {
		_, err := writer.Write([]byte(node.Value + "\n"))
		return err
	}
	var sb strings.Builder
	e.doEncode(&sb, node, 0)
	sb.WriteString("\n")
	_, err := writer.Write([]byte(sb.String()))
	return err
}
