	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if unicode.IsSpace(c) {
			p.pos++
		} else if c == '-' && p.pos+1 < len(p.s) && p.s[p.pos+1] == '-' {
			for p.pos < len(p.s) && p.s[p.pos] != '\n' {
				p.pos++
			}
		} else {
			return
		}
	}
}

func (p *luaParser) errorf(format string, args ...interface{}) error {
	return fmt.Errorf("lua: "+format+" at position %d", append(args, p.pos)...)
}

func (p *luaParser) parseValue() (*Node, error) {
	p.skipSpace()
	if p.pos >= len(p.s) {
		return nil, p.errorf("unexpected end of input")
	}
	c := p.s[p.pos]
	switch {
	case c == '{':
		return p.parseTable()
	case c == '"' || c == '\'':
		str, err := p.parseString()
		if err != nil {
			return nil, err
		}
		return &Node{Kind: ScalarNode, Tag: "!!str", Value: str}, nil
	case c == '[' && p.pos+1 < len(p.s) && p.s[p.pos+1] == '[':
		// long string
		end := strings.Index(string(p.s[p.pos+2:]), "]]")
		if end < 0 {
			return nil, p.errorf("unterminated long string")
		}
		str := string(p.s[p.pos+2 : p.pos+2+end])
		p.pos += 2 + end + 2
		return &Node{Kind: ScalarNode, Tag: "!!str", Value: strings.TrimPrefix(str, "\n")}, nil
	}
	// bare word: number, true, false, nil
	start := p.pos
	for p.pos < len(p.s) && (unicode.IsLetter(p.s[p.pos]) || unicode.IsDigit(p.s[p.pos]) || strings.ContainsRune("._+-xXeEabcdefABCDEF", p.s[p.pos])) {
		p.pos++
	}
	word := string(p.s[start:p.pos])
	if word == "" {
		return nil, p.errorf("unexpected character %q", c)
	}
	switch word {
	case "true", "false":
		return &Node{Kind: ScalarNode, Tag: "!!bool", Value: word}, nil
	case "nil":
		return &Node{Kind: ScalarNode, Tag: "!!null", Value: "null"}, nil
	}
	if _, err := strconv.ParseInt(word, 0, 64); err == nil {
		return &Node{Kind: ScalarNode, Tag: "!!int", Value: word}, nil
	}
	if f, err := strconv.ParseFloat(word, 64); err == nil {
		return &Node{Kind: ScalarNode, Tag: "!!float", Value: formatFloat(f)}, nil
	}
	return nil, p.errorf("unexpected token %q", word)
}

func (p *luaParser) parseString() (string, error) {
	quote := p.s[p.pos]
	p.pos++
	var sb strings.Builder
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == quote {
			p.pos++
			return sb.String(), nil
		}
		if c == '\\' && p.pos+1 < len(p.s) {
			p.pos++
			e := p.s[p.pos]
			switch e {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case '\\':
				sb.WriteByte('\\')
			case '"':
				sb.WriteByte('"')
			case '\'':
				sb.WriteByte('\'')
			case '0':
				sb.WriteByte(0)
			default:
				if unicode.IsDigit(e) {
					start := p.pos
					for p.pos < len(p.s) && p.pos-start < 3 && unicode.IsDigit(p.s[p.pos]) {
						p.pos++
					}
					n, _ := strconv.Atoi(string(p.s[start:p.pos]))
					sb.WriteRune(rune(n))
					continue
				}
				sb.WriteRune(e)
			}
			p.pos++
			continue
		}
		sb.WriteRune(c)
		p.pos++
	}
	return "", p.errorf("unterminated string")
}

func (p *luaParser) parseTable() (*Node, error) {
	p.pos++ // {
	var keyed [][2]*Node
	var positional []*Node
	for {
		p.skipSpace()
		if p.pos >= len(p.s) {
			return nil, p.errorf("unterminated table")
		}
		c := p.s[p.pos]
		if c == '}' {
			p.pos++
			break
		}
		if c == ',' || c == ';' {
			p.pos++
			continue
		}
		var key *Node
		if c == '[' && !(p.pos+1 < len(p.s) && p.s[p.pos+1] == '[') {
			p.pos++
			k, err := p.parseValue()
			if err != nil {
				return nil, err
			}
			p.skipSpace()
			if p.pos >= len(p.s) || p.s[p.pos] != ']' {
				return nil, p.errorf("expected ]")
			}
			p.pos++
			p.skipSpace()
			if p.pos >= len(p.s) || p.s[p.pos] != '=' {
				return nil, p.errorf("expected =")
			}
			p.pos++
			key = k
		} else if unicode.IsLetter(c) || c == '_' {
			// could be name = value, or a bare value like true/false/nil
			start := p.pos
			for p.pos < len(p.s) && (unicode.IsLetter(p.s[p.pos]) || unicode.IsDigit(p.s[p.pos]) || p.s[p.pos] == '_') {
				p.pos++
			}
			name := string(p.s[start:p.pos])
			save := p.pos
			p.skipSpace()
			if p.pos < len(p.s) && p.s[p.pos] == '=' && !(p.pos+1 < len(p.s) && p.s[p.pos+1] == '=') {
				p.pos++
				key = &Node{Kind: ScalarNode, Tag: "!!str", Value: name}
			} else {
				p.pos = start
				_ = save
			}
		}
		value, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		if key != nil {
			keyed = append(keyed, [2]*Node{key, value})
		} else {
			positional = append(positional, value)
		}
	}
	if len(keyed) == 0 {
		seq := &Node{Kind: SequenceNode, Tag: "!!seq"}
		for _, v := range positional {
			seq.AddChild(v)
		}
		return seq, nil
	}
	m := &Node{Kind: MappingNode, Tag: "!!map"}
	for i, v := range positional {
		m.AddKeyValueChild(createScalar("!!int", strconv.Itoa(i+1)), v)
	}
	for _, kv := range keyed {
		k := kv[0]
		if k.Kind == ScalarNode {
			k = &Node{Kind: ScalarNode, Tag: "!!str", Value: k.Value}
			if kv[0].Tag == "!!int" {
				k.Tag = "!!int"
			}
		}
		m.AddKeyValueChild(k, kv[1])
	}
	return m, nil
}
